INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('homelab-server-room', 'ghostty', 'The World Is Your Dashboard', 'The Server Room', 'One glowing panel per homelab node, pinned in your house or to housing furniture, with backlight and derez driven by live health checks.', 'Walk down an aisle of Tall Cabinets, each green with a btop or load readout. The NAS stops answering: its panel flickers amber, then red, and your pet swings toward it. Double-click flies you into an ssh session on that box. FC members holding a read-only key see the same wall when they walk in.', 'Health comes from a hidden capture session or agent probes (ping/tcp/http, node_exporter, incus list) via a new STATUS/EVENT frame, never from the panels, which sleep. Lua maps host to ok/warn/down and sets per-panel tint/backlight; move rez from global host.world_rez to per session in worldview.nelua. Placement uses house-id-aware anchors (see furniture-anchors). Drill-in reuses click focus, fly-in and per-host ssh profiles. Shared view uses read-only guest tokens (see over-the-shoulder-pets).', 'No depth test, so panels show through walls. A dozen live btop panels cost real FPS. Housing structs move between patches. Probe flaps cause alert fatigue; this is not a pager. Showing dashboards to an FC leaks hostnames and IPs.', 'homelab folks, sysadmins, SREs, sysadmin-heavy FCs', 1, 1, 0, 8, 'stretch', 'weeks', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ops-weather', 'ghostty', 'The World Is Your Dashboard', 'Ops Weather', 'Server health sets your local weather, client-side, so you feel an outage before you read about it.', 'All green: Fair Skies. Load climbs and clouds roll in. A failed CI run or degraded pool brings a thunderstorm, rain beads on your panels and a lightning pulse on the failing host''s backlight. Fix it and the sky clears.', 'Agent probe runner sends status over a new EVENT frame. New ops.lua maps states to per-territory weather ids with hysteresis. Shim adds SetWeatherOverride/ClearWeatherOverride beside GetEnvironment using the client-side WeatherManager path Brio and Weatherman use. M.lighting() already reads weather and rain, so tint and backlight follow for free; rain beads drawn in worldview.nelua.', 'Not every weather id is valid per territory; houses and duties have none or script their own. Hides real weather from fishers and gatherers, so it needs a toggle and guaranteed restore on unload, zone change and duty. Fights Brio or Weatherman.', 'sysadmins, homelab folks, SREs, streamers', 1, 1, 1, 8, 'stretch', 'days', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('homelab-minion-menagerie', 'ghostty', 'The World Is Your Dashboard', 'Homelab Minion Menagerie', 'Each server gets a client-side creature that follows you and acts out its health.', 'Five Proxmox nodes trail you through Gridania. One dozes, one sprints in circles at 100% CPU, one staggers under a smoking box at 95% disk, one plays dead. Click it and its tmux pane opens as a pet terminal.', 'Per-host health records over a new agent frame. Existing place_pet springs drive following. Ready fallback: ImGui billboard sprites on the same springs. Real version: client-side actors via ClientObjectManager or Brio IPC, with a BGCollision raycast for ground height and custom screen-space hit tests.', 'Client-spawned actors outside GPose are a known crash source and a grey area; they must despawn before zoning. Brio spawn outside GPose is uncertain. Many actors cost performance.', 'homelab folks, sysadmins, collectors', 1, 1, 0, 8, 'research', 'weeks', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('aetheryte-uplink', 'ghostty', 'The World Is Your Dashboard', 'Aetheryte Uplink', 'Aetherytes become status beacons for your hosts, and teleporting dissolves your terminals into aether that rebuilds on arrival.', 'Near an aetheryte, your hosts orbit the crystal as holographic rings with uptime and load, red if down. Cast Teleport and every panel streams into the loading screen, then rebuilds line by line at the destination, scrollback intact.', 'Shim adds FindNearest(Aetheryte) from IObjectTable. Lua reuses place_pet orbit math; worldview.nelua draws rings and halo. Host data from the shared probe/EVENT feed. Shim forwards Casting and BetweenAreas; worldview runs combat derez in reverse with a screen-space stream during loading and a line-reveal on arrival.', 'Halo is faked, not a real crystal tint; rings draw through geometry. Teleport detection is heuristic (Return, duty transitions). Needs a hide-hostnames option on stream.', 'homelab folks, sysadmins, anyone who teleports constantly', 1, 1, 0, 7, 'ready', 'days', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('airship-departure-board', 'ghostty', 'The World Is Your Dashboard', 'Airship Departure Board', 'CI/CD pipelines show as airship departures on a split-flap board at the landing or the FC workshop voyage console.', 'At the Limsa airship landing a split-flap board rattles to ''deploy/bazzite-sway: BOARDING'', then ''EN ROUTE'', then ''ARRIVED'' in green or ''LOST AT SEA'' in red with the failing step.', 'A world-pinned panel at per-territory coordinates running a `gh run list --json` TUI loop; flip transition per cell in core/render.nelua. Workshop console found by EventObj DataId via a small GetObject extension and pinned like a target anchor.', 'Thin novelty over a pinned dashboard. Repo names leak in public spots and on stream, so add redaction. Hardcoded coordinates break on zone changes.', 'developers, DevOps folks, FCs that hang out in the workshop', 1, 1, 0, 6, 'ready', 'days', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('commit-constellations', 'ghostty', 'The World Is Your Dashboard', 'Commit Constellations', 'On clear in-game nights, your git history hangs in the sky as constellations.', 'After dark, stars trace your commit graph: branches as trails, merges as clusters, today''s commits twinkling. Click one for its message and diffstat; double-click flies into `git show`. Day or clouds hide it.', 'Hidden agent session runs `git log --graph`. sky.lua lays nodes on a camera dome gated by GetEnvironment time, weather and rain. Stars drawn and hit-tested in worldview.nelua with the existing fly-in. Stretch: sky-only occlusion by sampling the depth buffer, as Pictomancy does.', 'Without depth occlusion stars draw over rooftops and the illusion breaks. Large graphs don''t read as constellations. Decorative and rarely looked at.', 'developers, open-source maintainers, screenshot hunters', 1, 1, 0, 6, 'stretch', 'weeks', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('town-criers', 'ghostty', 'The World Is Your Dashboard', 'Town Criers', 'The NPCs around you start calling out your logs in speech bubbles, so Ul''dah''s merchants hawk your warnings and a guard bellows your stack trace.', '`journalctl -f` runs on a minimized panel as you walk into Ul''dah''s Sapphire Avenue Exchange, and the merchants start calling out your log: ''Fresh from the kiln, nginx reloaded!'' A warning jitters in a yellow bubble over a Brass Blade. When the backup job fails the nearest guard bellows its stack trace in a big red battle-talk frame and every other bubble falls silent.', 'You pick one session as the crier source and keep it live with run_occluded. The core finds newly written lines from render-state dirty rows and extracts them with ghostty_formatter_format_buf (PLAIN, unwrapped), handing them to Lua, which sorts them by severity with your own patterns. A new shim call walks IObjectTable for EventNpc objects and guard BattleNpcs within about 25 yalms, never players, and returns position and height the way GetObject does today. Lua gives each line to the nearest free NPC with rate limits, and bubbles are ImGui rounded rects projected above each head through the view-projection the world panels already use. Severity picks speech, shaking shout or battle-talk styling, and scripts can shout on purpose with an `ffxiv;crier` APC.', 'Screenshots put hostnames and paths over NPC heads. Bubbles ignore depth, show through walls, and can overlap the NPCs'' real balloons. Busy cities have dozens of NPCs in range, so cap it at a handful. Players are excluded on purpose, so no one else''s character ever appears to say your text, even locally. Long lines must be trimmed and wrapped.', 'homelab folks, streamers, roleplayers with a sense of humour, anyone who tails logs while standing in a city', 1, 1, 0, 8, 'ready', 'days', 6, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('process-skyline', 'ghostty', 'The World Is Your Dashboard', 'Process Skyline', 'Your machine''s process table rises as a neon city on your island: memory sets a tower''s height, CPU lights its windows, and every fork raises a new building.', 'Fly over your island at night and a city of glowing towers stands in the meadow. Firefox is a 60-yalm skyscraper; `make -j32` throws up a district of cc1plus spires that rise, blaze and collapse within seconds; a zombie process stands as a grey ruin with a small green ghost drifting above it. Hover a tower for its name and PID, double-click it and `htop -p` opens on a panel at its base.', 'A helper on the agent host samples /proc every second and writes the changes as `ESC _ ffxiv;procs;<pid ppid rss cpu state comm> ESC \` into a hidden session kept live with run_occluded, caught through OPT_UNKNOWN_SEQUENCE with OPT_UNKNOWN_MAX_BYTES raised. Lua lays out a treemap by parent PID at a `here` anchor, so systemd slices become districts, and tower heights move on the same springs world.lua uses for pets. Towers are extruded quads through world_transform_vertices with windows as lit dotted rects, tinted by world.lighting(). Hovering uses ray-box tests built on the world_hit maths, and double-click opens a panel whose profile runs `htop -p <pid>`.', 'Hundreds of processes means hundreds of extruded ImGui boxes, so threads merge, small processes bucket into suburbs and draw calls are capped. Extrusions have no depth test unless routed through the depth pass, so the city shows through hills. Command lines leak tokens in argv, so arguments are hidden by default. On a busy desktop it''s just a Chrome city without a filter.', 'sysadmins, homelab folks, island decorators, people who like watching builds', 1, 1, 0, 9, 'stretch', 'weeks', 7, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('fishing-for-errors', 'ghostty', 'The World Is Your Dashboard', 'Fishing for Errors', 'Each new kind of error on your machines becomes a fish in the pond, and when you land a real catch it leaps out as a glowing hologram and goes into your Error Guide.', 'You sit on the Mist pier with a rod while journalctl churns on the host. You land a Merlthor Goby, and out of the water arcs a three-yalm coelacanth made of text: ''OOMKilled: jellyfin, first seen 02:14, 37 times'', fins flickering red. It''s a new species, so a NEW RECORD ribbon unfurls and it goes into your Error Guide beside last week''s big fish, ECONNRESET.', 'On the agent host, `xiv-pond` tails journalctl and app logs, collapses lines into signatures by stripping numbers, hex and paths (drain3-style templates), and writes `ESC _ ffxiv;fish;<sig>;<severity>;<count>;<text> ESC \` into a hidden session kept live with run_occluded. The core captures these through OPT_UNKNOWN_SEQUENCE and queues them. The shim adds a read of ConditionFlag.Fishing and an IChatGui.ChatMessage filter for your own catch message, and only after that message does Lua pop the most severe queued error. Its leap arc starts at a Raycast point ahead of your facing; severity and count set size and colour. The Error Guide is a ghostty.ui tab saved beside world-state.lua; double-click an entry to open its log on a panel.', 'It must never signal bites, hook timing or anything else about the real fish, which would be fishing assistance; it reacts only after the game has told you what you caught. Catch messages differ by client language. Bad templates turn one bug into a hundred species. Log lines carry tokens and hostnames, so redact on the host. It''s flavour, not monitoring, so keep a real alert alongside it.', 'homelab folks, anglers, SREs with a sense of humour', 1, 1, 0, 8, 'stretch', 'days', 8, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('sit-down-to-work', 'ghostty', 'Home Is Where the Shell Is', 'Sit Down to Work', 'Sit in any chair and your panels swing into a seated three-monitor arc while the camera settles into first person.', 'You /sit at your study desk. Wall panels spring into a curved arc at seated eye height, unfocused screens dim, the camera eases in. Stand up and everything springs back and your camera is restored.', 'Detect chair sit from ghostty.anim_state() Mode/ModeParam (or forward EmoteController id). Lua ''desk'' layout computes arc slots from seated position and heading and springs anchors there. Camera reuses the double-click Get/SetCameraState path, written once and restored once. Model M joins when it lands.', 'Tablet/typing pose overrides may knock you out of the chair, so disable them while seated. First-person near-plane clipping. Triggers in inns and public chairs unless limited to housing.', 'developers, roleplayers, cozy-workstation fans', 1, 1, 1, 8, 'ready', 'days', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('drive-in-cinema', 'ghostty', 'Home Is Where the Shell Is', 'Drive-In Cinema', 'A cinema-sized curved panel on your island or house wall, lit by the game''s sunset and rain, optionally broadcast read-only to opted-in friends.', 'At dusk you pin a huge screen over the island meadow and start asciinema. Its tint follows the sunset while rain streaks drift across. In the FC house, guests paste an invite code and watch the same live session at the same spot.', 'Solo works now: /term pin here plus lower pixels_per_yalm and a bigger curve radius; rain streaks from ghostty.env(); per-zone derez opt-out in worldview.nelua. Shared viewing (weeks, stretch): agent broadcast mode that streams output only and rejects DATA/OPEN/CLOSE, through a relay with per-invite keys, anchored by house ward/plot/room.', 'Truecolor text video repaints every cell and eats FPS; no kitty/sixel on the cell path. No depth, audio stays on the agent host. Agent token grants a shell today, so broadcast must be a separate read-only relay.', 'streamers, friend groups, FCs, event hosts, island decorators', 1, 1, 0, 8, 'ready', 'days', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('furniture-anchors', 'ghostty', 'Home Is Where the Shell Is', 'Mount to Furnishing', 'Pin terminals to real housing items, so a painting or bookshelf becomes a screen that moves with the furniture.', 'The painting in your apartment shows btop, the bookshelf `journalctl -f`. Drag the painting in the housing editor and the terminal slides along. It returns to the same frame on every visit.', 'Shim forwards HousingManager location (house/ward/plot/room) and IndoorTerritory furniture (item id, transform), as MakePlace and BDTH read. New ''furniture'' anchor in lua/world.lua matched by item id plus nearest transform, followed every frame, with per-item offset/size from a hand-made table. Replaces zone check with house-id check, since same-size houses share a territory id.', 'Panels show through walls and floors without depth; gate by room or height. Structs change with patches and load async. Identical adjacent items confuse matching. Frame fitting needs manual calibration.', 'housing decorators, homelab folks, roleplayers', 1, 1, 0, 7, 'stretch', 'days', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ghost-furniture-blueprints', 'ghostty', 'Home Is Where the Shell Is', 'Blueprints with Ghost Furniture', 'Share a terminal installation as a paste-able blueprint, or import a MakePlace layout, that projects wireframe outlines where the furniture goes.', 'Paste a ''Garlemald Ops Center'' blueprint in your Mist apartment and scanline boxes appear where cabinets belong. Place a matching item and it turns solid, its terminal booting with a warm-up flicker after you fill in hostnames and approve each command.', 'Builds on furniture-anchors. Lua serializes anchors plus item id and relative transform to base64 and imports MakePlace JSON. Nelua draws projected wireframe boxes sized from a per-item table. Match detection by item id within tolerance; template form in views.nelua; warm-up reuses rez.', 'Must never write furniture positions: show a match indicator and let the player place. Shared commands are an RCE vector, so never auto-run and hash-pin blueprints. Only transfers between identical house sizes.', 'housing designers, homelab community, content creators', 1, 1, 0, 7, 'stretch', 'weeks', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('homecoming-boot-sequence', 'ghostty', 'Home Is Where the Shell Is', 'Homecoming Boot Sequence', 'Arriving home boots your installation screen by screen and marks what printed while you were away.', 'As the loading screen fades, wall screens light up one by one while sessions reattach, with away-time lines tinted amber until you look. Step into the ward and the room folds into a single orbiting pet.', 'Zone-gated anchors and agent replay already exist. Add on_zone_changed in Lua with staggered boot timers, per-session rez in worldview.nelua, an unread row mark in render.nelua set on sleep, and fold-out to one pet when no anchor matches. Per-house layouts need the housing location hook.', 'Amber marking fails for tmux and full-screen apps. Mostly presentation over existing persistence. Staggered boot needs a skip.', 'daily players with long jobs, developers, crafters', 1, 1, 0, 6, 'ready', 'days', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('saucer-arcade-cabinets', 'ghostty', 'Home Is Where the Shell Is', 'Saucer Arcade Cabinets', 'Real terminal games run in glowing arcade cabinets along your house wall or beside the Gold Saucer''s own machines, with a high-score marquee only you can see.', 'A row of cabinets flickers on along the wall of your FC house: crawl, nethack, tint, and a bastet that picks the worst piece on purpose. Double-click one and the camera fills the screen with it. Beat your own best and the marquee bursts into Jumbo Cactpot-style fireworks while the cabinet''s light washes over the floor.', 'Each cabinet is a world panel pinned with `/term pin here` using a profile whose command is the game (crawl, nethack, bastet, tint, moon-buggy, ninvaders). A Lua `cabinet` place() shape tilts the panel back, adds a marquee strip and turns the backlight and light_intensity up. Double-click fly-in already exists. While a cabinet has focus, a keymap mode maps GamepadPressed buttons to arrows and letters through the key encoder with setopt_from_terminal, so DECCKM and kitty flags stay right. The core reads DATA_MODE for synchronized output (2026) and skips render_state_update between begin and end, so fast redraws never tear. The marquee flourish comes from a score-file watcher on the host that writes an `ffxiv;score` APC.', 'Dalamud can read gamepad state but can''t reliably swallow it, so the stick may still walk your character; keyboard or unused buttons are safer. In the crowded Gold Saucer panels without a working depth test cover other players in your view. 80x24 roguelikes need a readable pixels_per_yalm at fly-in size. Scores are local and easy to fake, which is fine because nothing is shared. It never touches MGP or the real minigames.', 'roguelike fans, Gold Saucer regulars, streamers, controller players', 1, 1, 0, 8, 'ready', 'days', 14, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ansi-gallery', 'ghostty', 'Home Is Where the Shell Is', 'The ANSI Gallery', 'Hang classic ANSI art on your house walls, and each piece paints itself at 2400 baud as you walk up to it.', 'You walk the upper floor of your apartment past framed 80-column pieces from 1990s art packs. Step within a few yalms of one and it blanks, then paints line by line at modem speed while a faint handshake plays from your desk speakers. A placard below shows title, artist, group and year from its SAUCE record, and next week, with no shell running at all, the wall is still there.', 'A host tool `ansi-hang` converts .ans files to VT (CP437 to Unicode, iCE colours to bright SGR backgrounds, width from SAUCE), runs the result through libghostty-vt once and saves a GHOSTSNP record with ghostty_snapshot_encode_alloc. In game each frame is a transport-less terminal restored with ghostty_snapshot_decoder_new_buf, so sleep, restarts and the 256 KiB replay ring don''t matter. A new lua/gallery.lua triggers the reveal from distance to ghostty.player(): clear the frame, then vt_write the stored VT at a per-frame byte budget (2400, 14400 or 57600 bps presets). Frames are world.lua pins, the placard is a small second panel, and world.lighting() tints them like any panel.', 'The renderer doesn''t draw blink, and the font needs full block, shade and box-drawing coverage at the right cell aspect or the art looks broken. 80x25 at a readable pixels_per_yalm takes a lot of wall. vt.h warns the snapshot API will change. Link to 16colo.rs rather than bundling art packs. Only you see the gallery, and without the depth test it can show through walls.', 'BBS-era and ANSI art fans, house decorators, retro-computing nerds, streamers', 1, 1, 0, 7, 'stretch', 'days', 15, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('tablet-prop-shell', 'ghostty', 'Body Language', 'The Tablet Prop Shows Your Shell', 'The tablet or book your character holds shows your live terminal on the game model itself.', 'Zoom in on the tomestone prop in your hands and htop updates on its screen, lit and depth-of-fielded by the game. GPose shots look like you''re on call from Eorzea.', 'Render the terminal to an offscreen texture (ITextureProvider draw-list wrap or D3D11 from Nelua), walk Character to weapon CharacterBase to Material texture, and swap its shader resource view each frame; a Penumbra mod gives a clean UV region. Cheap fallback: forward the hand bone world position and pin a small curved panel there.', 'Pointer-swapping game textures risks use-after-free crashes on zoning, redraws and Penumbra reloads. Shared texture shows your shell on every visible instance of that prop. Barely readable outside close-ups.', 'roleplayers, GPose photographers, streamers, sysadmins', 1, 1, 0, 9, 'research', 'weeks', 16, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('cast-bar-commands', 'ghostty', 'Body Language', 'Commands Cast Like Spells', 'Long-running commands get an FFXIV cast bar and casting pose, and the exit code plays out as a spell effect.', 'Run `cargo build --release`: your character raises their weapon into a cast loop and ''Casting: cargo build'' fills against its usual runtime. Ctrl+C shatters the bar with ''Interrupted''. Exit 0 plays a chime and /victory; failure throws sparks and an optional /facepalm only you see.', 'Agent parses OSC 133 C/D in the PTY stream and sends CMD_START/CMD_END frames; OSC 9;4 and 777 via libghostty callbacks as fallback. New lua/cast.lua keeps EWMA durations, a minimum threshold, and picks timelines played through anim_play. Cast bar and particles drawn with ImGui above the projected player. Exit 130 = interrupt. Chime needs a UIGlobals.PlaySoundEffect forward; VFX optional.', 'Needs shell integration on every host, tmux passthrough, and remote hooks over ssh. animation.lua''s pose guard must yield during casts. Cast timelines vary by job and weapon state. Never touch ActionManager or the real _CastBar.', 'developers, raiders, streamers', 1, 1, 1, 8, 'ready', 'days', 17, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('wardrobe-by-hostname', 'ghostty', 'Body Language', 'Wardrobe by Hostname', 'Glamourer IPC dresses you for the machine you''re on, so prod looks different from dev.', '`ssh prod-db-01` and you shimmer into a red hazard coat. Homelab tab: loungewear. A sudo prompt adds a crown until it closes. Exit and your glamour returns. Only you see it.', 'OSC 7 PWD_CHANGED and title give the host; forward on_host(id, host) to Lua. lua/wardrobe.lua maps globs to Glamourer designs for the focused session with ~1s debounce. Shim adds typed forwards for Glamourer apply/revert with a lock key. Sudo from a prompt regex on the cursor row.', 'Plain ssh without OSC 7 or titles gives nothing. Glamourer automation can fight the state; crash mid-apply leaves the outfit on. IPC signatures change, so pin the API version.', 'sysadmins, SREs, homelab folks, glamour enthusiasts', 1, 1, 0, 8, 'stretch', 'days', 18, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('emote-window-manager', 'ghostty', 'Body Language', 'Emotes as a Window Manager', '/beckon calls a panel over, /point focuses one, /shoo minimizes it, and bound emotes run commands after confirmation.', '/beckon and your pet springs to your shoulder. /point across the plaza focuses the panel you''re facing. /pray is bound to `terraform plan`; a glowing sigil at your feet asks you to confirm.', 'anim_state() already returns TimelineIds[0]; lua/emotes.lua maps emote timeline ids to actions on rising edge. Point picks the smallest angle off facing. Bound commands go through sendtext.nelua. Sigil is a projected ImGui ellipse. EmoteController.EmoteId forward as backup.', 'Pose guard eats emotes within 0.1s, so whitelist them. Confirmation is mandatory and binds default read-only. Slower than hotkeys; mostly for fun.', 'nerds, roleplayers, streamers', 1, 1, 0, 7, 'ready', 'days', 19, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('flow-state-limit-break', 'ghostty', 'Body Language', 'Flow-State Limit Break', 'Typing fast fills a client-side Limit Break gauge that fires a flourish at your peak.', 'A fast pace fills a three-segment LB gauge beside the dropdown with a rising aura. Hold 100 WPM for thirty seconds and your character plays a Limit Break just before `git push`. Stop and it drains.', 'Extend animation.lua typing energy with a rolling WPM window and three segments; ImGui gauge; payoff via anim_play of a job LB timeline the pose guard allows. Aura needs an actor VFX forward. Finger IK toward the Model M is dropped.', 'LB timelines are job-specific, some long and camera-bound. Rewards typing garbage into a shell. Aura VFX is stretch.', 'developers, streamers, speed typists', 1, 1, 0, 7, 'stretch', 'days', 20, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('gaze-and-presence', 'ghostty', 'Body Language', 'Gaze and Presence', 'Your character turns to the focused panel, startles when a background terminal rings, and dozes after long idle.', 'Switch tabs and you turn to face the new panel. A pet behind you rings: you flinch, turn and it pulses. After ten idle minutes you nod off holding the tablet until a keystroke jolts you awake.', 'Body turn exists (rate-limited set_rotation); trigger on focus change. Bell already bound in ghostty.nelua; emit on_bell to Lua for a startle timeline, turn and backlight pulse. Doze is an idle timer in animation.lua. Head look-at is research and deferred.', 'Merge with the in-progress visual bell rather than building twice. Only rotate while stationary. Look-at conflicts with posing plugins.', 'roleplayers, developers leaving builds running', 1, 1, 0, 6, 'stretch', 'days', 21, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('job-codex-terminals', 'ghostty', 'Body Language', 'Job Codex Terminals', 'The terminal''s physical form follows your job: codex pages for Scholar, a star globe for Astrologian, a wrist hologram for Machinist.', 'As Scholar your tmux windows are codex pages that flip when you switch windows. Swap to Astrologian and the same session becomes a turning sphere of panes. As Machinist it''s scanline hologram off your wrist.', 'Add ClassJob to GuObject. Lua style table per job selects frame, layout and pose. Nelua render variants: page-flip transition, spherical strip, rune/hologram overlays on existing scanline code. Page flip triggered by tmux window change. Bone anchoring is stretch; pet offset as fallback.', 'Per-job art and tuning is a large surface for a niche payoff; ship two or three. Bone positions vary by race and scale.', 'roleplayers, glamour enthusiasts, one-job mains, streamers', 1, 1, 0, 6, 'stretch', 'weeks', 22, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('moogle-mail', 'ghostty', 'Mail Call', 'Moogle Mail', 'When a background job, ssh session or tmux alert finishes, a delivery moogle only you can see hands you the result as a letter.', 'Crafting in Ul''dah, a moogle flaps in holding an envelope: ''rsync nas -> offsite: complete, kupo!''. Open it and a parchment pane shows the log tail; a failure arrives singed with the stderr. Unread letters collect in a mailbag badge at your hip, and a local chat line ''Your retainer has returned: exit 0, 3m41s'' restores the tab on click.', 'Triggers: agent EXIT for detached sessions, OSC 9/777 and bell callbacks, plus an agent-side NOTIFY frame so sleeping sessions don''t miss completions. mail.lua queues letters (id, title, last N lines), holds them until out of combat and duty, and persists with layout. Parchment theme in render.nelua; letter opens as a pet via place_pet. v1 moogle: ImGui billboard from a game icon texture on pet springs; optional local IChatGui.Print with a link payload. v2: client-side moogle actor (weeks, research).', 'Client-side actors crash on zoning and must never spawn in duties or cutscenes. Sprite draws through walls. Needs shell integration or wrappers. Stderr on screen can leak secrets on stream. Share one pipeline with the visual bell and taskbar.', 'homelab folks, crafters and gatherers, sysadmins, roleplayers', 1, 1, 1, 8, 'stretch', 'days', 23, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('loot-roll-job-results', 'ghostty', 'Mail Call', 'Loot-Roll Job Results', 'Jobs that finish mid-fight wait for combat to end, then drop at your feet as coffers you triage with Need, Greed or Pass.', '`term notify --after-combat make deploy` and you join a hunt train. The deploy finishes during an S-rank; a few seconds after combat a gold or red coffer drops with a chime. Need opens the log as a pet, Greed re-runs, Pass dismisses, all from the gamepad.', '`term notify` asks the agent via a control socket to OPEN a detached session; a PROTO_EVENT frame reports completion. Nelua queues while in_combat and releases after ~5s out. Lua ''drop'' anchor springs at your feet tinted by status. Need=ATTACH+make_pet, Greed=OPEN same argv, Pass=CLOSE via existing gesture code.', 'Combat flag flickers on trains; debounce. Skip bindings while the game''s NeedGreed addon is open. Greed re-running a deploy needs confirmation. ssh-launched jobs need the socket forwarded.', 'on-call sysadmins, developers with long CI, hunt train regulars', 1, 1, 0, 8, 'stretch', 'days', 24, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('cutscene-director', 'ghostty', 'Mail Call', 'Cutscene Director', 'Long commands finish like a story beat: letterbox bars, a camera move to the panel, and a Talk-style box reading the result.', 'Out of combat and standing still, a 4-minute build finishes. Bars slide in, the camera flies to the panel, and a Talk box with the tab as speaker reads ''Build hath completed. 4m12s''. Failures glitch red with an error toast. Any input cancels.', 'Shares the OSC 133 CMD_END frame with cast-bar-commands. Shim forwards BoundByDuty/WatchingCutscene/OccupiedInEvent and IToastGui. lua/director.lua sequences bars, camera (existing fly-in SetCameraState), box and return. Talk box is ImGui with game ULD textures, not the real AddonTalk.', 'Unprompted camera moves are jarring; abort on any input or condition change. Needs shell integration. Command names show on stream.', 'developers, sysadmins, streamers', 1, 1, 0, 8, 'stretch', 'days', 25, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('shell-tomestones', 'ghostty', 'Mail Call', 'Tomestones for Dead Shells', 'When a process dies its panel falls and leaves a tomestone on the spot, holding an exact snapshot of its last screen and scrollback.', 'The overnight `make -j32` in your workshop gets OOM-killed while you''re out gathering. When you come home a cracked slab stands where the panel was: ''make -j32, 1h14m, slain by signal 9''. Click it and the panel rises exactly as it died, scrollback and all, and `/tome raise` runs the command again in the same directory once you confirm.', 'On PROTO_EXIT, Session:mark_exited calls ghostty_snapshot_encode_alloc and writes a GHOSTSNP file beside world-state.lua with territory, pose, argv, cwd (DATA_PWD from OSC 7), title (DATA_TITLE), runtime and status; the agent already reports signals as 128+N. The panel derezzes into a drawn slab with the epitaph. Opening a stone builds a transport-less, read-only Session: ghostty_snapshot_decoder_new_buf, decode to decoder_ready so the final screen draws at once, then decoder_next brings older scrollback in as you scroll. A sleeping panel is detached and never sees EXIT, and the agent drops exited sessions, so the agent must hold a finished session until a client collects it, or link libghostty-vt itself (tools/build.sh already builds the host library) and snapshot at the moment of death. `/tome` is already an alias of `/term`, so `raise` is just a new subcommand.', 'Snapshots keep every secret that was on screen: per-profile opt-out, a retention cap and make_private file permissions. vt.h warns the API will change, so version the files and treat old ones as best effort. A graveyard of every `ls` would be silly, so only long runs or non-zero deaths get a stone.', 'homelab folks, anyone running long builds, on-call engineers reading a post-mortem', 1, 1, 0, 8, 'stretch', 'days', 26, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('pass-the-model-m', 'ghostty', 'Party Up', 'Pass the Model M', 'Pair-program with a party member in one tmux session, and the floating Model M flies to whoever holds the keys.', '/term pair and a curved panel appears between you and your friend with a driver badge in the driver''s job color. /term pass and the Model M springs across the gap and clacks in time with their keystrokes. Hand the keys back before the duty pops.', 'Agent already fans output to multiple attached clients. Add scoped guest tokens (session ids, ro/rw), a per-session driver, and DRIVER/PASS frames over a tailnet. Lua ''between'' anchor at the midpoint of player and friend; Model M springs between them on driver events. Each client poses only its own character.', 'Guest tokens are a new security boundary on a TLS-less agent, so tailnet only; rw means arbitrary code as the host user. Seeing your friend''s pose locally is unproven. Depends on the in-progress Model M.', 'developers, homelab friends in the same FC, collab streamers', 1, 1, 0, 8, 'stretch', 'weeks', 27, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('over-the-shoulder-pets', 'ghostty', 'Party Up', 'Over-the-Shoulder Pets', 'Friends who opt in make their orbiting pet terminal visible to you as a live read-only screen.', 'Target a friend who shared with you and a cyan outline marks their pet. Focus it and it resolves into their nethack run bobbing by their shoulder. An eye counter on their panel shows viewers; /term min darkens your view.', 'Read-only guest tokens scoped to one session plus a PAUSE frame on minimize; LIST already reports attached count. A second AgentClient per share with sessions flagged read-only. Invite carries name@world, matched against target/object table. Generalize the pet anchor to any entity_id.', 'Screens may show secrets; needs a clear broadcasting indicator. Skip or clear the 256 KiB replay for guests. Pet positions won''t line up exactly across clients.', 'streamers, roleplayers, FC mates, roguelike players', 1, 1, 0, 8, 'stretch', 'days', 28, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('static-war-room', 'ghostty', 'Party Up', 'Static War Room', 'Your static or FC gets one read-only strat board pinned at the same arena wall or FC house spot on every member''s client.', 'Zone into savage and a curved panel fades in on the north wall for all eight of you. The lead scrolls the strat doc and every copy scrolls. On a wipe, ''pull 47, 6:12'' appends to a progression log. It derezzes in combat and returns sharp on the wipe; later the wall switches to the crafters'' market dashboard.', 'World anchors are identical across instances; share as a save_state snippet restored when zone matches (FC house needs HousingManager id). Members attach with read-only guest tokens to a separate broadcast agent; one PTY means scroll sync is free. Shim forwards IDutyState start/wipe/complete; only the lead writes pull number and time. Leader ping is an EVENT frame that turns pets and highlights rows.', 'Never parse combat events or show timelines, which would make it a trigger tool. Lead''s agent dropping kills everyone''s board. Discord screen share covers the basics. Needs opacity for sightlines.', 'raiders, static leads, FC leadership, progression streamers', 1, 1, 0, 8, 'stretch', 'days', 29, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('guest-terminal-scenes', 'ghostty', 'Party Up', 'Allagan Terminal Scenes', 'RP hosts and venues run hackable in-world consoles backed by sandboxed scripts that invited players walk up to and use.', 'A GM pins a cyan Allagan-styled console in Castrum running a Lua text adventure. Invited players target it and type `override --sector 7`, their characters take the typing pose, everyone in the scene sees the same screen, and the GM replies live. A venue''s door kiosk runs a guestbook or drink menu the same way.', 'World anchor shared in the invite. Agent guest tokens with a forced command, like ssh ForceCommand: ATTACH only to the scene session, which runs in a container or restricted user. Client line-buffers and tags lines with name@world. Restricted session mode ignores OSC 52, notifications and hyperlinks. Theme palette plus a licensed fan font via the font atlas. Venue discovery by opt-in directory keyed on ward/plot is research.', 'Guests on a host is the core security problem: sandbox mandatory, rate caps, relay to hide IPs. Content sits outside SE moderation. Tiny audience, and non-plugin players see people typing at thin air.', 'roleplayers, RP venue hosts, event organizers, retro BBS nerds', 1, 1, 0, 8, 'stretch', 'days', 30, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('two-person-rule', 'ghostty', 'Party Up', 'Two-Person Rule by Emote', 'Gate a dangerous command behind signed approvals from party members, with /thumbsup as the ritual.', '`ghostty-gate -- incus delete nas-old --force` shows PENDING, the diff and two empty slots. An FC mate reads it and /thumbsup; their slot fills with name and job icon. The second approval flashes the panel and the command runs as everyone watches.', 'Authority lives in the agent: held command, quorum policy, approver public keys, ed25519 verify via vendored monocypher over (hash, nonce, expiry), then forkpty. Frames PENDING/APPROVE/APPROVED. Approver''s plugin watches only its own timeline for thumbsup (or /term approve), signs and sends over a guest connection.', 'Keys inside the game process are readable by other plugins; pitch as oops-prevention, not security, with a hardware-key option. Enforce minimum view time on the diff. Real crypto in a hobby agent needs care.', 'sysadmins, SREs, homelab collectives', 1, 1, 0, 8, 'stretch', 'weeks', 31, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('paged-mid-pull', 'ghostty', 'Party Up', 'Paged Mid-Pull', 'When your on-call healer gets paged, opted-in party members see a status line over them, so everyone knows why they went AFK.', 'Alertmanager fires and a red line appears over the healer: ''PAGED: disk 97% on nas01''. Their client rings and slides an incident terminal out of their pet slot. When it resolves the line turns green: ''back in 30s''.', 'Webhook receiver pushes a templated STATUS frame to the on-call''s agent. Party members hold status-only guest tokens. Map name@world to entity via IPartyList/object table and project an ImGui label above the head. Incident terminal reuses over-the-shoulder-pets.', 'Alert text leaks infra details; templated and redacted only. Ship as a mode of over-the-shoulder-pets and the bell, not a separate system. Hide labels in combat.', 'on-call engineers who raid, homelab statics', 1, 1, 0, 7, 'stretch', 'weeks', 32, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('linkpearl-bridge', 'ghostty', 'Party Up', 'Linkpearl Bridge', 'Bridge your FC''s Matrix or IRC room into a linkshell-styled terminal that echoes lines only into your local chat log.', 'An FC mate on a train types ''healer for maps at 8?'' in Matrix; it appears locally as [Bridge] in its own color. You reply in weechat. Nothing reaches game chat.', 'weechat script emits OSC 777 on activity; surface on_notify to Lua (or an agent NOTIFY frame). Shim forwards IChatGui.Print, which is local-only. Lua filters, colors and rate-limits with a clearly non-game tag.', 'Low novelty. Chat logger plugins capture external messages. A tag resembling [LS1] invites replying in game chat. Throttle to avoid flooding mid-duty.', 'FC officers, friends split between game and Matrix/IRC', 0, 1, 0, 5, 'stretch', 'days', 33, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('keystroke-colosseum', 'ghostty', 'Party Up', 'Keystroke Colosseum', 'Vimgolf duels fought on two towering arena panels, where every keystroke drains your own HP bar and the stands get instant replays.', 'Two FC members face off from opposite pillars in the house courtyard, each under a giant curved panel with the same broken CSV open in vim. Every keystroke knocks a sliver off an HP bar while the stands watch both screens live. Someone lands `:%s/;/,/g` and a floating screen rewinds the last ten seconds for everyone watching. The winner''s `:wq` passes the checker and the loser''s panel derezzes in a burst of rings.', 'A duel host on the agent opens both contestant sessions from a challenge file inside a container, counts DATA frames per session as keystrokes and runs a checker when the editor exits. Spectators ATTACH to both sessions, and the agent already fans output to every attached client (agent.nelua broadcast). Counts, clock and result arrive as `ffxiv;duel` APCs through OPT_UNKNOWN_SEQUENCE. Lua places both panels with `at` anchors from a shared arena origin and draws HP bars with new ui progress widgets. For instant replay each spectator''s client calls ghostty_snapshot_encode_buf once a second per duel terminal into a 15 s ring, and replay decodes each frame with ghostty_snapshot_decoder_decode into a scratch terminal on a replay panel. The derez reuses world.nelua''s rez effect and the `burst` bell preset.', 'Every attached client can write and there''s one token, so contestants need session-scoped tokens and spectators a read-only relay before this is safe. Snapshotting two terminals every second costs CPU and memory, so duel sessions use tiny scrollback. DATA frames don''t map one-to-one to keystrokes (escape sequences, key repeat), and paste must be disabled or scored by bytes. Contestants run code on the duel box, so the sandbox is mandatory. Players without the plugin see two people typing at thin air.', 'vim and emacs zealots, FC game nights, coding streamers, programming clubs', 1, 1, 0, 9, 'stretch', 'weeks', 34, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('bomb-defusal-night', 'ghostty', 'Party Up', 'Keep Typing and Nobody Derezzes', 'An asymmetric bomb-defusal party game: one player''s terminal holds the ticking bomb and everyone else''s holds a different page of the manual.', 'Your friend kneels at a sparking crate in the FC garden, the only one who can see the bomb terminal counting down from 03:00. You and two others each float a different manual page, one with wire tables, one with a `strings` dump, one with a regex for the serial, and you all yell clues over voice while she types `cut --wire 4`. Wrong wire: the bomb panel glitches, a red sonar ring bursts out of the crate on everyone''s screen, and the timer loses 30 seconds.', 'A game-master script on the host''s agent generates a puzzle seed, then opens one bomb session and one manual session per reader. Each invite carries a token scoped to one role''s session (read-write for the defuser, read-only for readers) and the crate''s anchor as a save_state snippet. The bomb TUI emits `ESC _ ffxiv;bomb;strike=1;t=150 ESC \`, which each client catches through OPT_UNKNOWN_SEQUENCE. Lua turns a strike into a red-tinted `sonar` bell style at the crate anchor, a world.nelua glitch on every panel and a short camera jitter through the existing GetCameraState/SetCameraState path. Detonation plays `burst` and derezzes every panel for a beat. Players talk only over voice or chat they type themselves.', 'Scoped and read-only tokens don''t exist yet; today''s single token grants a shell. Voice chat is effectively required. Puzzle design is real game-design work. The camera jitter needs a motion-sickness toggle and never fires InCombat or BoundByDuty. Guest sessions need the same sandboxing as any shared shell.', 'FC game nights, Keep Talking and Nobody Explodes fans, event hosts, streamers running viewer games', 1, 1, 0, 9, 'stretch', 'weeks', 35, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('queue-pop-eject', 'ghostty', 'Between Pulls', 'Queue Pop Eject', 'When the Duty Finder pops, whatever terminal owns your screen lets go, and an opt-in hook lets your desk react.', 'Thirty minutes into full-screen vim, the roulette pops. The panel peels off the camera into pet orbit, input returns to the game, and the tab counts down 45 seconds in red. On the host, a hook pauses music and renices your build.', 'Shim forwards IClientState.CfPop duty id via gu_event. Nelua clears world_full_id and stops capturing keyboard. Lua on_duty_pop picks pet or minimize and sets a countdown title cleared on WaitingForDutyFinder/BoundByDuty. Client-to-agent EVENT frame fork/execs an opt-in hook with only DUTY_ID in env.', 'Focus not released means you can''t press Commence; test hardest. CfPop may miss some queue types. Never auto-commit, never type into the PTY.', 'roulette grinders, developers who queue while working, streamers', 1, 1, 0, 7, 'stretch', 'days', 36, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('eorzea-cron', 'ghostty', 'Between Pulls', 'Eorzea Cron', 'A crontab on Eorzea time and weather that rings your pet terminal for timed nodes and weather spawns.', '`ecron ''zone=Ruby Sea weather=Thunder ET>=08:00'' notify ''Unspoiled node up''`. When the window opens, your pet panel rings. `ecron list` shows the next real-world time for every rule.', 'Host-side: ET = unix*3600/175, weather forecast from WeatherRate tables in a Lumina/Teamcraft dump, run by a systemd user timer. Notification writes BEL into the pet session; bell already bound. Optional amber pre-pulse via EVENT frame and a tint term in lighting().', 'WeatherRate tables change with patches. Island Sanctuary and Occult Crescent don''t follow simple rules. GatherBuddy already has alarms; the draw is shell scripting.', 'gatherers, mount and minion hunters, cron nerds', 0, 1, 0, 6, 'ready', 'days', 37, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('market-board-hover', 'ghostty', 'Between Pulls', 'Hover-to-Shell Market Board', 'Hovered items stream into your shell, so a Universalis CLI draws cross-world price history beside the retainer bell.', 'Open your retainer sell list and a panel beside the bell runs `mb watch`. Hover each item and it redraws a braille sparkline, cheapest listings across your DC and sales velocity. You still set every price by hand.', 'Shim forwards IGameGui.HoveredItemChanged and home DC via gu_event; Nelua debounces ~150ms and relays PROTO_EVENT. `term events --kind hover` feeds a shell script calling Universalis. Panel shown while OccupiedSummoningBell.', 'Not every row raises a tooltip. Universalis is crowd-sourced and rate-limited. Existing plugins already show prices; the draw is your own tooling. Never write prices back.', 'market board flippers, crafters, gil-makers', 1, 1, 0, 6, 'stretch', 'days', 38, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('xhb-shell-slots', 'ghostty', 'Between Pulls', 'Live Cross Hotbar Shell Slots', 'Hotbar slots bound to shell jobs show live progress rings, so a Steam Deck player can watch a build without opening a terminal.', 'Cross hotbar set 8 holds build, ci and backup. A ring fills as `term slot ci progress 0.6` updates; a failure turns the slot red and shakes it. Hold the slot to peek the log tail as a pet, release to send it back.', 'Shim forwards _ActionCross/_ActionBar slot rects plus RaptureHotbarModule and macro text. Nelua maps `/term focus <name>` slots (needs named sessions) and draws rings on the foreground list. `term slot` arrives as PROTO_EVENT. Hold detection from GamepadDown plus active set.', 'HUD layouts, WXHB and scale plugins break slot rects. Macro fires on press before hold. Niche for the effort.', 'Steam Deck and controller players, couch homelabbers', 0, 1, 0, 6, 'stretch', 'days', 39, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('echo-replays', 'ghostty', 'Showtime', 'Echo Replays', 'Replay old terminal sessions as ghost holograms in the exact spot they happened, framed like the game''s Echo visions.', 'Walk back to where you fixed the homelab at 3am and type /term echo. The screen flashes white and a translucent cyan panel rezzes in, replaying the session at real speed. Triggers scrub; /term echo loop 30 loops a stretch for stream.', 'Agent records asciicast-style timestamped output and resizes plus territory and coordinates; REC_LIST/REC_OPEN/REC_CHUNK frames. Replay transport feeds Session:feed on a clock, reusing TermView and rendering. Keyframes every ~5s via libghostty formatter for seeking. Flash, rez-in and ghost tint reuse existing effects.', 'Recordings keep every token and hostname printed: retention limits, per-profile opt-out, playback redaction. Disk growth. Keyframes may not restore every mode exactly.', 'roleplayers, streamers, developers', 1, 1, 1, 8, 'ready', 'days', 40, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('aetherial-visualizer', 'ghostty', 'Showtime', 'Aetherial Visualizer', 'Audio from a terminal''s player makes panel backlights and pet terminals pulse to the beat.', 'Start ncmpcpp and panel backlights pulse on the bass, pets kick on their springs, and bars mode raises columns under the panel.', 'Agent matches PipeWire nodes to the PTY process tree, captures with pw-record, runs a windowed FFT, and sends 8-16 bands as a BANDS frame at 30-60Hz. Lua modulates backlight and adds pet spring impulses; bars are extra projected quads.', 'Audio over ssh plays remotely and can''t be captured. Crowds see nothing unless synced. Needs intensity cap and photosensitivity toggle. Flatpak and pulse-compat matching is fragile.', 'streamers, roleplayers, venue and club hosts', 1, 1, 0, 7, 'stretch', 'weeks', 41, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('stream-redaction', 'ghostty', 'Showtime', 'Stream Redaction Mode', 'Streamer mode seals password prompts and secret-looking text on every panel before it''s drawn, with an optional Eorzean-script skin for looks.', 'Panels keep layout, color and motion, but password prompts, API tokens and IPs become sealed crystal tiles. Panels marked public stay readable. The Eorzean-script skin is style only, since fans can read it.', 'Agent checks tcgetattr after reads and sends SECRET_INPUT when ECHO is off with ICANON. lua/redact.lua regexes dirty rows (ghp_, AKIA, JWT, IPs, *_TOKEN=, key headers); render.nelua draws crystal quads over returned ranges on every surface including the first frame after wake. Cipher skin is a second font handle. Public flag persisted with layout.', 'ECHO signal fails inside tmux and ssh, leaving only regex; a missed pattern leaks. Masking must never lag a frame. No hold-to-peek, since OBS captures it. Fan font licensing.', 'streamers, sysadmins, homelab folks', 1, 1, 0, 6, 'ready', 'days', 42, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('credits-roll', 'ghostty', 'Showtime', 'Duty Complete Credits Roll', 'Clearing a duty rolls Final Fantasy-style credits across your pet terminals, written from your session.', 'After the clear, the camera orbits your character while pets scroll ''Directed by <alias>'', ''Wipes: 14'', ''Commands run between pulls: 212'', ''Longest command: cargo build, 6m03s'', with party members as job icons. Any input skips.', 'Shim forwards IDutyState and IPartyList ClassJob ids; icons from ITextureProvider. lua/credits.lua builds text from Enter counts and CMD_END durations and feeds generated VT into a local session. Orbit via SetCameraState spring, gated on WatchingCutscene.', 'Must not cover the loot window or exit prompt. Default alias must not leak hostname. Duration stats need OSC 133.', 'raiders, streamers, developers', 1, 1, 0, 6, 'ready', 'days', 43, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('obs-scene-conductor', 'ghostty', 'Showtime', 'OBS Scene Conductor', 'Duty and panel events switch OBS scenes, and stream triggers fire whitelisted cosmetic effects in game.', 'Starting a duty switches to your Raid scene and ducks terminal audio; flying a panel full screen switches to Code. Channel-point redeems via Streamer.bot fire a derez burst or spin your pets, and a camera swoop only out of combat.', 'Shim forwards IDutyState and TerritoryChanged; core sends EVENT frames to the agent. A small sidecar speaks obs-websocket v5 and relays inbound events as EFFECT frames. lua/effects.lua maps them to whitelisted calls gated on InCombat and BoundByDuty.', 'Viewer camera control is risky if a gate fails. The agent holds another credential and any network exposure widens a shell-granting service. Frame-locked browser overlays are dropped.', 'streamers', 0, 1, 0, 6, 'stretch', 'weeks', 44, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('gpose-terminal-studio', 'ghostty', 'Showtime', 'GPose Terminal Studio', 'Terminals stay in group pose as frozen props you can scroll back, move, tilt or attach to a character''s hand.', 'In GPose each panel freezes instead of vanishing. Scroll to an earlier moment, drag or tilt it, or attach it to an actor''s hand bone so your character holds the real screen.', 'Set DisableGposeUiHide; confirm draw callbacks and ViewProjection follow the GPose camera. Freeze via Session:sleep. Drag/rotate gizmo on world_hit/world_unproject. Hand attach via a GetBone shim forward reading hkaPose and a Lua ''bone'' anchor.', 'ImGui overlays never get game DoF or lighting and cover other actors. The game''s screenshot likely excludes Dalamud''s layer. Bone math breaks on ClientStructs changes.', 'GPose photographers, roleplayers, streamers', 1, 1, 0, 6, 'research', 'weeks', 45, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('glyphfall', 'ghostty', 'Showtime', 'Glyphfall', 'Lines that scroll off a world panel fall out of it as real letters that splash in rain, drift in snow and pile up at your feet until you clear the screen.', 'Run `find / 2>/dev/null` on a panel in Ishgard and the lines tumble off its top edge as glowing letters, drifting down through the snow into banks around your boots. In La Noscea rain they splash and fizzle, and in a Thanalan dust storm they blow sideways off the cliff. Type `clear` and a gust sweeps the whole pile away in a derez shimmer.', 'The core keeps a tracked grid ref on the top row of the active area; after new output, that ref''s SCREEN position against DATA_SCROLLBACK_ROWS says how many rows just scrolled off, which keeps working once the 10,000-line scrollback is full and the row count stops growing. Each new history row is read back with ghostty_terminal_grid_ref at a HISTORY point plus ghostty_grid_ref_graphemes and ghostty_grid_ref_style, and every non-blank glyph spawns a particle at its cell''s spot on the panel''s top edge. One Raycast per batch finds the ground, a cheap integrator moves the letters, and they''re drawn with PushWorldFont AddText. A new lua/glyphfall.lua turns the ghostty.env() weather id into behaviour: rain splashes and fades, snow drifts and piles, wind and sand push sideways. An empty viewport right after output triggers the sweep.', 'Fast output means thousands of letters a second, so it needs a hard particle cap, sampling of every Nth row and whole-line strips as a fallback. ImGui letters ignore depth unless routed through the depth pass, so piles show through walls. Alt-screen TUIs never scroll into history, so htop never snows. Weather ids need a hand-made table, and house interiors have no weather. It''s decoration, not a log.', 'streamers, screenshot hunters, people who run `yes` for fun', 1, 1, 0, 8, 'ready', 'days', 46, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('magic-lantern-projector', 'ghostty', 'Showtime', 'Magic Lantern', 'Aim a panel like a projector and its terminal, text and kitty images alike, is thrown onto whatever it hits: walls, furniture, aetherytes and the people walking through the beam.', 'Set a projector at the back of the FC house and run `mpv --vo=kitty trailer.mkv`: the film leaves the glass, covers the far wall, bends over a bookshelf and plays across your own back when you walk through the beam. On a quiet night in Limsa you aim another at the Aetheryte Plaza crystal and htop wraps around its facets. Swing the projector and the image swings with it.', 'The projector''s terminal is drawn into a texture (ITextureProvider.CreateDrawListTexture from the shim, or a D3D11 render target on the device GuSceneDepth.ui_device already exposes), with kitty images uploaded through the decode path Kitty Graphics Tapestries needs: GHOSTTY_SYS_OPT_DECODE_PNG, re-uploaded when GHOSTTY_KITTY_IMAGE_DATA_GENERATION changes. A full-screen quad then runs through the same draw-list callbacks as core/depthpass.nelua with a sibling of panel_depth.hlsl: it rebuilds each pixel''s world position from the reversed-Z SceneDepth and the inverse view-projection rows that cbuffer already carries, moves it into the projector''s frustum from its world.place() pose, and samples the texture with cone falloff and a facing term from depth derivatives. app/lights.nelua tints the panel''s Scene.Light toward the frame''s average colour, so the room''s real lighting brightens too. Alt-drag and Shift-snap aim it.', 'It adds colour over a finished frame; it isn''t real lighting, and it lands behind water, glass and hair that don''t write depth. Render-to-texture from the native core is unproven, and the depth path has only been checked in a Wine/DXVK probe. Kitty''s shm medium doesn''t cross the TCP agent, so video arrives as base64 frames: cap resolution and FPS. Flashing video needs a photosensitivity switch. Only you and your stream see it.', 'venue owners, FC movie nights, GPose photographers, streamers, VJs', 1, 1, 1, 10, 'research', 'weeks', 47, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('shader-sky', 'ghostty', 'Showtime', 'Paint the Sky', 'Pipe a pixel shader from your shell and it replaces the sky over Eorzea on your screen only, fed by Eorzea time, the weather and where your camera points.', 'On the Mist lighthouse at dusk you run `aether-sky plasma.hlsl` and the sunset dissolves into a slow demoscene plasma that stops cleanly at rooftops, masts and tree lines. When rain rolls in, the plasma cools to blue and ripples. Swap in a raymarched tunnel and it turns with your camera, so the town seems to sit at the mouth of a wormhole; `aether-sky off` brings the real sky back.', 'A shell helper compiles the HLSL on the Linux host with the same pinned vkd3d-compiler tools/build-shaders.lua uses, so nothing compiles inside Wine, and sends the DXBC as `ESC _ ffxiv;sky;<base64> ESC \`, caught through OPT_UNKNOWN_SEQUENCE with OPT_UNKNOWN_MAX_BYTES and OPT_APC_MAX_BYTES raised for the payload. The core checks the DXBC header, creates the pixel shader on GuSceneDepth.ui_device, and adds one full-screen quad at the start of the background draw list through the core/depthpass.nelua callback path, with SceneDepth still bound at t1. The shader keeps only pixels whose reversed-Z depth is 0 (the infinite far plane) and discards the rest. A fixed cbuffer supplies day seconds, rain and weather id from ghostty.env(), the camera-relative inverse view-projection rows panel_depth.hlsl already builds rays from, the depth sizes and the session''s bell count.', 'Nobody has checked that the sky really reads depth 0; `/term depth show` comes first. A painted sky hides the sun, moon and clouds, and effects that don''t write depth leave odd edges. Shader bytecode from a shell runs on your GPU inside the game process, where a heavy shader can stall frames or remove the device, so accept it only from the focused session, time-box it, and ask before loading one from a remote host. Only you and your stream see it.', 'demosceners, shader artists, streamers, screenshot and GPose folks, venue hosts', 1, 1, 0, 9, 'research', 'weeks', 48, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('venue-lighting-desk', 'ghostty', 'Showtime', 'The Lighting Desk', 'A tracker or cue sheet in a terminal drives a rig of real in-game lights channel by channel, and opted-in patrons at the venue see the same show on their own clients.', 'On the stage panel you press play in Furnace: the kick slams a red light up from the floorboards, hi-hats strobe cold blue across the beams, and the lead arpeggio walks a violet spot along the wall, throwing your shadow with it. Mute channel 3 and its spot goes dark mid-bar. The dancer beside you joined the venue''s desk at the door, so she /cheers at the same blackout you just saw.', 'On the host, `ffxiv-lightd` reads the tracker''s MIDI out (ALSA sequencer or JACK) or a cue script and prints `ESC _ ffxiv;cue;ch=1;n=36;v=127;t=183.250 ESC \` into a desk session; the APCs never touch the grid and arrive through OPT_UNKNOWN_SEQUENCE only on sessions flagged as desks. A new lua/lightrig.lua maps channels to fixtures (offset from a pinned `here` anchor, colour, range, shadows, attack and decay), and app/lights.nelua grows from one light per panel into a capped pool on the same LightCreate/LightUpdate calls (HostApi.cs:400-451). Patrons ATTACH to the desk session: the agent already broadcasts output to every attached client and replays 256 KiB on join. Cues carry desk time, and a new agent timestamp frame lets clients schedule against a playout buffer of about 150 ms. Fixture offsets hang off the house''s ward, plot and room, which an in-game MCP server plugin can already read through HousingManager.', 'Every attached client can write today and there''s a single token, so patrons need a read-only broadcast relay first. Nobody knows how many Scene.Lights the renderer tolerates, so cap the pool at 8-16. Strobes need a hard rate limit and a per-patron intensity slider. Sync is only as good as each patron''s latency, and the music reaches them over Discord or Twitch with its own drift. Players without the plugin see a normal club. Aetherial Visualizer pulses panels from local audio; this is an authored, shared show.', 'chiptune and tracker musicians, DJs, dance club and venue owners, event hosts', 1, 1, 0, 9, 'stretch', 'weeks', 49, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('algorave-conductor', 'ghostty', 'Showtime', 'Algorave Conductor', 'Live-code music in a terminal and your character conducts at the exact tempo, while the pattern that just played flares on the panel behind you.', 'In your FC house you evaluate `d1 $ sound "bd*2 [~ hh] sn"` in Neovim and your character lifts a hand and beats time at 128 BPM. Every drum hit makes the `d1` line flash on the big curved panel behind you, and `d2`''s pads bloom teal half a bar later. Type `hush` and your arms drop as the room goes quiet.', 'TidalCycles and Strudel''s desktop setups send every event to SuperDirt as OSC over UDP. A host-side `ffxiv-tidal` reads a mirrored copy of that stream (orbit, cps, cycle, delta, sound) and prints `ffxiv;beat` APCs into a hidden session kept live with run_occluded, caught through OPT_UNKNOWN_SEQUENCE. A new lua/conductor.lua converts cps to BPM and drives ghostty.anim_speed on a pose from animation.lua picked per tempo band, with anim_play flourishes on section changes, all client-side like the existing typing loop. For the flash it finds the row holding `d1 $` on the editor panel with ghostty_search_* and GHOSTTY_SEARCH_DATA_VIEWPORT_MATCHES, then glows that rect in the orbit''s colour for the event''s delta. Sonic Pi works the same way through its OSC cue log.', 'Poses played far off their normal speed look silly, so stick to tempo bands. Tidal doesn''t report source spans, so matching an event to its line is a guess; Strudel''s events do carry them. The UDP mirror must never add latency to SuperDirt. Animation changes are client-side but stay off in duties. Nobody in the venue sees the code unless they watch your stream.', 'live coders, algorave and venue hosts, music streamers, roleplayers', 1, 1, 0, 8, 'stretch', 'days', 50, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('cracktro-login', 'ghostty', 'Showtime', 'Cracktro Login', 'Launching the game plays a 1990s cracktro over the title screen: a sine-scrolling greetz list, copper bars, a starfield and a MOD tune from your desk speakers.', 'Before you press Start, the logo sky fills with copper bars and a chrome sine scroller: ''GREETZ TO <your static> ... <your FC> ... CODE BY YOU''. A four-channel module thumps from your desk speakers. Hit any key and the intro shatters into the scanline derez, leaving the title menu.', 'The intro is an ordinary terminal program on the agent host: `cracktro` draws truecolor half-block frames (kitty graphics once Kitty Graphics Tapestries lands) and plays the .mod with openmpt123. The core opens it at the title screen, when host.nelua reports not in world and IClientState.IsLoggedIn is false, as a borderless full-screen popup terminal. It holds render_state_update while DATA_MODE shows synchronized output (2026), so each frame presents whole. Greetz come from greetz.txt plus an FC name and friend names cached at your last logout (ClientStructs InfoProxyFriendList; fields to verify). Any key or pad button ends it with the existing derez, once per launch, skippable in settings.', 'Full-screen half-blocks at speed are heavy on the per-glyph ImDrawList path. render.nelua doesn''t honour mode 2026 today. If the agent isn''t reachable before login it must show nothing and never delay the menu. Friends'' names on a streamed title screen are a leak, so friend greetz are opt-in. Copper bars need a calm preset, and MOD files carry their own licences.', 'demosceners, retro-computing fans, streamers, FCs with a sense of humour', 0, 1, 0, 8, 'stretch', 'days', 51, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('aetheryte-ssh-network', 'ghostty', 'Nerd Power Tools', 'Aetheryte Network for SSH', 'Your ~/.ssh/config becomes a teleport menu, and connecting casts a client-side teleport that lands a shell beside you.', 'ctrl+t opens an Aetheryte-style host list grouped by ProxyJump chain, RTT as cost, unknown hosts unattuned. Pick one: your character casts, the current panel derezzes, and a pet lands at the remote prompt. Expand a host to attach its tmux sessions as shards.', 'New Nelua primitive ghostty.run(argv, cb) capture session plus ghostty.command(text). Agent-host helper prints TSV from `ssh -G`, `ssh-keygen -F` and a TCP connect time; tmux shards via ControlMaster only on expand. Lua menu in core/ui.nelua table widget; anim_play cast timeline, derez, open `ssh -t host` and pin as pet. No shim changes.', 'Can''t hijack the real Teleport keybind. Probes can trip 2FA, fail2ban or slow DNS, so TCP connect only. Cast timeline must not lock movement. Real teleport VFX is research.', 'sysadmins, homelab folks, anyone with too many SSH hosts', 1, 1, 1, 8, 'ready', 'days', 52, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('deploy-raid-pull', 'ghostty', 'Nerd Power Tools', 'Deploy as a Raid Pull', 'CI jobs show as party frames, and a production deploy needs a charged Limit Break hold before Enter goes through.', 'The GitHub Actions run shows as party frames: HP is steps done, cast bar the current step, enrage the timeout, debuff icons on failures that open `gh run view --log-failed`. Type `terraform apply` and Enter becomes a three-segment LB gauge you hold to fill. Green runs play victory.', 'Capture session polls `gh run list/view --json` every ~10s to TSV; frames drawn with new ui.* progress widgets. ghostty.input_line(session) reads cursor-row cells with SEMANTIC_CONTENT==INPUT (OSC 133). keymap.lua swallows Enter on guarded patterns until the hold fills, then sends \r. Victory via anim_play, skipped while BoundByDuty.', 'A speed bump, not a safety control: needs OSC 133 and is bypassed from any other terminal. Swallowing Enter needs a visible reason and Esc to cancel. gh rate limits.', 'developers, DevOps engineers, raiders', 0, 1, 0, 8, 'stretch', 'days', 53, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('parse-your-shell', 'ghostty', 'Nerd Power Tools', 'Parse Your Shell', 'An ACT-style meter ranks your session''s commands by time and colors each like an FFLogs parse.', 'Your slowest `nix build` is grey, a quick test run purple, your best `make check` gold. Failed commands get death markers. Click a row to jump to that prompt''s output; copy a text summary to paste wherever you like.', 'Agent parses OSC 133 with libghostty''s standalone OSC parser and timestamps an EVENT frame delivered even to detached sessions. Lua keeps per-command history and percentiles and draws colored bars. Jump scans rows for SEMANTIC_PROMPT. Summary via SetClipboardText only.', 'Needs OSC 133 through tmux and ssh. Scrollback lost on sleep/restart. Percentiles mean little with few runs. No automated chat sends.', 'raiders who are developers, performance nerds', 0, 1, 0, 7, 'stretch', 'days', 54, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('git-status-buffs', 'ghostty', 'Nerd Power Tools', 'Git Status as Buffs and Debuffs', 'Each pet terminal gets a mob-style nameplate with its branch and a buff row for repo state.', 'Your pet reads ''feature/observatory <bazzite-sway>'' with the last exit code as its level. Below: a stack count of dirty files, ahead/behind arrows, a crystal per stash, and a pulsing Doom icon during a merge conflict. Click Doom to type `git status`.', 'precmd hook runs `git status --porcelain=v2 --branch` with a timeout and emits a private OSC user var. Wire UNKNOWN_SEQUENCE in session.nelua to Lua on_uservar. worldview projects the nameplate above each pet via a world.nameplate(id) hook; click uses /term type.', 'Slow git in big repos adds prompt lag. Check whether OSC 1337 SetUserVar reaches the callback; else use an unused OSC number. Overlapping nameplates, stale state while asleep.', 'developers who live in git', 1, 1, 0, 6, 'ready', 'days', 55, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('failing-suite-extreme', 'ghostty', 'Nerd Power Tools', 'The Failing Suite (Extreme)', 'Target a striking dummy and your test suite becomes a trial boss: failing tests are its HP, compiler errors pull as adds on an enemy list, and all green plays Duty Complete.', 'You target the dummy in your FC workshop and type `/term trial pytest`. Its nameplate becomes ''The Failing Suite (Extreme)'', a boss bar reads 28 failing of 240, and the worst traceback towers behind it on a hologram panel like a primal. Save a fix and yellow ''+17'' numbers fly off the dummy while ''E0308 mismatched types: loader.rs'' aggros onto the enemy list; click it and nvim jumps to line 214. At zero the hologram shatters in a scanline derez and a Duty Complete banner sweeps the screen.', 'A host wrapper runs the suite and the checker under watchexec, reads JUnit or JSON output (`cargo check --message-format=json`, `tsc --watch`, `ruff --output-format json`) and prints `ESC _ ffxiv;suite;pass=..;fail=..;fixed=..;top=<test> ESC \` plus `ffxiv;diag;<json>` snapshots, caught through OPT_UNKNOWN_SEQUENCE (session.nelua sets neither option today). A new lua/trial.lua diffs snapshots into damage, new adds and kills, ranks adds with primary errors first, and keeps a local hunt log. The hologram is a world panel on the existing `target` anchor raised above the dummy, running `less +G` on the top failure. Boss bar, enemy list and banner are ImGui in chrome.nelua''s glass style; numbers go through a new shim call to IFlyTextGui.AddFlyText, and the nameplate is renamed in INamePlateGui.OnNamePlateUpdate only for a BattleNpc whose BNpcName is a striking dummy. Clicking an add writes `goto file:line` to the wrapper, which calls `nvim --server $NVIM --remote-send`.', 'Hitting the dummy puts you in combat, and combat derezzes everything, so this is a boss you watch, not one you fight. AddFlyText may only attach to your own character, so the dummy''s numbers might have to be drawn by the plugin. One refactor can spawn 300 adds, so cap and roll them up, and crediting a root-cause fix with its cascade is a heuristic. Giant tracebacks carry paths and secrets. It''s gated to dummies outside duties so it never looks like a real combat HUD.', 'developers who practise TDD, compiled and typed language folks, streamers who code, raiders with a CI habit', 1, 1, 1, 9, 'stretch', 'days', 56, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('debugger-trial-arena', 'ghostty', 'Nerd Power Tools', 'Debugger Trial: The Floor Is the Source File', 'Attach a DAP debugger and your source file unrolls across the ground as a boss arena: breakpoints are AoE telegraphs, the current line is a tank-buster marker and an uncaught exception is a wipe.', '`/term trial python -m pytest -x` and the arena rezzes around your feet: `solver.py` lies flat as the floor, breakpoint lines ringed in orange telegraphs, the call stack standing at the north edge like a boss timeline. F10 slides the glowing marker down the floor, and changed locals pop out of their lines as flytext: ''retries 2 -> 3''. Step into a call and the floor derezzes and rebuilds as `http.py`. Then the exception: the screen flashes red, ''ENRAGE: KeyError token'' crawls across the arena, and the frame that threw glows.', 'A host-side `ghostty-dap` runs as a small REPL in its own session and speaks DAP to debugpy, lldb-dap or `dlv dap`. On every `stopped` event it writes `ESC _ ffxiv;dap;<base64 JSON> ESC \` with file, line, breakpoints, stack and changed variables, forwarded to a new Lua hook through OPT_UNKNOWN_SEQUENCE. The floor is a second world panel placed with pitch -90 through the placement table, running `bat --paging=never` on the file; world_axes and the depth-pass basis already tilt with pitch. Telegraphs reuse the ring renderer in app/bell.nelua projected onto the floor''s rows, and the stack is a pet panel. A new keymap action sends F5, F9, F10 and F11 to the ghostty-dap session whichever panel has focus. The arena refuses to open while BoundByDuty and derezzes in combat like every panel.', 'A floor-sized panel adds real overdraw, and no panel has been laid at -90 degrees yet, so it floats slightly above the ground to avoid z-fighting. Reading text at a steep camera angle is the hard part, and first person may be the only readable view. APC through tmux needs passthrough. Every DAP adapter has quirks. It stays a toy until conditional breakpoints and watches exist.', 'developers who live in debuggers, raiders, live-coding streamers', 1, 1, 0, 9, 'stretch', 'weeks', 57, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('bisect-heaven-on-high', 'ghostty', 'Nerd Power Tools', 'Git Bisect, Heaven-on-High', '`git bisect` becomes a deep-dungeon descent, one floor per step, ending in a boss room where the first bad commit is waiting.', '`git bisect start HEAD v1.2` and a floor counter drops in over your pet terminal: ''Heaven-on-High, Floor 1 of ~7, 97 commits remain''. Mark a commit good and a Cairn of Passage lights blue as you sink a floor; bad springs a trap; `skip` spends a Pomander of Safety. Under `git bisect run` the floors flash past in a few breaths. Floor 7 locks shut and a boss nameplate reads ''c41e9d0: hot-swap loader cleanup, 3 weeks ago'', with its diff on the panel behind it.', 'A precmd hook, plus a `git` wrapper for run mode, checks for .git/BISECT_LOG. When it''s there, the hook takes bisect_nr and bisect_steps from `git rev-list --bisect-vars` over the bad and good refs, reads the last verdict from `git bisect log`, and spots the `# first bad commit:` line that log gains when the hunt ends. It prints `ffxiv;bisect;floor=..;left=..;verdict=..` as an APC, caught through OPT_UNKNOWN_SEQUENCE (the Stage Directions plumbing). A new lua/bisect.lua maps good, bad and skip to cairn, trap and pomander effects built from bell.lua rings and the worldview glitch and derez, and on the boss floor pins a panel running `git show --stat` beside the pet.', 'It''s a theme on top of real work. The precmd hook never fires inside `git bisect run`, so run mode depends on the wrapper. Floor estimates wobble with skips and merges. Deep Dungeon art is limited to game icons through ITextureProvider.GetFromGameIcon and colour. APC through tmux needs passthrough.', 'developers hunting regressions, Deep Dungeon grinders', 1, 1, 0, 8, 'ready', 'days', 58, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('blue-magic-spellbook', 'ghostty', 'Nerd Power Tools', 'Blue Magic: Learn Commands by Watching', 'When a pair, an agent or a teammate''s panel runs a command you''ve never typed and it works, you learn it like Blue Magic into a spellbook you can cast from later.', 'Claude, fixing the agent, runs `journalctl --user -u ghostty-agent -g token --since -1h` and it works. Blue motes spiral off its panel into you: ''You learn Journal Scry (No. 37)''. A week later you open the spellbook''s grid of icons and pick Journal Scry; the command appears at your prompt with `ghostty-agent` and `-1h` selected as placeholders, waiting for your Enter. Spells you never cast fade to grey.', 'Commands come from two sources. Any shell with OSC 133: the text is read from cells whose GHOSTTY_CELL_DATA_SEMANTIC_CONTENT is INPUT between prompt rows, with the exit code from the agent-side CMD_END frame proposed in Commands Cast Like Spells, since libghostty-vt drops it. And Claude Code: PostToolUse hooks on its Bash tool emit the command and whether it errored. A host helper `ghostty-spellbook` checks $HISTFILE or atuin to decide whether a command is new to you, redacts secret-shaped arguments and turns paths and numbers into placeholders. A new lua/bluemage.lua stores spells, names them from a small word list keyed by binary, draws the book with ghostty.ui widgets and plays the motes over the source panel. Casting goes through `/term type` into the focused session, never `/term send`.', 'A command working for an agent doesn''t make it safe, so destructive verbs (`rm`, `dd`, `git push --force`, `terraform apply`) can never be learned, and casting never presses Enter. argv often carries secrets, so redaction is conservative and the spellbook file is made private. The naming whimsy wears off, so plain names are an option.', 'developers learning from pairs and AI agents, Blue Mage mains', 0, 1, 0, 7, 'stretch', 'days', 59, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('palace-of-the-dead-inodes', 'ghostty', 'Nerd Power Tools', 'Palace of the Dead Inodes', 'Your filesystem becomes a dungeon you walk: directories rise as doorways around you, files sit as coffers, and walking through a door cds the shell or leaves a permanent door in your house.', '`/term crawl ~/src` and ''Floor 3: ~/src'' flashes across the screen as a ring of doorways rises, one per subdirectory. Walk up to a coffer and it opens into a `bat` preview, and the 4 GB core dump lurking among them is a mimic. Walk through ''ghostty-dalamud'' and the ring collapses, the shell cds, and the next floor rezzes in around you. Back home, Alt-drag a folder link out of `ls --hyperlink=auto` and its arch stays on your apartment floor, a door into that repo that''s still standing tomorrow.', 'A host helper `xiv-crawl` prints `ESC _ ffxiv;floor;<json: names, kinds, sizes> ESC \` after each cd, caught through OPT_UNKNOWN_SEQUENCE, while OPT_PWD_CHANGED and DATA_PWD confirm where the shell really is. Lua places doors on a ring around ghostty.player() at Raycast ground height, and a segment test on consecutive player positions detects a crossing, which sends `cd -- ''name''` through the `/term send` path only while DATA_CURSOR_AT_PROMPT (OSC 133) is true. Permanent doors come from OSC 8: map the mouse cell to a grid ref, check GHOSTTY_CELL_DATA_HAS_HYPERLINK, read ghostty_grid_ref_hyperlink_uri, accept only file:// links whose host matches the agent''s (a hostname added to its OK reply), and save the arch per zone in world-state.lua. Crossing a saved door OPENs a new panel with a PWD env entry, which the agent already chdirs on. Coffers are small preview panels; `..` is the exit portal.', 'Needs open floor such as a house, the island or an empty field, and walls clip doors. Huge directories need paging into floors of about 20. The agent has no stat or hostname today, and file:// links printed over ssh point at other machines. Walking must always be your own movement: the walk-up steering hook must never carry you through a door. Not for use inside a real Deep Dungeon.', 'developers lost in monorepos, people teaching the shell, housing decorators who want a repo room, Deep Dungeon enjoyers', 1, 1, 0, 8, 'stretch', 'weeks', 60, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('grep-the-world', 'ghostty', 'Terminal Craft', '/grep the World', 'One scrollback search across every terminal you own, with hit counts floating over panels and ''next'' flying the camera to the match.', '/term find OOMKilled and every panel with a match gets a ''3'' badge and a soft pulse, including the pet at your shoulder. Next turns the camera to the panel, scrolls and highlights the line. On controller, the d-pad steps between shell prompts.', 'libghostty-vt ships vt/search.h with incremental feed/tick across screens and scrollback. One GhosttySearch per Session, a few ticks per frame. Highlight as selection, scroll via scroll_delta, badges projected in draw_world, counts in the Umbra popup for minimized tabs. Camera reuses fly-in easing; prompt stepping via SEMANTIC_PROMPT.', 'Sleeping panels only retain the 256 KiB replay ring; search agent-side or say so plainly. Byte-exact matching, no regex. Prompt stepping needs shell integration.', 'sysadmins, homelab folks, on-call engineers who raid', 1, 1, 1, 8, 'ready', 'days', 61, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('folding-screen-splits', 'ghostty', 'Terminal Craft', 'Folding Screen Splits', 'Splitting a world terminal hinges it into a folding screen of panes you can angle, fold shut and walk around.', 'ctrl+shift+\ creases a world panel down the middle: vim on the left leaf, tests on the right. Split again for a triptych around your desk with the focused leaf lit. Drag a hinge to open flat or fold a leaf shut while its process keeps running.', 'Each leaf is its own Session; add group id and leaf index to layout persistence. Lua computes leaf placement from the group anchor with hinge yaw animated by spring(). No new projection math. Hinge drag is a new grip mode calling policy_world_hinge. Folded leaves sleep via sleep_unseen. /term split and fold commands.', 'Overlapping leaves need depth-sorted picking. Long-folded panes lose older scrollback on wake. Resizing a leaf must rebalance neighbours.', 'tmux addicts, sysadmins, housing decorators, roleplayers', 1, 1, 1, 8, 'ready', 'weeks', 62, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('kitty-graphics-tapestries', 'ghostty', 'Terminal Craft', 'Kitty Graphics Tapestries', 'Kitty graphics protocol images render on 3D panels, so live dashboards and pictures hang in the world like paintings.', '`watch -n30 ''curl grafana/render/... | kitten icat''` on a panel pinned to your house wall and a live Grafana graph hangs there as a curved tapestry, tinted by time and weather. It returns with a scanline wipe when the panel wakes.', 'libghostty-vt already implements kitty graphics placements. Decode PNG with vendored stb_image or Zig. Shim forwards CreateTexture/ReleaseTexture via ITextureProvider.CreateFromRaw, cached by image id. Draw placements as tessellated quads so world_transform_vertices curves and tints them; plain AddImage in 2D. No sixel.', 'Images vanish past the replay ring on sleep or restart unless re-sent or cached agent-side. Cap texture memory in-process; create on the render thread and free on unload or crash.', 'homelab folks, streamers, venue decorators', 1, 1, 0, 8, 'stretch', 'weeks', 63, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('item-links', 'ghostty', 'Terminal Craft', 'Item Links in stdout', 'OSC 8 links with an ffxiv:// scheme turn CLI output into item tooltips, map flags and chat-ready item links.', 'A crafter script prints ''Grade 8 Tincture of Strength x3 @ 4,200g''. Hover for an icon-and-stats tooltip, ctrl+click to put a real item link in your chat input to send yourself, or click coordinates to drop a map flag.', 'Mouse to cell to GhosttyGridRef, then ghostty_grid_ref_hyperlink_uri, sharing mouse-selection plumbing. Lua parses item/map/quest URIs into typed actions. Shim forwards Lumina Item lookup and icon, OpenMapWithMapLink, and a chat-input item link insert. ImGui tooltip first; native tooltip later.', 'Output is untrusted: typed actions only, click required, never free text into chat. Chat-input insertion depends on unstable ClientStructs internals.', 'crafters, gatherers, market goblins, CLI tool authors', 0, 1, 0, 8, 'stretch', 'weeks', 64, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('legible-at-distance', 'ghostty', 'Terminal Craft', 'Legible at 40 Yalms', 'Distance LOD for world panels: full text up close, block minimap rows mid-range, a one-line nameplate far away.', 'htop on a Limsa pillar is crisp up close. Walk away and lines become colored blocks shaped like the text; further, the panel collapses to a nameplate: ''build passed 3m12s''. Distant panels also get cheaper.', 'draw_world already has projected corners; divide by rows for on-screen cell height and pick glyphs, run blocks (reuse the merged background-run loop), or nameplate from title, last row or OSC 9;4 progress. Lua owns thresholds with hysteresis. Font mip handles at 20/40/80px chosen in PushWorldFont. MSDF is research.', 'No ligatures: per-cell AddText, no shaper. Big font atlases grow fast. LOD pop needs cross-fade.', 'developers, sysadmins, screenshotters, streamers', 1, 1, 0, 7, 'stretch', 'days', 65, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('soul-crystal-themes', 'ghostty', 'Terminal Craft', 'Soul Crystal Themes', 'Terminal palettes re-derive live from your job, HUD theme and chat colors, and the prompt can show the real job icon.', 'Swap from WHM to DRK and every terminal crossfades to a palette from the job color, diff additions in FC-chat green, errors in Tell pink. Your starship prompt shows the job as the game icon.', 'Set GHOSTTY_TERMINAL_OPT_COLOR_PALETTE with a per-frame lerp; lua/theme.lua builds 16 colors with a contrast clamp while app OSC overrides still win. Shim forwards ClassJob, ClassJobChanged and IGameConfig HUD/chat colors. Job icon drawn as a texture at a placeholder codepoint; prompt queries job via custom OSC.', 'SeIconChar shares the PUA with Nerd Font powerline glyphs and ImWchar is 16-bit, hence textures. Job colors have poor contrast without clamping. Config option names need checking.', 'developers, job-swapping raiders, ricers, streamers', 0, 1, 0, 7, 'stretch', 'days', 66, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('terminal-perf-meter', 'ghostty', 'Terminal Craft', 'Parse Your Terminals', 'A /term perf meter colors each terminal''s frame cost like a DPS parse, and a governor tightens budgets inside duties.', '/term perf shows draw ms, vertices and PTY bytes/sec per tab: grey at 0.3ms, pink for the cmatrix tab burning 4ms. Entering a duty throttles unwatched panels (''budget 1.5ms, 2 throttled''); GPose lifts all caps.', 'QueryPerformanceCounter around draw_terminal and world_transform_vertices, vertex deltas, byte counters per session. Governor caches flat panel geometry and on throttled frames skips render_state_update and render_termview, re-running only the transform. Shim forwards BoundByDuty, IsGPosing and local chat print.', 'Stale geometry cache after resize or font change draws garbage. Combat derez already cuts much of the duty cost. Chat notice should be opt-in.', 'raiders, performance nerds, streamers, low-end laptops', 0, 1, 0, 6, 'ready', 'days', 67, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('accessibility-inheritance', 'ghostty', 'Terminal Craft', 'Inherits Your Accessibility Settings', 'The terminal follows the game''s color-blindness filter, supports accessible fonts per tab, and can speak matching output lines.', 'With deuteranopia filter on, red/green diffs become blue/orange. Tabs can use Atkinson Hyperlegible or OpenDyslexic. A tab marked spoken reads lines matching ERROR aloud, so a failing deploy is audible mid-pull.', 'CVD-safe palette preset chosen from a forwarded IGameConfig color-filter option. Per-profile font handles via AddFontFromFile. Agent strips escapes, regex-matches lines and sends a small frame; speech via host-side piper/espeak, SAPI or TextToTalk IPC as options.', 'No global high-contrast mode to inherit; offer a manual AAA palette. SAPI under Wine is poor, so prefer host TTS. Rate-limit speech so it never talks over callouts.', 'colorblind, low-vision and dyslexic players, raiders who can''t look away', 0, 1, 0, 6, 'stretch', 'days', 68, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('kana-on-the-curve', 'ghostty', 'Terminal Craft', 'Kana on the Curve', 'IME composition text renders inline at the cursor, even on curved world panels, with a game-styled candidate list.', 'A Japanese player types into nvim on an apartment panel: composition text appears underlined at the cursor, bending with the panel, and kanji candidates pop out beside it. Same in the dropdown, ssh and tmux.', 'Committed text and wide cells already work. Shim hooks WM_IME_COMPOSITION/ImmGetCompositionString (or reflects into Dalamud) to forward preedit and cursor. render.nelua draws the underlined overlay in the same draw range so world_transform_vertices curves it. Candidate frame is ImGui; merge a CJK font subset.', 'CJK at 40px bloats the atlas; ImWchar is 16-bit so no astral characters. IME through Wine/Proton on Linux is unreliable. WndProc hooks can conflict with Dalamud''s IME.', 'JP/CN/KR players, multilingual developers, roleplayers', 1, 1, 0, 6, 'research', 'weeks', 69, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('apps-follow-the-sun', 'ghostty', 'Terminal Craft', 'Apps That Follow the Sun', 'The terminal tells your apps it''s light mode at Eorzean dawn and dark mode at dusk, so their themes change as the sun comes up over Thanalan.', 'You''re editing on a pet terminal in Ul''dah at 5:58 ET. The sun clears the walls, the glass warms, and on the same beat Neovim and every other app listening for colour-scheme reports switches to its light theme without a keypress. Step into a dungeon or your basement workshop and everything goes dark again; a thunderstorm keeps it dark until the storm passes.', 'A Lua hook scheme.decide(env) reads ghostty.env() (day seconds, rain, weather id) plus an indoors flag the shim would add from TerritoryType, and returns light or dark with hysteresis. Sessions register GHOSTTY_TERMINAL_OPT_COLOR_SCHEME so `CSI ? 996 n` queries get the current answer. When the answer flips, every session whose DATA_MODE shows 2031 gets an unsolicited report from ghostty_color_scheme_report_encode written to the PTY. OPT_COLOR_BACKGROUND, FOREGROUND and PALETTE switch to dawn and dusk sets built with ghostty_color_palette_generate and clamped with ghostty_color_contrast, so tools that only query OSC 10/11 at startup get the right colours next launch. Sleeping panels get the latest report on wake.', 'Mode 2031 support is uneven, and many tools read OSC 11 once and never again. A mid-session flip can be jarring, so it''s per profile with a manual override and flips at most once per Eorzean hour (about three real minutes). Reports only go to apps that enabled 2031, never into a bare prompt. Soul Crystal Themes recolours the terminal; this tells the apps.', 'Neovim, Helix and fish users, readability-sensitive players, anyone who plays at odd hours', 0, 1, 0, 7, 'ready', 'days', 70, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('regional-phosphor', 'ghostty', 'Terminal Craft', 'Allagan Phosphor', 'Every terminal re-renders in the technology of wherever you stand: Allagan green phosphor, Garlean magitek amber, Sharlayan hologram blue, Crystarium cut glass.', 'Zone into Azys Lla and your btop panel flickers into a curved green Allagan readout, scrolling logs leaving faint phosphor trails. In Garlemald it warms into a rounded amber magitek CRT with a hum bar crawling up the glass. In the Crystarium the slab turns to cut crystal that bends the plaza behind it with rainbow fringes, and a failing build sends a hairline crack across it that seals on the next exit 0.', 'Draw each world panel''s cells into an offscreen texture with ITextureProvider.CreateDrawListTexture, only when the render state reports GHOSTTY_RENDER_STATE_DIRTY_PARTIAL or FULL, so idle panels cost nothing. Draw that texture on the curved quad through the core/depthpass.nelua callbacks with a material shader built by tools/build-shaders.lua: barrel curvature, shadow mask, scanlines, bloom, and persistence blended with last frame''s texture. The glass material also copies the panel''s screen rect from the back buffer and offsets its samples by the cylinder normal panel_depth.hlsl already computes. A new lua/materials.lua maps TerritoryType through Lumina to material tables, world.place gains a `material` field, and zone changes crossfade. While DATA_MODE shows synchronized output (2026) the texture keeps its last frame so trails never smear a half-drawn screen. Cracks key off the agent-side CMD_END exit code.', 'Render-to-texture adds a pass and texture memory per dirty panel, and it''s unconfirmed that CreateDrawListTexture accepts a draw list built by the native core, so a direct-draw fallback stays. The back-buffer copy is taken after the HUD is drawn, so HUD pieces behind glass bend too. Curvature and bloom cost legibility, so a hold-to-read key snaps back to crisp. Persistence trails can bother motion-sensitive players. Nothing on the depth path has been observed in game.', 'ricers, lore fans, roleplayers, GPose folks, retro-computing fans', 1, 1, 0, 8, 'stretch', 'weeks', 71, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('scrollback-spire', 'ghostty', 'Terminal Craft', 'The Scrollback Spire', 'A terminal''s whole scrollback rises out of the ground as a tower of text you fly up to read, and every screen of output adds a storey.', 'On your island a slim spire of glowing rows climbs out of the grass, with the live screen at its base. A long build pushes it higher as you watch. Mount up and fly along it: 80 yalms up you''re reading yesterday''s apt upgrade, and a lit ledge marks the bookmark you left at the first error. Click the ledge and the panel at the base scrolls straight to that line.', 'The base is an ordinary pinned panel. For the rows above it the core reads history with ghostty_terminal_grid_ref at HISTORY points, sized by DATA_SCROLLBACK_ROWS and DATA_TOTAL_ROWS, and caches each row''s text once when it scrolls off. Only the band within about 40 yalms of camera height is drawn through world_transform_vertices, with block LOD above and below. Rows sit on a vertical cylinder, so the existing curve and hit maths apply. Bookmarks are tracked grid refs (ghostty_tracked_grid_ref_*), which survive reflow and go empty when pruned. Clicking a ledge calls ghostty_terminal_scroll_viewport with ROW. A new shim read of ConditionFlag.InFlight fades in the upper storeys only while you fly.', 'At a readable size 10,000 lines is about 200 yalms, so it needs a height cap or compressed storeys. A sleeping panel only has the 256 KiB replay ring, so the spire shrinks after wake unless rows are cached on the client. Flying only works in some zones, and on the island after unlocks. Distant rows cost FPS without strict LOD. Old secrets in scrollback become readable from across the map, though only to you.', 'sysadmins tailing logs, streamers, flying-mount collectors, anyone who has lost output', 1, 1, 0, 9, 'stretch', 'weeks', 72, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('stage-directions-apc', 'ghostty', 'Protocol Alchemy', 'Stage Directions in the Byte Stream', 'A private `ESC _ ffxiv;` escape lets your scripts and TUIs cue real lights, bell rings, poses and camera moves on the same frame as the text they print.', 'Your homemade text adventure prints ''The lantern gutters out.'' and on that frame the real light beside your panel dies, a grey wash crosses the glass and a low sonar ring rolls out from your feet. deploy.sh ends with `stage cam=push-in bell=burst`, so the camera eases onto the panel just as LIVE appears. `cat` a stranger''s log and nothing happens, because that profile isn''t trusted.', 'Profiles with `stage = true` set GHOSTTY_TERMINAL_OPT_UNKNOWN_SEQUENCE and a 4 KiB OPT_UNKNOWN_MAX_BYTES; libghostty-vt then hands over every APC it doesn''t handle itself (kitty `G` and the glyph protocol stay internal), and the callback keeps only `ffxiv;v=1;` payloads. A new Lua hook, stage.cue(id, verbs), maps a whitelist onto what already exists: app/lights.nelua colour and intensity, bell.lua presets, world.place tint and backlight, anim_play, and showcase-style SetCameraState shots. While DATA_MODE reports synchronized output (2026), cues queue and fire when it clears, so a frame and its effect land together. An `ffxiv;q` probe is answered through the session''s WRITE_PTY path so scripts can detect support, and a tiny `stage` shell helper ships beside ghostty-agent. Most of the APC-driven ideas in this batch stand on this plumbing.', 'Output is untrusted: an ssh session to a hostile box, or a log you cat, could flash lights or yank the camera, so it''s off per profile by default, with a verb whitelist and a rate limit. Cues arriving in reattach replay are dropped, the way replayed bells already are. Camera and pose verbs are refused in combat, duties, cutscenes and GPose, and there will never be movement, targeting, chat or command verbs. tmux drops unknown APC unless allow-passthrough is on and the sequence is wrapped.', 'storytellers, RP venue hosts, streamers, demoscene nerds, anyone who writes shell scripts for fun', 1, 1, 1, 9, 'ready', 'days', 73, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('clipboard-crystals', 'ghostty', 'Protocol Alchemy', 'Clipboard Crystals', 'Every OSC 52 copy buds off the panel as an aether crystal that orbits you, and a remote program can read your clipboard only while you hold one out.', 'Yank a stack trace in Neovim over ssh and a small crystal labelled ''nvim@nas: panic: nil map'' breaks off the glass and joins the ring at your shoulder. Drop it on another panel to paste; if it carries newlines headed for a shell prompt it glows red and wants a second click. When a remote tool asks to read your clipboard, the panel says ''wants a crystal'' and gets nothing until you raise one.', 'Register GHOSTTY_TERMINAL_OPT_CLIPBOARD_WRITE: each GhosttyClipboardWrite carries MIME contents (OSC 52, OSC 1337 Copy or OSC 5522), the program name, granted and can_remember, and is answered inside the callback. Store the crystal (capped with OPT_CLIPBOARD_WRITE_MAX_BYTES) and mirror the chosen one to the desktop with the agent''s existing CLIP_SET. OPT_CLIPBOARD_READ must also be answered synchronously, which the agent''s round-trip CLIP_GET can''t do but a crystal already in memory can: reply SUCCESS with the crystal you''re holding out, otherwise DENIED plus a local toast. Dropping a crystal runs ghostty_paste_is_safe (bound today but unused), then ghostty_terminal_paste, so bracketed paste (2004) and kitty paste events (5522) are honoured. Crystals ride the pet springs in lua/world.lua; image/png writes wear a MIME badge until Kitty Graphics Tapestries brings texture upload.', 'OSC 52 read is a known way to steal a clipboard, so deny is the default and any remembered grant must be visible and revocable. Many apps never retry a denied read. Crystals hold secrets: memory only, cleared on logout, labels hidden in streamer mode. tmux needs `set-clipboard on`.', 'Neovim-over-ssh users, security-minded sysadmins, anyone who has pasted the wrong thing into prod', 1, 1, 0, 8, 'ready', 'days', 74, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('your-feet-are-the-mouse', 'ghostty', 'Protocol Alchemy', 'Your Feet Are the Mouse', 'Lay a terminal flat on the floor and any mouse-aware TUI follows your character''s footsteps as the pointer, with a jump as the click.', 'Drop a 12-yalm minesweeper board on your apartment floor and step onto it: the hover highlight follows your boots from tile to tile. Jump and the tile under you flips; land on a mine and the board flashes red around your ankles. A friend who visits sees only you hopping around an empty room.', 'place() already takes pitch, and world_axes and the depth-pass basis tilt with it, so a `floor` pin lays the panel flat at a Raycast ground height. Each frame ghostty.player() x/z is projected into panel pixels through that basis. The core builds a ghostty_mouse_encoder with setopt_from_terminal, so tracking (1000/1002/1003) and format (SGR 1006, SGR-pixels 1016) come from the app, plus OPT_SIZE and OPT_TRACK_LAST_CELL so motion reports only when you cross a cell. The shim adds ConditionFlag.Jumping to GuObject; its rising edge after a short dwell on a tile sends a button-1 press and release. Stepping on or off the board sends ghostty_focus_encode in or out when mode 1004 is set. Only your own character counts, and only in floor mode.', 'The plugin has never reported a click to a TUI (termview only encodes the wheel), so this is the mouse encoder''s first user. Jumps are noisy, hence the dwell. Floors aren''t flat everywhere, so raycast the corners and refuse slopes, and a flat panel may z-fight the floor in the depth test. Other players'' positions must never become input.', 'housing decorators, TUI game tinkerers, streamers, anyone with a big empty FC house', 1, 1, 1, 9, 'stretch', 'days', 75, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('emoji-pyrotechnics', 'ghostty', 'Protocol Alchemy', 'Emoji Pyrotechnics', 'Sparkle, party-popper and fire emoji printed by your tools burst out of their exact cell as particle effects that spill into the room.', 'Your test runner prints its party popper and confetti rains out of that cell, bouncing on the floor around the panel. `cargo` sparkles send glitter drifting past your ear, and a log line with a fire emoji sheds embers that vanish behind the pillar in front of you. Scroll back over them and nothing fires again: each emoji gets one show.', 'After Session:feed, walk the render state with ghostty_render_state_row_iterator_next_dirty and read GHOSTTY_RENDER_STATE_ROW_CELLS_DATA_GRAPHEMES_UTF8 per cell, matching a table in a new lua/pyro.lua that maps a grapheme to an emitter preset. Grapheme clustering (mode 2027) keeps ZWJ and VS16 sequences in one cell, so a flag or a skin-toned emoji is a single emitter. Each hit pins its row with a capped ghostty_terminal_grid_ref_track so redraws and scrolling don''t refire it, and bursts during reattach replay are skipped the way core/bell.nelua skips replayed bells. Cell rects map to world space through world_transform_vertices; particles are quads through the depth-pass callbacks, landing at one Raycast per burst.', 'Dalamud''s 16-bit ImWchar can''t draw emoji outside the BMP, so most source cells still show tofu and the particles are shapes, not glyphs. Emoji-heavy output such as a gitmoji log needs a per-second budget. TUIs that clear and redraw make old emoji look new. Needs a photosensitivity switch, and emitters stay off in duties.', 'streamers, JS and Rust developers, gitmoji fans, chat-TUI users', 1, 1, 0, 8, 'ready', 'days', 76, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('waymarked-scrollback', 'ghostty', 'Protocol Alchemy', 'Waymarked Scrollback', 'Your last eight commands stand on the floor as waymarks A to D and 1 to 4, and stepping onto one scrolls the panel to that command''s output.', 'After a long debugging session eight markers fan out in front of your panel, green for clean exits and red for failures. Step onto red 3 and the panel scrolls back to `terraform plan` and outlines its output. Alt-drag the marker away and that output tears off as a frozen page, colours intact, that you stick on the wall beside the fix. A healer watching the same session drops marker A on a stack trace, and it rides that line on your copy as new output pours in.', 'The core walks history with ghostty_terminal_grid_ref and GHOSTTY_ROW_DATA_SEMANTIC_PROMPT to find prompt rows and pins each with ghostty_terminal_grid_ref_track, so markers survive scrolling and reflow; when ghostty_tracked_grid_ref_has_value goes false the row was pruned and the marker crumbles. libghostty-vt parses the OSC 133 exit code but doesn''t keep it, so colours come from the agent-side CMD_END frame proposed in Commands Cast Like Spells. Standing on a marker (distance from ghostty.player()) calls scroll_viewport with ROW and ghostty_terminal_select_output on the tracked ref. Tearing off formats that selection with ghostty_terminal_selection_format_alloc in VT format and feeds it into a transport-less, read-only terminal pinned like any panel. Shared marks are a MARK frame carrying the line text and output byte offset; each viewer resolves it with ghostty_search_* and tracks the hit.', 'Needs shell integration on every host, through ssh and tmux. Tracked refs add work on every update, so cap them. These are drawn markers only plugin users see: never place real waymarks, which the whole party sees. Repeated log lines can resolve a shared mark to the wrong row, and a late joiner whose 256 KiB replay lost the line can''t place it. Torn-off pages keep whatever secrets were printed.', 'developers, SREs, on-call rotations inside FCs, anyone who scrolls up hunting for which run failed', 1, 1, 0, 8, 'stretch', 'weeks', 77, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('agent-party-formation', 'ghostty', 'Familiars', 'Your Agents Are a Light Party', 'Parallel Claude Code agents fight at your side as a light party: tank plans, healer reviews, two DPS implement in their own worktrees, with context as MP and every tool call as a cast.', '`/term party refactor-loader` and four pet terminals rez into formation: planner out front, reviewer behind you, implementers on your flanks. The party list reads ''DPS, wt/loader-a, Casting: Edit loader.nelua'' while MP drains as context fills, and a member waiting for permission pulses with an exclamation mark. When both DPS branches go green a Limit Break gauge fills for a merge you run yourself. Share the party with your FC and members who log in find it working at the workshop bench.', '`ghostty-party` reads a composition from lua/party.lua (role, job icon, prompt file, worktree), runs `git worktree add` per member, and OPENs `claude` with a CWD env entry and a GHOSTTY_SESSION variable. Claude Code hooks (PreToolUse, PostToolUse, Notification, PreCompact, Stop, SubagentStop) call a tiny `ghostty-emit` that writes to a new unix socket on ghostty-agent, which buffers EVENT frames for detached sessions and broadcasts them; MP comes from the last usage entry in the hook''s transcript_path. Formation is a new anchor preset on the pet springs in lua/world.lua, and frames are ImGui with job icons from ITextureProvider.GetFromGameIcon. Agents running outside Ghostty join through an in-game MCP server plugin: the shim subscribes to that plugin''s agent-board IPC and change event and turns its status posts into frames. The LB button only types `git merge` into the tank''s session with `/term type`, never Enter.', 'Four live agents cost real money and quota, so the party list shows spend. Hook payloads and tool names change between Claude Code releases. Sharing with the FC puts code, prompts and secrets on other clients, and every attached client can write today, so it needs a read-only relay, a share toggle and redaction. Worktrees pile up and need an explicit disband. Inside duties the formation collapses to frames only. No in-game MCP server has been observed working yet.', 'developers running several AI coding agents at once, developer FCs, raiders who think in roles', 1, 1, 1, 9, 'stretch', 'weeks', 78, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('familiar-tells-ready-check', 'ghostty', 'Familiars', 'Ready Checks for Your Agents', 'When an agent needs you mid-duty it waits for the wipe or the kill, and then every pending question arrives at once as a ready check.', 'Queued in Limsa, a local echo line tagged [Ghostty] pops up: ''Claude on bazzite-sway: pin the base image digest, or keep floating stable?'' Click it and its panel slides in beside you. Mid-pull two more agents stall without a sound. The boss dies, and a Ready Check window lists all three, each with the last lines of its prompt and its numbered choices; you tick 1, 1 and 3 before the loot rolls finish.', 'Claude Code''s Notification and Stop hooks send `ghostty-emit waiting` (the EVENT frame from Your Agents Are a Light Party); other agents can use OSC 9 or 777, which reach GHOSTTY_TERMINAL_OPT_DESKTOP_NOTIFICATION once session.nelua registers it. Out of combat the shim prints the line with IChatGui.Print and a link payload that focuses the session''s panel; while InCombat or BoundByDuty is set, lines queue. The Ready Check opens on ICondition.ConditionChange (combat off) or IDutyState.DutyWiped and DutyCompleted, as a local window styled after the game''s, never the real /readycheck. Each row renders the session''s bottom rows from render state, options are parsed from lines shaped like `1. Yes`, and a click sends only that digit through the key encoder to that session. CLAUDE.md can also tell agents to call an in-game MCP server''s duty-state tool before asking and keep working while you''re inside.', 'One-click approvals between pulls is how you approve an `rm -rf` without reading it, so rows show the full command and destructive patterns can''t be answered from the check. Parsing Claude Code''s prompt off the screen breaks when its TUI changes. Local lines must never look like a real player''s tell, both for clarity and honest screenshots. Nothing is ever sent to other players.', 'developers who leave agents running while they play, raiders, on-call devs', 0, 1, 0, 8, 'stretch', 'days', 79, 2, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('feed-the-familiar', 'ghostty', 'Familiars', 'Feed It to the Familiar', 'Alt-drag a failing terminal onto your AI companion and it swallows the last command''s output as context and starts on the fix.', '`cargo test` just went red on the panel by the window. Alt-grab it, carry it across the room and let go over the Claude pet at your shoulder: the panel folds into it with a gulp of light, then springs back to the wall. The pet''s input box reads ''[Pasted text: cargo test in ~/cascadia, exit 101, 212 lines]'', and a moment later its cast bar says ''Reading main/cascadia-tools/solver.go''.', 'world.drop(id, pose) already fires when an Alt-drag ends (core/policy.nelua:544); lua/world.lua checks the drop point against panels whose profile has `familiar = true`. The core scans GHOSTTY_ROW_DATA_SEMANTIC_PROMPT upward for the last OSC 133 prompt, takes a grid ref on the output after it, calls ghostty_terminal_select_output and ghostty_terminal_selection_format_alloc (plain, unwrapped, trimmed, capped to the tail). A header adds DATA_TITLE, DATA_PWD from OSC 7, the command from INPUT-semantic cells and the exit code from the agent''s CMD_END frame. The block goes through ghostty_paste_encode into the familiar''s session as a bracketed paste. Without OSC 133 it falls back to a PLAIN formatter over the viewport. The swallow reuses the present and fly-in tween in worldview.nelua.', 'It sends terminal output, env dumps and tokens in stderr included, to a hosted model: show a byte count, redact token-shaped strings, confirm the first time. If the familiar sits in a permission prompt the paste lands in the wrong place, so drops are refused unless its last hook state is idle. The source shell needs OSC 133 through tmux and ssh. Alt-drag already means move, so drop targets need a clear highlight.', 'developers pairing with Claude Code or other terminal agents', 1, 1, 0, 8, 'stretch', 'days', 80, 2, 0)
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Scholar''s Ledger', 'Almanac''s threads, made easier to search, steer and trust once you have a few hundred of them.', 0, 'almanac') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Almanac''s Grimoire of Tools', 'More kinds of tools behind Almanac''s IToolSource, and a clearer look at what the model did with them.', 1, 'almanac') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Almanac''s Proving Grounds', 'Benchmark and model-fit work, so players can see what their card can really run beside the game.', 2, 'almanac') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Almanac at the Adventurer''s Side', 'Ways for Almanac to fit around actual play: duties, spoilers, busy hands and repeated questions.', 3, 'almanac') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-thread-search', 'almanac', 'The Scholar''s Ledger', 'Search Every Thread', 'A search box over every conversation you have had with Almanac, so the answer from last Tuesday is two keystrokes away instead of lost in the sidebar.', 'You remember asking which Bozjan zone had the fish you wanted, but not when. Type ''bozja fish'' in the thread sidebar and three hits appear with the matching line highlighted. Click one and the thread opens scrolled to that message.', 'Add an FTS5 virtual table over messages.content in AlmanacStore''s schema (CREATE ... IF NOT EXISTS beside threads/messages), kept in step by triggers so AppendMessage, ForkThread and DeleteThread need no changes. A new AlmanacStore.Search(query) returns (thread id, seq, snippet). ChatWindow.DrawThreads gets an input above ''New thread''; ChatSession.Open grows a seq to scroll to. Tool results are indexed but ranked below user and assistant lines.', 'FTS5 has to be present in the e_sqlite3 the plugin ships and loads inside Dalamud; SqliteNativeTests should assert it the way it asserts the version. The first open on an existing database has to backfill the index, which must not block the framework thread. Prompted-mode tool results are stored as user messages with PromptedTools.ResultPrefix and need filtering.', 'everyone who uses the chat regularly', 0, 1, 1, 5, 'ready', 'days', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-context-gauge', 'almanac', 'The Scholar''s Ledger', 'Context Gauge', 'A small bar in the chat header that shows how full the model''s context is, and trims old tool output before it overflows instead of after.', 'Twenty questions into a crafting session the gauge turns amber. Hover it: ''about 6,900 of 8,192 tokens; the recipe dump from step 3 is 2,100 of them''. Almanac shortens that old result on the next turn and says so in a yellow notice line.', 'ChatSession.Window cuts to the last 40 messages (HistoryWindow) whatever their size, so one large get_recipe result can fill a small context. ChatResult already carries PromptTokens; read the served context length from Ollama''s /api/show or the gateway, store it per model next to model_caps, and replace the message-count window with a token budget that trims old tool output first, as the engine''s [agent] context_tokens does. ChatWindow.DrawHeader draws the gauge.', 'Not every server reports prompt tokens or its context length, so the gauge needs an honest ''unknown'' state and a character-count estimate. Trimming a tool result the model still needs makes it call the tool again or guess. Prompted mode puts the tool list in the system prompt, which counts too.', 'players on 8 GB cards and small-context models', 0, 1, 0, 5, 'ready', 'days', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-clickable-answers', 'almanac', 'The Scholar''s Ledger', 'Answers You Can Click', 'Map coordinates, item names and duty names in a reply become small buttons that place the flag or show the details, without asking the model again.', 'Almanac answers ''The Summoning Bell is at X 11.2 Y 14.5 in Old Gridania''. The coordinates are underlined; click them and the flag lands on your map. Hover ''Grade 8 Tincture of Strength'' and a card shows its ilvl and where you already have some.', 'Structured tool results (ToolOutcome.Json, kept in CallRecord) already name the zones, items and coordinates the answer was built from, so matching the reply against those is more reliable than parsing free text. ChatWindow''s LineKind.Assistant branch renders spans instead of one TextUnformatted. Clicks call engine.XivMcpToolsAsync() then McpToolSource.CallAsync("set_map_flag" | "get_item" | "find_owned_items") directly, going through XivMcp''s normal tiers.', 'Wrapped ImGui text with inline buttons is fiddly and costs frame time on long transcripts. A model that invents coordinates would get a flag in the wrong place, so only values that came out of a tool result become links. Old threads reopened from SQLite have lost the in-memory CallRecords unless tool JSON is re-parsed from the stored messages.', 'everyone, especially new players', 0, 1, 1, 7, 'stretch', 'days', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-thread-voices', 'almanac', 'The Scholar''s Ledger', 'A Voice per Thread', 'Give each thread its own system prompt, so the crafting thread stays terse and the lore thread can talk like a Sharlayan librarian.', 'Right-click a thread, choose ''Voice'', pick ''Crafting tutor''. From then on that thread answers with macros and numbers only, while the story thread next to it keeps its long-winded scholar. Branching a thread keeps its voice.', 'AlmanacSettings.SystemPrompt is one global string and Engine.GetChatSession passes a Func<string> for it. Store a per-thread prompt in the kv table (thread.<id>.prompt) so no migration is needed, have ChatSession.SendAsync ask for the thread''s prompt before the global one, and copy it in AlmanacStore.ForkThread. A few built-in voices ship beside DefaultSystemPrompt; the thread context menu in ChatWindow.DrawThreads picks one.', 'A voice that drops the default prompt''s rules (''do not guess such facts'', ''if an action is denied, do not retry'') makes a small model worse at tools, so custom voices should be appended to those rules, not replace them. Voices that imitate named NPCs are fan content; keep the shipped ones generic.', 'roleplayers, crafters, anyone with several long-running threads', 0, 1, 0, 5, 'ready', 'hours', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-thread-export', 'almanac', 'The Scholar''s Ledger', 'Export a Thread for a Bug Report', 'Save a thread as Markdown with its tool calls, model and settings, after a review step that blanks out names and tokens.', 'The model called the wrong tool twice. Right-click the thread, ''Export for a report''. A preview shows the transcript with your character name, retainer names and the XivMcp endpoint replaced by placeholders; you untick one line you would rather keep private and save the file.', 'AlmanacStore.Messages(threadId) already returns every message with tool calls and tool results. ChatSession.Render is the model for turning them into lines. Add a header with Engine.Version, engine.ModelLabel, ToolMode and ToolProfile, run a redaction pass seeded from get_player''s result and the settings'' URLs and tokens, and show the result in a window with per-line exclusion before writing it next to the plugin config directory.', 'Redaction by string match will miss things, such as a friend''s name in a chat log a tool returned; the review step is the real safeguard and the README''s warning about unreviewed transcripts still applies. The export must never include LeaderboardToken, AlmanacToken or XivMcpToken.', 'bug reporters, benchmark contributors, the maintainer', 0, 1, 0, 3, 'ready', 'hours', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-wasm-tool-sources', 'almanac', 'Almanac''s Grimoire of Tools', 'Sandboxed WebAssembly Tools', 'Let players add small tools, such as a gil calculator or a rotation lookup, as WebAssembly modules that can reach nothing they are not granted.', 'You drop tincture-math.wasm into Almanac''s tools folder. Settings lists it with ''no filesystem, no network''. Ask ''how many tinctures for a week of savage at two pulls an hour?'' and the chat shows ''→ tincture_math'' with the answer worked out by code, not guessed by the model.', 'The WasmToolSource sketched in ToolSources.cs''s doc comment: one module per tool, exporting its ToolDef JSON and call(args-json) -> result-json, run under WASI with no preopens or sockets by default. It only has to implement IToolSource; Engine.NewLoop adds it to the ToolHub list after XivMcp, so XivMcp keeps name priority. Per-module grants shown in SettingsWindow; the runtime is disposed in Engine.Dispose and counted by LiveObjects so the reload leak tests cover it.', 'A Wasm runtime such as Wasmtime brings a native library that has to load inside Dalamud on Windows and under Wine, the same class of problem as the SQLite native library, and must unload cleanly on plugin reload. Fuel or time limits are needed so a looping module cannot stall a turn. Sharing modules invites people to run code from strangers; grants must default to nothing.', 'tinkerers, theorycrafters, plugin authors', 0, 1, 1, 7, 'research', 'weeks', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-notes-tool-source', 'almanac', 'Almanac''s Grimoire of Tools', 'Your Own Notes as a Tool', 'Point Almanac at a folder of Markdown notes, such as your glamour plans, retainer ventures or static''s strats, and the model can search them in game.', 'Ask ''what did we decide for the tank swap on P3?'' and the chat shows ''→ notes_search tank swap P3'', then quotes the two lines from static-strats.md with the file name, instead of making something up.', 'A NotesToolSource implementing IToolSource with two read-only tools, notes_search and notes_read, backed by an FTS5 index in almanac.sqlite (the Python engine''s knowledge base does the same with SQLite FTS5, so its front-matter format can be reused). Engine.NewLoop adds it to the ToolHub list; ToolProfiles gains the two names in SmallSet so small models see it. Re-index on a file-change watcher or on a Refresh button in SettingsWindow.', 'Notes go to whatever model server is configured, which may not be local; the settings page has to say that. A large folder makes results long and eats a small context (see the context gauge). A file watcher under Wine on a Z: path may not fire, so manual refresh has to exist anyway.', 'raiders, crafters, organised players, FC officers', 0, 1, 1, 6, 'stretch', 'days', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-engine-knowledge-bridge', 'almanac', 'Almanac''s Grimoire of Tools', 'The Engine''s Knowledge in Game', 'When the plugin already uses an Almanac gateway, also offer the engine''s read-only tools, such as kb_search and model_residency, in the in-game chat.', 'Your homelab notes live in the engine''s knowledge base. Mid-queue you ask ''is the NAS backup still failing?'' and the in-game chat calls almanac__kb_search and host_status through the engine, while game questions still go to XivMcp.', 'ToolHub already merges several sources, first-lister wins. When AlmanacSettings.Engine == EngineAlmanac, create a second McpToolSource over McpHttpClient pointed at the engine''s MCP port (41880) with AlmanacToken and id "almanac", and add it after XivMcp in Engine.NewLoop. Filter to tools whose safety is read, since the engine''s change tools rely on MCP elicitation or confirm tokens the chat window does not implement.', 'The engine''s gateway and MCP server are separate listeners with the same bearer token; a player who exposed one but not the other gets a confusing half-connection. Tool names may collide with XivMcp''s, so the engine''s need a prefix. Engine tools that run commands on remote hosts should stay out of the in-game list even if marked read.', 'engine users, homelab players', 0, 1, 0, 6, 'ready', 'days', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-tool-call-inspector', 'almanac', 'Almanac''s Grimoire of Tools', 'Tool Call Inspector', 'Click any grey tool line in the transcript to see the full arguments and result, how long it took, and whether the call passed schema validation.', 'The answer about tomorrow''s weather looks wrong. Click ''← get_weather_forecast (0.4s)'' and a panel opens with the formatted JSON: the model asked for the wrong territory id. Copy the call, or rerun it as it was to check the tool itself.', 'ChatSession.Shorten cuts tool lines to 120 characters and Render throws the rest away. Keep the StoredMessage seq on tool lines (it is already there), and on click load the full message from AlmanacStore.Messages, pretty-print it with System.Text.Json, and pair each call with its result by ToolCallId. Validation reasons come from Scorer.Validate as AgentLoop already records them in CallRecord. Rerun is only offered for tools in the read tier.', 'Tool results can be large, such as a full inventory, and drawing them every frame in ImGui is slow unless the text is cached and clipped. Prompted-mode threads store calls as plain assistant text, so pairing needs the PromptedTools parser. Rerunning an action-tier call must never be possible from here.', 'players testing models, benchmark contributors, plugin developers', 0, 1, 0, 4, 'ready', 'days', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-question-router', 'almanac', 'Almanac''s Grimoire of Tools', 'Only the Tools the Question Needs', 'Before each turn, narrow the offered tools to the few that fit the question, so small models stop reaching for get_equipment when you asked about the weather.', 'With the full tool set a 4B model used to call three unrelated tools before answering. Now the header reads ''tools: 5 of 38 for this question''. It asks get_weather_forecast once and answers.', 'ToolProfiles'' own comment says small models do better with fewer tools; today the choice is a static small/standard/all set. Add a per-turn filter to ToolHub: score each ToolDef by keyword overlap and, where the server offers one, embeddings from an /v1/embeddings model, keep the top N plus a fixed core (get_location, get_player). Measure it with BenchRunner against the unfiltered sets before it becomes a default.', 'Leaving out the tool a question needed is worse than offering too many: the model guesses. Embeddings need a second model loaded next to the chat model and the game. Changing the tool list between turns of one thread can confuse models that cache tool names, and it makes benchmark results incomparable unless recorded in the result.', 'players on small models and 8 GB cards', 0, 1, 0, 5, 'stretch', 'weeks', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-streaming-ask-ipc', 'almanac', 'Almanac''s Grimoire of Tools', 'Answers Back Over IPC', 'A second IPC version that lets another plugin ask Almanac a question and receive the reply as it streams, not only open the chat window.', 'A terminal plugin''s /ask panel or a desktop widget shows Almanac''s answer in its own bubble, word by word, with tool lines in grey, and the Almanac window never opens.', 'Plugin.cs registers Almanac.ApiVersion (1) and Almanac.Ask (Func<string, bool>), which only opens ChatWindow and calls Send. Add ApiVersion 2 with Almanac.AskInThread returning a request id, and an Almanac.Event IPC message carrying the same events ChatSession.OnEvent already handles (TextDeltaEvent, ToolStartedEvent, ToolFinishedEvent, done or error), serialised like the engine''s --stream-json lines. Requests run in their own ChatSession so they do not fight the window''s thread.', 'Two ChatSessions against one local model double the load; requests need a queue and a busy answer. IPC messages are delivered on the caller''s thread and a slow subscriber could stall streaming. Any plugin can call it, so it must not accept a system prompt or tool profile from the caller.', 'plugin authors, Ghostty and XivDesktop users', 0, 1, 0, 5, 'ready', 'days', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-bench-head-to-head', 'almanac', 'Almanac''s Proving Grounds', 'Head to Head', 'Pick two past benchmark runs and see them side by side, task by task, with the tool calls each model made.', 'Past runs lists qwen3.5:9b at 0.81 and a newer 8B at 0.78. Tick both and press Compare: they tie on location and weather, the 8B fails flag_coordinates by swapping X and Y, and it answers 0.4 s sooner on average. Now you know which one to keep.', 'Every run is already in bench_runs with its full ResultJson (AlmanacStore.BenchRuns returns BenchRow). BenchmarkWindow''s ''Past runs'' header gets checkboxes and a Compare table built from the per-task entries in each result, with columns for tool validity, answer check and time to first token. Only runs with the same SuiteVersion are comparable; others are shown greyed with the reason.', 'Results from different context sizes, quantisations or mock versus live mode look comparable and are not, so the table must show those settings at the top. Old result JSON written before a schema change needs tolerant parsing.', 'players choosing a model, leaderboard contributors', 0, 1, 0, 5, 'ready', 'days', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-context-fit-finder', 'almanac', 'Almanac''s Proving Grounds', 'Context Fit Finder', 'A wizard step that tries the chosen model at 8k, 16k and 32k context, measures VRAM and speed at each, and recommends the largest that does not spill into system RAM.', 'The wizard says your 12 GB card has about 8.5 GB left beside the game. Press ''Find my fit'': three short runs later it reports 32k spills and drops to 4 tok/s, 16k fits at 31 tok/s, and it sets 16k for you.', 'SetupWindow already computes the VRAM budget (GpuInfo, GameReserveMb) and Engine.BenchRunnerAsync builds a runner with an IVramProbe (OllamaVramProbe first, NvidiaSmiProbe as fallback) sampled by VramSampler. Run a three-task subset of Suite.Bundled() with Ollama''s num_ctx option per step, record peak VRAM and tok/s, and detect spill as a sharp drop in speed or Ollama reporting size_vram below size.', 'Only Ollama takes a per-request context size; LM Studio and llama.cpp fix it at load time, so for them this can only advise. Each step reloads the model, which takes time and briefly competes with the game for VRAM. Under Wine, nvidia-smi may not be reachable from inside the game.', 'new players, anyone sharing one GPU with the game', 0, 1, 0, 6, 'stretch', 'days', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-headroom-gauge', 'almanac', 'Almanac''s Proving Grounds', 'Headroom Gauge', 'A live readout of VRAM used by the game and the model, and of the last reply''s tokens per second, so you can see a hub or a busy FATE pushing the model out.', 'In a quiet field the small gauge in the chat header shows 2.1 GB free. You enter Limsa at peak hour and it drops to 300 MB; the last reply took 9 s at 6 tok/s. Almanac suggests the small tool set and a lower context until you leave.', 'Reuse IVramProbe from Bench/Vram.cs on a slow timer (every few seconds, off the framework thread), plus DXGI''s QueryVideoMemoryInfo next to the adapter enumeration in GpuInfo.cs for the game''s own budget. Tokens per second come from ChatResult''s OutputTokens and elapsed time, already measured for the benchmark. ChatWindow.DrawHeader shows it; thresholds come from GameReserveMb.', 'QueryVideoMemoryInfo through DXVK under Wine may report numbers that do not match the real card. nvidia-smi polling costs a process spawn each time; keep it slow or use the Ollama probe. Numbers that jump about will worry people more than help them, so smoothing matters.', 'players on 8-12 GB cards, benchmark contributors', 0, 1, 0, 6, 'stretch', 'days', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-suite-from-thread', 'almanac', 'Almanac''s Proving Grounds', 'Turn a Conversation into a Benchmark Task', 'When a model gets a real question badly wrong, turn that exchange into a proposed benchmark task, with the tool results frozen as fixtures, for the next suite version.', 'The model told you the wrong aetheryte for a hunt mark. Right-click the question, ''Propose as a benchmark task''. A form shows the prompt, the tools that were needed, their results captured as fixtures and a field for the correct answer; you submit it for review instead of just grumbling.', 'A thread already holds the user prompt, each tool call and its JSON result, which are the shape of a SuiteTask (Prompt, Tools, Expect) and of the suite''s fixtures that FixtureToolSource replays. Build the draft task from AlmanacStore.Messages, let the player write the Expect rules in the vocabulary JsonRules and Scorer already use, and send it through the existing DeviceLink sign-in to a proposals endpoint, not straight into ffxiv-core.', 'Fixtures captured live contain the character name, location history, retainers and possibly other players'' names from chat tools; the form has to redact them and show the exact payload, as Share does. Every accepted task changes the suite''s Sha256 and breaks comparability with past runs, so tasks must batch into versioned releases. Writing good Expect rules is hard for most players.', 'benchmark contributors, the leaderboard''s maintainers', 0, 1, 0, 7, 'stretch', 'weeks', 14, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-duty-quiet-mode', 'almanac', 'Almanac at the Adventurer''s Side', 'Quiet While You Pull', 'Almanac hides its window in combat and duties, holds any reply that finishes meanwhile, and tells you with a toast once you are out.', 'You asked about a recipe just before the queue popped. The window slides away at the barrier. Twenty minutes later the boss dies, and a quiet toast says ''Almanac: your answer about Rarefied Sykon Bavarois is ready''. /almanac opens it where you left off.', 'Inject ICondition and IToastGui into the Plugin constructor beside ICommandManager and IFramework. On IFramework.Update, watch ConditionFlag.InCombat and BoundByDuty; set ChatWindow.IsOpen false and remember it was open. ChatSession keeps running on the thread pool as it does now; when it goes from Busy to idle during quiet mode, queue one toast for when the flags clear. A setting in SettingsWindow turns it off.', 'Some players want the window open in duties, such as for a crafting-log duty or a trial they have cleared many times, so it must be optional. Toast wording should not look like a game system message. Condition flags change briefly during cutscenes and zone loads and need a short debounce.', 'raiders, roulette players, anyone who asks questions in queue', 1, 1, 0, 5, 'ready', 'hours', 15, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-duty-residency', 'almanac', 'Almanac at the Adventurer''s Side', 'Give the VRAM Back for Duties', 'When the model shares the game''s GPU, unload it as you enter a duty and load it again when you leave, so savage frame rates do not pay for an idle chatbot.', 'Enter the raid and a small notice says ''Almanac released 5.8 GB for the duty''. You wipe, you clear, you leave; by the time you are back at the Summoning Bell the model is warm again and your first question answers without a cold start.', 'Only when AlmanacSettings.GameOnSameGpu is set. For an Ollama backend (BackendKind), POST /api/generate with keep_alive 0 on BoundByDuty and a no-prompt load with keep_alive -1 on leaving, the same calls the engine''s residency loop makes. The ServerDetector root URL and Engine.Quick HttpClient already exist for this. Skip it while ChatSession is Busy, and show the state in the chat header.', 'With the Almanac gateway as the engine, its own residency loop pins the model while ffxiv_dx11.exe runs and will fight the plugin, so the gateway needs a way to be told, or the plugin must stay out of it. LM Studio and llama.cpp have no equivalent API. Reloading a model right as the duty ends causes a stutter in town; a delay helps.', 'raiders on single-GPU machines, players on 8-12 GB cards', 1, 1, 1, 6, 'stretch', 'days', 16, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-spoiler-guard', 'almanac', 'Almanac at the Adventurer''s Side', 'Spoiler Guard', 'Almanac checks how far you are in the main scenario and keeps its answers about lore, NPCs and later zones behind that line unless you ask it not to.', 'Midway through Heavensward you ask who a certain knight is. Almanac answers with what you have already seen, then adds: ''There is more about him later in the story. Ask again with /almanac spoilers on if you want it.''', 'At the start of a thread, and when the zone changes, call XivMcp''s get_quest_status for a short list of main scenario milestones and put the furthest completed one into the system prompt that ChatSession builds each turn, with a rule not to reveal later events. A toggle in settings and a /almanac spoilers on|off subcommand in Plugin.OnCommand. Answers based on search_quests or get_quest for quests beyond that point get a warning line.', 'A local model''s own training is the main source of spoilers and a prompt rule will not stop all of them; this lowers the risk and must say so. Choosing the milestone list takes knowledge of the story and upkeep every patch. Players on a new character may have finished the story on another.', 'new and returning players, story-focused players', 0, 1, 1, 7, 'stretch', 'days', 17, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-reference-pages', 'almanac', 'Almanac at the Adventurer''s Side', 'Reference Pages', 'Save a question you ask often as a named page and run it with one command or macro line, so your daily checks are one keypress.', 'Every evening you type the same three questions. Now /almanac page evening runs ''which retainers are back, what is the weather in Eureka Pagos for the next hour, and which of my gathering tokens are close to the cap?'' and puts the answer in its own thread.', 'Store pages in the kv table under page.<name>. Plugin.OnCommand gains a ''page <name>'' case that opens a fresh thread through ChatSession.New and sends the stored text via ChatWindow.Send. A small list in SettingsWindow edits them, and the transcript''s context menu gets ''Save this question as a page''. Because it is a slash command it can sit in a game macro.', 'A page that asks for an action-tier tool will still stop for XivMcp''s approval, which is correct but surprising in a macro. Pages run one at a time; a second while Busy is refused, as Almanac.Ask is today. It must never become a timer that runs itself.', 'daily-routine players, gatherers, crafters', 1, 1, 0, 4, 'ready', 'hours', 18, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('almanac-push-to-talk', 'almanac', 'Almanac at the Adventurer''s Side', 'Push to Talk, Read Aloud', 'Hold a key, ask your question out loud, and hear the answer spoken, with speech recognition and voice both running on your own machine.', 'Both hands are on the controller mid-gathering. You hold the chosen key and say ''when does the next ephemeral node spawn here?''. The words appear in the chat window as you speak, the tool line flickers, and a quiet voice answers while you keep moving.', 'Capture microphone audio in the plugin (for example NAudio''s WASAPI capture), send it to a local whisper.cpp server''s /inference endpoint that ServerDetector could find like the model servers, and pass the text to ChatWindow.Send. For speech, stream the TextDeltaEvent text sentence by sentence to a local TTS server such as Piper and play it on a separate audio device. Settings hold the two endpoints and the key.', 'Microphone capture inside the game process under Wine is unreliable, and audio APIs differ per system. Speech recognition and TTS take GPU or CPU next to the chat model and the game, which is exactly the budget the wizard is trying to protect. Picking up voice chat from a party must never happen by accident, so push to talk only, with a clear indicator.', 'controller players, gatherers, players who prefer speaking to typing', 1, 1, 0, 8, 'research', 'weeks', 19, 1, 0)
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Gold Saucer at Home', 'The cabinet itself: where your games live in the world and how they share a screen with Eorzea.', 0, 'xivarcade') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Save Crystals', 'Your battery saves and states, kept safe, visible and easy to go back to on any machine.', 1, 'xivarcade') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Cartridge Shelf', 'The cover wall as a collection you can sort, annotate and be proud of, still bring-your-own.', 2, 'xivarcade') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Arcade Linkshells', 'XivArcade talking to the other mods in the family, each link optional and local.', 3, 'xivarcade') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-duty-pop-pause', 'xivarcade', 'Gold Saucer at Home', 'Duty Pop Pause', 'When the Duty Finder pops, your arcade game saves a state and pauses, and it offers to resume when you are back.', 'You are halfway through the Magitek Armor ride in FF6 when the roulette pops. The panel freezes on the frame, a small ''state saved'' tag appears, and the pad is already back with FFXIV. Forty minutes later the duty ends and a chat line asks if you want to pick up in Narshe.', 'Add network_cmd_enable and a fixed network_cmd_port to system_cfg_text in tools/xiv-arcade, so every RetroArch launch accepts local UDP commands. PadCaptureService already watches ICondition for combat and cutscenes; add a DutyPop reason to the PadRelease enum, raised from ConditionFlag.WaitingForDuty or an IAddonLifecycle PostSetup on ContentsFinderConfirm. On it, ArcadeService asks the helper (new ''pause'' verb) to send SAVE_STATE then PAUSE_TOGGLE, checked with GET_STATUS first so a paused game is not unpaused. On leaving the duty, the resume offer is a chat link, never automatic.', 'It must only watch the pop, never click Commence; that line is absolute. PAUSE_TOGGLE is a toggle, so a lost reply can leave the game running. Standalone PCSX2 and DuckStation have no equivalent command channel, so they get the pad release only. The UDP port is open on localhost to anything on the machine. None of the underlying pad or panel path has been seen in game yet.', 'players who queue while they play something else, roulette grinders', 1, 1, 1, 8, 'stretch', 'days', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-bgm-duck', 'xivarcade', 'Gold Saucer at Home', 'Hush the Orchestrion', 'While an arcade panel has the focus, FFXIV''s music fades down so the chiptune is the only soundtrack, and it fades back when you look away.', 'You focus the Chrono Trigger panel in your apartment and the Mist housing theme slides to a whisper. Click back into the game and it swells again over two seconds. Combat or a cutscene brings it back at once.', 'PadCaptureService already decides five times a second, from GhosttyWire.FocusGet, whether the arcade panel has the focus. Feed the same signal to a small AudioDuck service that reads SoundBgm through Dalamud''s IGameConfig once, lowers it in steps on the framework tick, and restores the remembered value on focus loss, every PadRelease reason and Dispose. A Configuration flag (on by default) and a /arcade duck toggle.', 'IGameConfig writes land in the player''s real config, so a crash mid-duck leaves the music quiet on next launch; store the original in the plugin config and restore it on load. Players who already muted BGM must not have it turned back up. Focus detection depends on ghostty-dalamud and is not yet seen in game.', 'everyone who has heard two soundtracks fight', 1, 1, 1, 6, 'ready', 'hours', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-housing-cabinet', 'xivarcade', 'Gold Saucer at Home', 'The Cabinet in the Corner', 'Give a game a fixed spot in your house or apartment, so it always opens on the same wall or furniture instead of wherever the panel lands.', 'Final Fantasy Tactics always opens on the wall beside your war table, sized like a small cabinet. Walk up, press Play on the wall, and the Ivalice title screen appears where it did yesterday. In a different ward it opens as a normal panel, as before.', 'Today ArcadeService.Play hands one shell line to HostLauncher.RunInCompositor, which sends window.open with only a run field, then finds the panel through window.list. Add an optional placement to GhosttyWire.OpenRun (anchor position, heading, size, territory and house id), stored per game in Configuration and captured with ''/arcade cabinet here'' from the player''s own position. ghostty-dalamud needs a matching window.open parameter or a window.place call; its own furniture-anchor idea covers the house-id side.', 'It depends on a ghostty-dalamud IPC change that does not exist yet. Housing layout and territory ids shift with patches, and panels have no depth test, so a cabinet can show through walls. The panel path has not been observed in game at all.', 'housing decorators, retro collectors, roleplayers', 1, 1, 1, 8, 'stretch', 'weeks', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-crt-glass', 'xivarcade', 'Gold Saucer at Home', 'CRT Glass and Bezels', 'Per-console scanline shaders and a cabinet bezel on the panel, chosen once and kept out of your own RetroArch settings.', 'The SNES shelf gets soft scanlines and a slight curve, the Game Boy a green-tinted LCD grid, the PS2 stays clean. In the dusk light of your island, the panel looks like a set that has been running since 1994.', 'system_cfg_text already appends per-console overrides at launch without touching retroarch.cfg. Add video_shader_enable and a video_shader path, plus input_overlay for a bezel, from a per-console choice in config.json set by ''/arcade look <console> <preset|off>''. The helper only points at shader presets already on disk (RetroArch''s own slang shaders), and the window lists what it found.', 'Shaders cost GPU time inside the agent''s headless compositor on top of FFXIV. Flatpak RetroArch sees only paths passed with --filesystem, so shader folders need adding to launch_argv. Standalone emulators are left out. Bezels shipped with the plugin would need their own licence check, so it starts with none.', 'retro purists, streamers, screenshot takers', 1, 1, 0, 6, 'ready', 'days', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-save-timeline', 'xivarcade', 'Save Crystals', 'Save Timeline', 'A history strip for each game showing every pre-launch backup and synced version, with one button to go back.', 'You overwrote the only save before the point of no return. Open the game''s details, press History, and a strip of dated saves slides out: last night on the desktop, Tuesday on the laptop. Pick Tuesday, confirm, and the current save is backed up before the old one takes its place.', 'backup_saves already keeps the last 10 copies under backups/<game>/<time>/, and Syncthing keeps .stversions in the synced tree. A new helper verb ''history <game>'' lists both into state.json, and ''restore <game> <stamp>'' runs settle() first, then backup_saves on the current files, then copies through the same never-lose rules as copy_if_newer, forced for this one explicit choice. ArcadeWindow''s details strip gets a History button next to Play.', 'Restoring while another machine is playing just creates a conflict, so it must refuse while sync says Syncing or the game is running. Standalone memory cards hold many games at once, so restoring one card rolls back every game on it; the window has to say so. Staggered versioning names are Syncthing''s own format and may change.', 'everyone who has saved over the wrong slot', 0, 1, 1, 7, 'ready', 'days', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-state-slots', 'xivarcade', 'Save Crystals', 'Save State Snapshots', 'See your save states as screenshots in the details strip and start a game straight into the one you pick.', 'Under Final Fantasy IX you see four small frames: Alexandria, the Iifa Tree, a boss you keep dying to, the last autosave. Click the boss frame and the game opens right before the fight, on whichever machine you are on.', 'Turn on savestate_thumbnail_enable in system_cfg_text so RetroArch writes a PNG beside each state in states/<console>/, which already syncs. The helper lists states per game into state.json; ArcadeWindow loads the PNGs through the same background CoverCache thumbnails used for covers. A launch takes an optional slot and launch_argv passes RetroArch''s entry-slot option.', 'The entry-slot flag needs a recent RetroArch and must be checked against the Flatpak version before relying on it. State files are core-specific, so a state from Snes9x will not load in bsnes; show the core with each frame. PCSX2 and DuckStation keep states in their own formats and come later.', 'players juggling several states, speedrun practice', 0, 1, 0, 7, 'stretch', 'days', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-conflict-picker', 'xivarcade', 'Save Crystals', 'Pick the Winning Save', 'When two machines changed the same save, show both side by side and let you choose, instead of renaming files by hand.', 'A gold banner: ''Chrono Trigger: both saves kept''. Open it and you see the desktop''s save from 21:14 next to the laptop''s from 22:40, each with its state thumbnail and play time. The newer one is live; one click makes the other live and keeps both.', 'resolve_conflicts already writes the conflicts table (live, kept_as, both mtimes) and names the loser ''name (older save, device ..., date).srm''. Expose unresolved rows through ArcadeSync.Conflicts in state.json with sizes and device names, add a ''swap <conflict id>'' helper verb that exchanges the two names after a backup_saves call, and draw the pair in ArcadeWindow under the sync status.', 'Newer is not always better, which is the point, but players can still choose wrong; the swap must be reversible and itself recorded. Modification times differ across machines with bad clocks. Needs the sync path tested between two real machines, which has not happened yet.', 'multi-machine players, couples sharing a library', 0, 1, 0, 6, 'ready', 'days', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-handheld-bridge', 'xivarcade', 'Save Crystals', 'Handheld Bridge', 'Setup profiles that make a Steam Deck or an Android RetroArch share the same synced save tree, so you can continue on the sofa.', 'You stop FF Tactics at your desk, pick up the Deck, and the same chapter is waiting in RetroArch there. Back at the desk, /arcade last picks up the Deck''s save, and the status line said ''Syncing...'' until it had fully arrived.', 'The synced tree is already device-neutral: game_id is a hash of system and title, and system_cfg_text turns off per-core sorting. Add ''xiv-arcade sync-setup --profile deck|android'' that prints the matching RetroArch overrides for that device (savefile_directory, savestate_directory, the sort flags) and the Syncthing folder path, like syncthing_folder_commands does today. The plugin shows it as an extra step in the first-run list.', 'Android scoped storage and Syncthing forks make folder paths awkward. EmuDeck and similar setups sort saves per core and may overwrite the overrides. The handheld has no settle gate, so a game started there while saves arrive can still create a conflict.', 'Steam Deck owners, Android handheld players', 0, 1, 0, 7, 'stretch', 'days', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-play-journal', 'xivarcade', 'The Cartridge Shelf', 'Play Journal', 'Hours and sessions per game, from the play history the helper already records, shown on each cover and in a weekly chat line.', 'Selecting Final Fantasy VI shows ''41 h over 23 sessions, last Tuesday''. On Sunday a chat line says you spent 6 hours in the arcade this week, mostly in Ivalice. /arcade journal lists your top ten.', 'The plays table in arcade.db already stores game_id, core, started and ended for every launch. build_state adds total seconds and session count per game to state.json; ArcadeGame gains two fields; ArcadeWindow''s details strip prints them next to last played. A ''journal'' verb in ArcadeCommands prints the summary to chat.', 'arcade.db is per machine, so hours played on the laptop are missing on the desktop unless a small per-machine journal file is put into the synced tree and merged. A crashed emulator leaves ended empty, so sessions need a sensible cap.', 'completionists, stat lovers, backlog keepers', 0, 1, 0, 5, 'ready', 'hours', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-crystal-pilgrimage', 'xivarcade', 'The Cartridge Shelf', 'Crystal Pilgrimage', 'Mark games finished and the Final Fantasy shelf gains a crystal for each one, a quiet record of working through the series.', 'You finish Final Fantasy V and mark it done. Its cover gets a small crystal on the spine and a line across the top of the shelf fills in: 9 of 26. Hover it to see when you finished each one and how long it took.', 'The 26-title shelf is already built from ArcadeShelfEntry and ArcadeGame.Ff keys. Add a finished flag with a date per game id, written by ''/arcade finished <name>'' and a button in the details strip, and kept in a small JSON file inside the synced tree so every machine agrees. CoverLayout draws the crystal mark on both picture and drawn covers; hours come from the play journal when present.', 'Marking is manual on purpose; reading emulator memory to detect an ending would be fragile and is not wanted. The synced file can conflict like any save and needs merge-by-union rules.', 'Final Fantasy fans, series marathoners', 0, 1, 0, 6, 'ready', 'days', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-custom-shelves', 'xivarcade', 'The Cartridge Shelf', 'Shelves of Your Own', 'Make your own shelves, such as Backlog, Couch co-op or Comfort games, and put favourites at the top of the wall.', 'Tab cycles past the Final Fantasy shelf to ''Rainy day'' and ''Two players'', which you made yourself. A star on a cover lifts it to the front of every shelf it belongs to.', 'ArcadeWindow already builds its Section list and CoverGrid per console. Add named shelves and favourites, keyed by the stable game_id, in a shelves file in the synced tree; the helper includes them in state.json and the window adds them as sections after the Final Fantasy shelf. Commands: ''/arcade shelf <name> add|remove <game>'' and a right-click menu on a cover. LaunchBox playlists could be read as starting shelves.', 'More shelves make Tab and L1/R1 navigation slower, so empty shelves should hide. game_id is title-based, so renaming a file to a different title drops it from its shelves.', 'large-library owners, LaunchBox refugees', 0, 1, 0, 5, 'ready', 'days', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-screenshot-covers', 'xivarcade', 'The Cartridge Shelf', 'Covers from Your Own Screenshots', 'Take a screenshot in the emulator and use it as that game''s cover, a bring-your-own picture with no download involved.', 'Your homebrew and fan-translated games all have drawn covers. On the title screen you press the screenshot button, then in the window choose ''Use last screenshot as cover'', and the drawn cover is replaced by the title screen, cropped to the console''s box shape.', 'Point RetroArch''s screenshot_directory at a per-console folder under the helper''s data directory from system_cfg_text. A helper verb ''cover-from-shot <game>'' copies the newest screenshot into the art tree as the game''s own picture, ranked after the player''s covers and before fetched ones in find_boxart. CoverLayout already fits pictures to each console''s box aspect without stretching.', 'The games folder is never written to, so these must live outside it and not in covers/. Screenshots of wide or odd-resolution games crop badly; a crop preview may be needed. Standalone emulators use their own screenshot folders.', 'players with obscure, homebrew or translated games, people who keep cover fetch off', 0, 1, 0, 5, 'ready', 'days', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-dat-verify', 'xivarcade', 'The Cartridge Shelf', 'Verified Dump Badges', 'Check your files against a No-Intro or Redump DAT you supply and mark good dumps, bad dumps and their canonical names.', 'A small check appears on most covers. One PlayStation game shows ''bad dump: track 2 differs'', which explains the crash you had last month. Cover matching improves too, because every verified game now carries its exact canonical name.', 'The player drops Logiqx XML DAT files into a dats/ folder; nothing is downloaded. The helper hashes files in the background (SHA-1 and CRC32, cached in the games table by size and mtime), matches them, and puts the verdict and canonical name into state.json. art_candidates tries the canonical name first. Uses the same content-check approach as check_bios_file.', 'Hashing a PS2 library takes a long time and must be resumable and throttled. CHD and CSO are compressed, so their hashes do not match Redump without chdman or decompression; say ''not checkable'' rather than guess. DAT files have their own licensing and must never be bundled.', 'archivists, collectors, anyone debugging a game that will not boot', 0, 1, 0, 5, 'stretch', 'days', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-lantern-netplay', 'xivarcade', 'Arcade Linkshells', 'Link Cable over Lantern', 'Invite a friend from XivLantern to a RetroArch netplay session of a game you both own, with the connection details passed privately between you.', 'You and your static both have Secret of Mana. In your Lantern channel you press ''Play together''. Their chat shows an invite with the cover. They accept, and a second controller joins on your panel while you both stand in the FC house.', 'The helper''s launch_argv gains RetroArch''s host and connect netplay modes. XivArcade offers a new IPC call beside XivArcade.v1.Search and Launch that builds an invite: game_id, core name and version, content CRC and a tailnet or LAN address, never the file. XivLantern carries it peer to peer, and the receiving XivArcade checks that the same game_id with the same CRC is in its own library before offering Join.', 'The hard line holds: no game file, disc or BIOS ever travels, and a CRC mismatch refuses. NAT traversal is hard without Tailscale or a relay. Netplay needs identical core versions and breaks with standalone emulators. Needs a Lantern IPC hook that does not exist yet, and RetroArch netplay latency inside a headless compositor is unknown.', 'friend groups, statics, couch co-op fans who now live apart', 1, 1, 1, 9, 'stretch', 'weeks', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-umbra-widget', 'xivarcade', 'Arcade Linkshells', 'Now Playing Widget', 'An Umbra toolbar widget showing the running game and save-sync state, with one click to resume the last game.', 'Your toolbar shows a small cartridge icon and ''FF VI, saves in sync''. When the other machine is still sending saves it turns amber and reads ''Syncing...''. Click it and a popup lists your last five games with Resume buttons.', 'Follow the pattern ghostty-dalamud uses for its Umbra.Ghostty widget, without an assembly reference. ArcadeService.State already carries PlayingTitle, Sync.Code and the play history, so the widget reads them through a new XivArcade.v1.Status IPC call and launches through the existing XivArcade.v1.Launch.', 'Umbra''s widget API changes between versions, and XivArcade must keep working with Umbra missing. The status call must be cheap, because toolbars poll often.', 'Umbra users, anyone who closes the Arcade window', 0, 1, 0, 5, 'ready', 'days', 14, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-almanac-names', 'xivarcade', 'Arcade Linkshells', 'Ask the Local Model for a Name', 'When cover matching fails, ask your own local model through Almanac for the game''s canonical name, and keep the answer only if it really exists in the console''s list.', 'Forty files named like ''ff5_rpge_v1.1'' have drawn covers. You press ''Ask Almanac'' and one by one the covers fill in, each with a small note: ''matched by name suggestion''. The two it could not place stay drawn.', 'This is the TODO already written in docs/ARCADE.md. The helper writes unmatched names and their console''s cached Named_Boxarts list to state.json; the plugin sends each to Almanac.Ask with a narrow prompt; the answer goes back through a new helper verb and art_match accepts it only if it is exactly one entry in that list. XivMcp stays out of it, as the doc says.', 'Needs a request and response bridge between the in-game IPC and the host helper, which is why it was left out. Small local models invent names; the exact-list check makes that safe but may leave most games unmatched. Slow on modest GPUs, so it must run in the background and be cancellable.', 'players with messy file names who turned cover fetch on', 0, 1, 0, 6, 'research', 'weeks', 15, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('arcade-almanac-hints', 'xivarcade', 'Arcade Linkshells', 'Stuck? Ask the Scholar', 'A spoiler-careful hint button for the game you are playing, answered by your local model through Almanac, with nothing leaving your machine.', 'You have walked around the Phantom Forest for ten minutes. You open the details strip, type ''where is the train'', choose ''nudge, no spoilers'', and get two lines back in the Almanac chat. It says it is not sure when it is not sure.', 'ArcadeWindow''s details strip gets a Hint box that calls Almanac''s IPC with the game''s title, console and year from ArcadeGame plus the player''s own question and a spoiler level. XivArcade sends nothing else: no emulator memory, no screenshots. The reply opens in Almanac''s own chat window.', 'Local models know little about most 1990s games and will invent walkthrough steps; the answer needs a clear ''model guess'' label. Depends on Almanac being installed and a model loaded. Adds one more optional cross-plugin IPC to test.', 'first-time players of old games, families', 0, 1, 0, 5, 'stretch', 'days', 16, 1, 0)
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Aetheryte Plaza', 'Finding, starting and trusting the apps you launch from /desktop and the Super+D palette.', 0, 'xivdesktop') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Apartment Wards for Windows', 'Workspaces, layouts and a taskbar that remember how you arrange your desktop across Eorzea.', 1, 'xivdesktop') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Linkpearl to the Linux Host', 'Carrying clipboards, notifications, files and tool calls between the game session and the desktop it runs on.', 2, 'xivdesktop') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Duty Finder Manners', 'Keeping the desktop out of the way when the game needs your attention, and out of shot when others are watching.', 3, 'xivdesktop') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-doctor', 'xivdesktop', 'The Aetheryte Plaza', '/desktop doctor', 'One command that walks every layer between the palette and a visible window, and says which one is broken, with evidence.', 'Nothing opens when you pick Firefox. You type /desktop doctor and a small checklist fills in line by line: catalog 214 apps, Ghostty Call gate present, agent answering, compositor up, test launch queued, panel id 7 mapped. The fourth line is red: the agent is running without --windows wayland, and the fix is printed beside it.', 'A DoctorService in XivDesktop.Plugin runs the checks in order off the framework thread: CatalogService snapshot count and scan time, IpcContract.GhosttyCall/GhosttyPost HasAction, agent.status and focus.get through GhosttyCallBackend, then an opt-in launch of a harmless app and a wait for its request id to resolve in window.list''s requests. Each step is a pure record in Core (step, evidence, verdict, fix) so the reasoning is host-testable; the result renders in a small ImGui window and can be copied as a redacted report for the issue template the README asks for.', 'It can only report what the IPC tells it; a mapped panel is still not proof the player can see it. The test launch starts a real program on the host, so it must be explicit and use something the player picks. The copied report must strip home paths, tokens and window titles.', 'every new player setting it up, and whoever answers their issues', 0, 1, 1, 6, 'ready', 'days', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-open-with-file', 'xivdesktop', 'The Aetheryte Plaza', 'Open With, from inside the game', 'Pick a file in an in-game file dialog and open it in the right host app, using the %f and %u codes the Exec parser already knows about.', 'You want the fight notes PDF beside you before a prog session. Palette, type ''open'', choose the file from ~/Documents in a Dalamud file dialog, and the palette offers the three apps whose MimeType claims PDFs. A panel with the document lands at your shoulder.', 'ExecLine.StripFieldCodes currently expands %f %F %u %U to nothing; add a variant that substitutes one or many shell-quoted Linux paths. DesktopEntryParser keeps MimeType; AppCatalog builds a mime index. The picker is Dalamud''s FileDialogManager over Z:\, and HostPaths maps the chosen Wine path back to the Linux path before it goes to window.open. A new PaletteCommand kind ''open'' and a right-click ''Open file with…'' in LauncherWindow.', 'Mime detection needs a guess from the extension or the agent running xdg-mime; Wine cannot see everything the host can. Flatpak apps need their --file-forwarding markers kept rather than dropped. Paths with odd characters are exactly where quoting bugs hide, so this needs fuzz tests beside FuzzTests.', 'raiders with notes and spreadsheets, writers, anyone who opens files more than apps', 0, 1, 1, 6, 'stretch', 'days', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-desktop-actions', 'xivdesktop', 'The Aetheryte Plaza', 'Right-Click Actions from the .desktop File', 'Show each app''s own [Desktop Action] entries, such as a new private window or a compose message, as palette row actions.', 'Highlight Firefox in the palette and the hint row reads Enter launch, Ctrl+P private window. Thunderbird offers Compose. It feels like the host''s launcher, because it is reading the same file.', 'DesktopEntryParser ignores every group but [Desktop Entry]; parse the listed Actions groups into DesktopEntry.Actions (name, Exec, Icon) and run each Exec through ExecLine like the main one. PaletteEngine.RowActions appends them after the built-in actions; LauncherWindow''s context menu lists them under Launch. AppSummary gains an optional actions list, an additive change to IpcContract.', 'Chord assignment for arbitrary actions can collide with existing row keys, so only the first few get one. Some apps put odd things in actions that assume a running session bus.', 'keyboard-first players, anyone used to a full desktop launcher', 0, 1, 0, 4, 'ready', 'hours', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-svg-icons', 'xivdesktop', 'The Aetheryte Plaza', 'Real Icons, Not Letter Tiles', 'Have ghostty-agent rasterise SVG-only icons once on the host so the grid and taskbar stop falling back to letter tiles.', 'Half your grid used to be coloured squares with a single letter. After one rescan, the Inkscape, GIMP and Steam icons are there at the grid''s icon size, and they stay after a restart.', 'IconResolver already reports IconKind.SvgOnly. Collect those names after a scan and ask the agent for a PNG cache path per name at Configuration.IconSize (a new agent method, rendered with whatever the host has, such as rsvg); cache under XDG_CACHE_HOME keyed by source path and mtime, then map through HostPaths.ToLocal so ITextureProvider opens it. No new dependency in the plugin.', 'Needs a ghostty-dalamud and agent change, so it only helps players on a matching build. Without the agent, letter tiles remain. Icon themes vary; the cache has to be invalidated when themes change.', 'everyone who opens the app grid', 0, 1, 0, 4, 'stretch', 'days', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-record-chord', 'xivdesktop', 'The Aetheryte Plaza', 'Press the Chord to Bind It', 'Record a key chord by pressing it in Settings, and be told straight away if Wine never delivered it.', 'Settings, Keybinds, click the terminal row and press Super+Enter. Nothing arrives: the row says ''no key seen in 3 seconds, your desktop may be taking Super''. You press Ctrl+Alt+Enter instead, it records, and a small warning notes the game''s own binding for that chord.', 'KeybindService already reads IKeyState with a GetAsyncKeyState fallback; add a capture mode that suspends ChordTracker, waits for the first non-modifier key and builds a KeyChord from the held modifiers, then writes it to Configuration.Keybinds through the existing SettingsWindow Keybinds tab. The timeout message is the useful part: it is the first direct evidence of whether Wine passes the modifier at all.', 'The game still acts on the keys while recording, so a chord bound to a game action fires once. Some compositors only drop Super on release. Cannot see what the game has bound without reading keybind data, so the conflict hint stays heuristic.', 'everyone setting up keys, especially GNOME and KDE users whose desktop eats Super', 0, 1, 0, 5, 'ready', 'hours', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-macro-lines', 'xivdesktop', 'The Aetheryte Plaza', 'Apps on Your Hotbar, by Macro', 'A palette action that copies a ready /desktop launch line for any app, so it can live in a user macro on your hotbar.', 'Highlight Blender, press Ctrl+M, and the palette says ''copied /desktop launch org.blender.Blender''. Paste it into a User Macro, give it an icon, drag it to your crafting bar. Now the tool you plan melds in is one slot away.', 'PaletteCommand.Copy already exists and LauncherWindow already has ''Copy command''. Add a RowAction in PaletteEngine.RowActions that copies ''/desktop launch <desktop-file id>''; the plugin''s command handler already resolves ids first. The id is stable across rescans, unlike the name.', 'XivDesktop does not write the macro itself; touching the game''s macro data is out of bounds, so the player pastes by hand. Macros are shared per character and can be synced; an id for an app you later remove just fails with a message.', 'crafters, hotbar-minded players, controller players', 1, 1, 0, 4, 'ready', 'hours', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-controller-ring', 'xivdesktop', 'The Aetheryte Plaza', 'Controller Ring Launcher', 'A radial app ring on the gamepad for Steam Deck and couch players, with favourites on the sticks and workspaces on the shoulder buttons.', 'On the Deck, hold a chosen button combo and your eight favourites fan out in a ring. Flick the stick toward the browser and release; the window lands as a pet. L1 and R1 step through workspaces while the ring is up.', 'Read IGamepadState in KeybindService alongside IKeyState and feed a pad chord into ChordTracker. The ring is a new ImGui window drawing UserLists favourites with IconDrawer; stick angle picks a sector. Launch and workspace steps go through CommandRunner, so nothing new reaches Ghostty.', 'Any button combo the ring uses is also read by the game; it must be a chord the player chooses and ideally one the game leaves unbound. Panel apps still want a keyboard, so this launches and arranges, it does not make a browser controller-friendly.', 'Steam Deck players, controller players, couch setups', 1, 1, 0, 7, 'stretch', 'days', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-glamour-plate-layouts', 'xivdesktop', 'Apartment Wards for Windows', 'Glamour Plates for Your Desk', 'Save a named set of apps and placements, and put the whole arrangement on with one palette entry.', 'Type ''>plate raid'' and your prog layout goes on like a glamour: the spreadsheet docked left, the timeline tool as a pet, voice chat on workspace 2. ''>plate cozy'' swaps to a music player and a book for the inn room. Each plate shows its pieces before you apply it.', 'A Layout record in Core (app id, workspace, pin args, order) with a pure planner that diffs it against the current window list, the way WorkspaceModel.Plan already diffs visibility. Applying launches missing apps through window.open, waits for request ids to resolve in window.list''s requests, then issues window.place and the workspace moves. Saved in Configuration beside Workspaces; exposed as palette rows and an additive XivDesktop.v1 gate.', 'Windows appear asynchronously and some apps open several windows or a splash first, so matching window to app is fuzzy (WindowApps helps). Placement arguments are relative to the character, so the same plate lands differently in different spots. Launching six apps at once is slow.', 'raiders, crafters, streamers, anyone with more than three regular apps', 1, 1, 1, 7, 'stretch', 'days', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-zone-layouts', 'xivdesktop', 'Apartment Wards for Windows', 'The Desk Knows Where You Are', 'Bind a layout or workspace to a territory, so your house, the inn and Limsa each get their own arrangement back when you arrive.', 'You enter your apartment and the reading lamp app and the notes panel reappear where you left them by the window. Teleport to Ul''dah for the market and they fold away, leaving only the price sheet. Nothing moves in duties unless you said so.', 'Subscribe to IClientState.TerritoryChanged in SessionService (AskService already does). A small Core map from territory id, and for housing the ward and plot where the client state exposes it, to a plate name or workspace number. On change, run the same layout planner as named plates. The Configuration gains a per-territory table; ARCHITECTURE.md already lists this as planned.', 'Zone changes happen while panels are mid-request; everything must wait until the load finishes. Housing identifiers are less stable than territory ids across patches. Instanced areas share a territory, so the match may be coarser than the player expects.', 'housing enthusiasts, roleplayers, crafters and gatherers with a home base', 1, 1, 0, 7, 'stretch', 'days', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-gearset-workspaces', 'xivdesktop', 'Apartment Wards for Windows', 'Change Job, Change Desk', 'Link a gearset or job to a workspace, so switching to a crafter brings the crafting spreadsheet and switching to a tank brings the raid notes.', 'You click your Carpenter gearset. As the gear swaps, workspace 3 slides in with the rotation sheet and the market board notes. Back to Warrior for roulettes, and it returns to the quiet workspace with only chat.', 'Poll the local player''s ClassJob once per frame in the IFramework.Update tick KeybindService already runs, or on a class-change event where Dalamud offers one. A Configuration map from ClassJob row id to workspace number, applied through SessionService''s existing workspace switch and WorkspaceModel.Plan. Only the player''s own job is read.', 'Fast gear swaps must be debounced. Switching workspace hides panels; a hidden video keeps playing sound, so this can surprise. Must never fire in a duty unless enabled separately.', 'crafters and gatherers, job-hopping players, raiders', 1, 1, 1, 7, 'ready', 'days', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-scratchpad', 'xivdesktop', 'Apartment Wards for Windows', 'The Chocobo Saddlebag Scratchpad', 'A sway-style scratchpad: stow any panel out of sight with one chord and summon it back to your shoulder with another.', 'The calculator app and a music player live in the saddlebag. Super+minus stows the focused panel. Super+grave brings the most recent one back as a pet beside you, and pressing it again cycles to the next thing in the bag.', 'Add a scratchpad as workspace 0 in WorkspaceModel (outside Count''s 1-9), so Plan hides its panels regardless of the current workspace. Two new KeyAction entries in Core/Input/Keybinds.cs with defaults, handled in CommandRunner; summoning uses window.hide off plus window.toggle_pet or window.place with the configured PinArgs.', 'Needs window.hide from the newer Ghostty methods; on older backends it falls back to minimise or is unavailable. Workspace persistence must not treat 0 as an orphan to clean up.', 'sway and i3 users, anyone with small tools they check often', 1, 1, 0, 5, 'ready', 'hours', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-taskbar-icons', 'xivdesktop', 'Apartment Wards for Windows', 'Proper Icons on the Umbra Taskbar', 'Show each open window''s real app icon in the Umbra Windows widget instead of a letter tile.', 'Your toolbar reads like a desktop panel: the browser globe, the terminal, the chat app, each with the workspace number beside it. The one that just opened has a thin highlight for a few seconds.', 'WindowsWidget.Item sets a LetterTile colour and letter today. Add an optional icon path to AppSummary and the Windows payload in IpcContract (additive, as the contract requires), filled from CatalogService''s resolved PNG path, and let the widget load it through Una.Drawing''s image style. Falls back to the letter tile when absent.', 'The Umbra layout and the reflection-based popup workaround are themselves unverified in game. Icon textures must be loaded once and shared, not per redraw. Depends on desk-svg-icons for full coverage.', 'Umbra users', 0, 1, 0, 4, 'ready', 'days', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-clipboard-bridge', 'xivdesktop', 'Linkpearl to the Linux Host', 'One Clipboard for Both Worlds', 'Copy in a host app panel and paste into game chat, or the other way round, through the agent.', 'You copy a PF description out of the browser panel and paste it straight into the Party Finder comment box. Later you copy a player''s macro text from chat and paste it into your notes app. No alt-tab, no second clipboard to think about.', 'The game side is Wine''s Windows clipboard, reachable from the plugin through ImGui''s clipboard functions. The compositor side needs ghostty-agent to act as a Wayland data-device client in its own compositor. XivDesktop would watch for a change on either side and relay text only, with a size cap, through a new agent method; PaletteCommand.Copy already writes the game side.', 'Needs agent work in ghostty-dalamud. Password managers put secrets on the clipboard, so relaying must be opt-in, text only and skip sensitive MIME hints. Two-way sync loops need care. Wine''s clipboard is already bridged to the host X11 or Wayland session on some setups, which could produce three clipboards fighting.', 'everyone who uses a browser panel, raid leaders, crafters copying rotations', 0, 1, 0, 7, 'research', 'weeks', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-app-notifications', 'xivdesktop', 'Linkpearl to the Linux Host', 'Moogle Delivery for App Notifications', 'Show notifications from apps running in the compositor as Dalamud toasts, with the app''s icon and a click that focuses its panel.', 'Mid-roulette, a small toast slides in: your chat app, one new message from your partner. You finish the pull, click the toast, and the chat panel comes forward on its workspace.', 'The agent owns org.freedesktop.Notifications on the session bus it gives its compositor''s apps and forwards summary, body and app id as a new event in window.list or a separate method. SessionService already raises Dalamud notifications through INotificationManager for panel open and end; extend Notify with the app''s icon from CatalogService and a click that runs PaletteCommand.Focus.', 'Depends entirely on agent changes and on apps using the session bus the agent controls. Notification bodies are private and would show on stream; needs a ''title only'' option. Rate limiting is needed for chatty apps.', 'everyone who keeps chat or mail apps in a panel', 0, 1, 0, 6, 'stretch', 'weeks', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-xivmcp-tools', 'xivdesktop', 'Linkpearl to the Linux Host', 'Let XivMcp Drive the Desk', 'Ship the planned list_apps, launch_app, list_windows, window_action, switch_workspace and palette_search tools in XivMcp, on top of the XivDesktop.v1 gates that already exist.', 'You ask your local model to ''set me up for the savage prog''. It lists your apps, opens the timeline sheet and the recording tool, puts them on workspace 2 and tells you which ones it could not find, all through tools you can see and approve.', 'The gates are in src/Shared/IpcContract.cs (ListApps, Launch, Windows, Workspace, Palette, WindowAction) with parse helpers already. XivMcp registers thin tools that call them and return the JSON as is. Launch returns queued, not done, so launch_app should poll Windows for the new panel before reporting success.', 'A model that can launch apps can run programs on the host; launch_app needs a per-call confirmation or an allow list, the way the Claude permission dialog works. Tool results must say ''queued'' honestly rather than ''opened''. Lives mostly in another repository.', 'Almanac and Claude users, automation-minded players', 0, 1, 0, 6, 'ready', 'days', 14, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-send-to-game', 'xivdesktop', 'Linkpearl to the Linux Host', 'Send This Window to Eorzea', 'A GNOME Shell entry that hands a window already running on your desktop to the game as a panel.', 'You are reading a guide in the host browser, then launch the game. From the browser''s window menu you choose Send to game, and a moment later that same page is floating as a pet beside your character, still scrolled to the same place.', 'Moving an already-mapped window into the agent''s compositor is not possible as such; GUIDE.md''s planned route is the agent capturing it through the desktop portal''s screencast, as it does on Windows. A small Shell extension calls the agent (not Wine) with the window''s identity; the agent starts a capture and the game gets a window.open with a match. XivDesktop''s part is palette and taskbar support for captured panels.', 'A captured window is a picture plus forwarded input, not a native panel; input forwarding through the portal is limited. The portal prompts the user every time on many setups. GNOME extension APIs change every release. Nothing of this exists yet.', 'GNOME users, people who run the game as one part of their desktop', 1, 1, 0, 8, 'research', 'weeks', 15, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-duty-pop-stow', 'xivdesktop', 'Duty Finder Manners', 'Stow the Desk When the Duty Pops', 'When you enter a duty or combat starts, hide every window panel, and put them back exactly as they were when it ends.', 'The queue pops while you are reading a wiki panel. You commence, and the panels fold away before the first loading screen. After the last boss, as the chest appears, they return to the same workspace and positions.', 'Plugin.cs already receives ICondition (AskService uses it). A DutyGuard in SessionService watches BoundByDuty and InCombat with a short settle delay, remembers WorkspaceModel''s state, and hides everything through the same Plan and window.hide path workspaces use; the exit restores it. Per-condition toggles in Settings, General, plus an exception list for apps the player wants kept, such as voice chat.', 'Hiding is presentation only: a video keeps playing and audio keeps going. If a panel owns the keyboard when a pull starts, focus must return to the game first or it is dangerous. Condition flags flicker around cutscenes and zoning, so a naive watcher will thrash.', 'everyone who queues with panels open, healers especially', 1, 1, 1, 7, 'ready', 'days', 16, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('desk-privacy-veil', 'xivdesktop', 'Duty Finder Manners', 'The Veil', 'One chord, or GPose starting, hides private panels and blanks window titles in the palette, taskbar and notifications.', 'You enter GPose for a party photo. Your mail and chat panels disappear, the Umbra taskbar reads ''Window, Window, Window'', and the open and close toasts stop naming apps. Leave GPose and it lifts.', 'A Veiled flag in SessionService, set by a new KeyAction and by IClientState''s GPose state. When set, PaletteEngine gets a context with titles masked, the Windows gate returns masked titles to the Umbra widget, SessionService.Notify drops names, and panels tagged private in Configuration are hidden through window.hide.', 'XivDesktop cannot mask the contents of a panel it hides late: anything captured in the first frame is already out. Other plugins drawing window titles are not covered. It must be clear this reduces exposure, not a guarantee.', 'GPose photographers, streamers, anyone sharing screenshots', 1, 1, 0, 6, 'ready', 'hours', 17, 1, 0)
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Whose Lantern Is Lit', 'Presence and the friend list: knowing who is about, and saying what you are up to, without the game telling anyone.', 0, 'xivlantern') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Linkshells of Your Own', 'Channels you make and hand out, grown into something a static or FC can live in.', 1, 'xivlantern') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Voices in the Aether', 'Calls between friends, built so that a codec crash can never take the game down with it.', 2, 'xivlantern') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Letters That Find You', 'Messages and friends that follow a person across time offline and across devices.', 3, 'xivlantern') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Lamplighter''s Keys', 'Identity, trust and the author channel: who you are talking to and how your keys are kept.', 4, 'xivlantern') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-status-presets', 'xivlantern', 'Whose Lantern Is Lit', 'Status Presets', 'Save a handful of status-and-note pairs and switch between them with one click or one short command.', 'Raid night: you type /lantern as raid and your lantern goes busy with ''prog, back at 23:00''. Afterwards /lantern as chill flips it to online with ''maps? roulettes?''. Your static sees the note change in their list within one heartbeat.', 'Add a List<StatusPreset> (name, presence, note) to Configuration. Command.Parse gains an ''as <preset>'' verb beside ParseStatus; Plugin.OnCommand resolves it and calls the existing LanternService.SetPresence. MainWindow.DrawMe gets a small preset combo next to the presence combo and note field. Parsing is BCL-only, so it is host-tested in XivLantern.Core.Tests like the rest of Commands.', 'Very little. Preset names must not collide with existing subcommands (on, off, invite), so they sit behind ''as''. Notes are still typed text and are clamped by the same length limit.', 'raiders, statics, anyone who forgets to change their note', 0, 1, 0, 4, 'ready', 'hours', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-idle-away', 'xivlantern', 'Whose Lantern Is Lit', 'Away When You Walk Off', 'Opt in, and your lantern dims to away after a few minutes with no keyboard or mouse input, and lights again when you come back.', 'You leave the game running and go to make tea. Ten minutes later your friends see you as away with the note you left. You touch the mouse and you are online again before anyone asks.', 'A Framework.Update tick in LanternService (it already polls lt_poll there) checks OS idle time through GetLastInputInfo, never game state, and calls SetPresence with LT_PRESENCE_AWAY once past a threshold set in Configuration, restoring the previous presence and note on input. Off by default, shown in DrawSettings with the other switches.', 'GetLastInputInfo under Wine reports X11/Wayland input only as well as Wine forwards it; controller-only players may look idle while playing. It must never override a status the player set by hand (busy, invisible), and the banned-API test in CoreTests must keep passing, so no IClientState shortcuts.', 'everyone who leaves the client open', 0, 1, 0, 4, 'ready', 'hours', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-lfg-tags', 'xivlantern', 'Whose Lantern Is Lit', 'Up For It Tags', 'Tick a few typed tags (maps, roulettes, crafting, ex, chat) and friends can filter the list to people who want the same thing tonight.', 'You fancy a treasure map run. You tick ''maps'', open the list and filter by it: two friends lit up with the same tag. One message later you have a party, and nobody had to shout in an FC channel.', 'Extend Wire::Heartbeat in crates/lantern-core/src/node/friends.rs with a tags field, or better add a new Heartbeat2 variant at the end of the enum so old nodes keep decoding, and store tags beside status/note for each friend device. Surface them in lt_friend_list JSON, FriendView and GetFriends over IPC. MainWindow.DrawList gains a filter chip row. Tags are chosen from a fixed list plus free text the player types; nothing comes from the game.', 'A wire change needs a compatibility plan: postcard enums break if variants are reordered, and mixed versions will run side by side for weeks. Free-text tags need the same clamping and ChatText.Clean treatment as notes. Tempting to auto-fill from the duty finder, which the design forbids.', 'friend groups, FCs, casual players', 0, 1, 0, 6, 'stretch', 'days', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-friend-groups', 'xivlantern', 'Whose Lantern Is Lit', 'Friend Folders', 'Sort friends into your own folders (static, FC, crafting pals) that collapse and show how many in each are lit.', 'Your list has grown to thirty. Now it reads ''Static 6/8'', ''FC 3/14'', ''Old server 0/5''. You collapse the old server folder and the people who matter tonight are at the top.', 'Groups are local only: a Dictionary<string, string> from node id to folder in Configuration, never sent to anyone. MainWindow.DrawList renders ImGui.CollapsingHeader per folder with an online count from service.Friends, and a right-click menu on a friend to move them. Mutes keep using the existing Muted keys, so a folder can be muted in one step by toggling each key.', 'Folders keyed by node id split when a friend reinstalls (new NodeId), until nostr device lists merge devices into one person. Drag and drop in Dalamud ImGui is fiddly; a context menu is the safer first cut.', 'people with long friend lists, FC officers', 0, 1, 0, 4, 'ready', 'hours', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-dtr-roster', 'xivlantern', 'Whose Lantern Is Lit', 'Glance at the Server Bar', 'Hover the Lantern entry in the server info bar to see who is lit and their notes, without opening the window.', 'Mid-dungeon, the bar says ''Lantern 3 · 1 unread''. You hover it: ''Alice, away: crafting'', ''Bob, online'', ''Cid, busy: prog''. You finish the pull and answer later.', 'Notifier already owns the IDtrBarEntry and refreshes its text on a timer from service.Friends and Book.TotalUnread. Set the entry''s Tooltip to a short roster built by a pure function in XivLantern.Core (sorted online first, names through ChatText.Label, notes through ChatText.Preview) so it is host-tested. Clicking still calls toggleWindow.', 'Tooltips are SeString, so friend-typed names and notes must be escaped so they cannot inject payloads or colour codes. Long lists need a cap (''and 7 more''). Hidden while streaming would be a sensible option, since the bar is often on screen.', 'everyone, especially people who keep the window closed', 0, 1, 0, 5, 'ready', 'hours', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-channel-history', 'xivlantern', 'Linkshells of Your Own', 'Catch Up on Join', 'Someone who joins or comes back to a channel gets the recent backlog from any member who has it, instead of an empty room.', 'You log in after work and open #static. Instead of silence you see the last hour: the pull times, the strat link, ''who has the sprint macro?''. Each line still carries its author''s verified signature.', 'DESIGN.md already names the shape: a blob snapshot offered by any member. Keep the signed gossip frames per channel in a new store table, and on a peer''s Hello offer a snapshot with lt_blob_add_bytes and lt_blob_offer, which exist in the C ABI and the C# binding (BlobAddBytes, BlobOffer, BlobFetch) but are unused by the plugin today. The joiner fetches, re-verifies every frame with proto.rs, de-duplicates by signature and merges into ChatBook through Conversation.LoadHistory.', 'Gossip gives no ordering, so merged history needs a sort by sender timestamp that a member could lie about. Every member keeps a copy, which makes ''delete'' meaningless and should be said plainly. Snapshot size and how far back need limits, and a malicious member can offer junk, so verification must drop anything unsigned.', 'statics, FCs, anyone in a channel across time zones', 0, 1, 1, 7, 'stretch', 'weeks', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-sealed-channels', 'xivlantern', 'Linkshells of Your Own', 'Sealed Channels', 'Channel messages encrypted with a key carried in the ticket, so relays and nodes passing gossip along cannot read them.', 'You make #static as sealed. Friends join exactly as before, but the channel shows a small lock, and a gossip neighbour who happens to relay frames sees only ciphertext. When someone leaves the static, you reseal and send the new ticket to the people who stay.', 'Add a symmetric key to the ltroom ticket in ticket.rs and encrypt the payload inside the signed frame in proto.rs (XChaCha20-Poly1305, signature over the ciphertext). Scope::Custom topics stay random. ''Reseal'' makes a new channel with a new key and sends ChannelInvite over each chosen friend link, which friends.rs already does. The plugin shows a lock in DrawList and the ticket wording changes in DrawAdd.', 'Anyone holding the ticket still reads everything; this protects against the swarm, not against members. Removing a member is only a reseal, and old keys still read old history. A ticket format change needs a version byte and a clear message on old clients.', 'statics, FCs, privacy-minded players', 0, 1, 0, 6, 'stretch', 'weeks', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-pull-timer', 'xivlantern', 'Linkshells of Your Own', 'Channel Pull Timer', 'A countdown anyone in a channel can start, drawn on every member''s screen, without touching the game''s own countdown.', 'Your raid lead types /lantern pull 10 in #static. A calm 10, 9, 8 appears on everyone''s screen at the same moment, with a soft chime at zero. The game''s /countdown is left alone for the party leader.', 'Channel messages are plain text today (LanternService.SendToChannel calls RoomSend with the string). Add a small structured envelope with a reserved prefix that carries a duration, not a clock time, parsed in XivLantern.Core and tested there. Command.Parse gains ''pull <seconds> [channel]''. The plugin draws an overlay window with no inputs and a toast through the existing INotificationManager at zero. It never sends /countdown or any game command.', 'Old clients show the envelope as a raw line, so the prefix must read sensibly as text. Relay latency makes timers drift by a few hundred milliseconds between members. People will ask for it to start the game''s countdown; that is a game command and stays out.', 'statics, raid leaders, event organisers', 0, 1, 1, 6, 'ready', 'days', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-share-screenshot', 'xivlantern', 'Linkshells of Your Own', 'Pass a Picture Along', 'Share a screenshot or small file with a friend or channel, peer to peer, shown as a thumbnail you choose to open.', 'You finally clear the fight and drop the clear screenshot into #static. Everyone sees ''Alice offered clear.png, 2.1 MB''; a click fetches it straight from Alice''s node and shows it in the chat pane.', 'The network half exists: lt_blob_add_file, lt_blob_offer, lt_blob_fetch and LT_EV_BLOB_OFFER/PROGRESS/DONE are in lantern.h and wrapped by LanternNode.BlobAddFile/BlobOffer/BlobFetch. The plugin needs a picker (a path field or drag from the file system), an offer line in ChatBook, fetch on click into a folder under the plugin config directory, and a thumbnail through ITextureProvider for PNG and JPEG only. For 1:1, offer over the friend link rather than a room.', 'Decoding untrusted images in the game process is a crash and exploit surface; fetch must stay click-to-accept, capped in size, and blocked or muted peers ignored. Screenshots leak names and chat, so the offer dialog should say so. Blob storage grows on disk and needs a cleanup setting.', 'statics, friends, GPose photographers', 0, 1, 1, 6, 'stretch', 'days', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-voice-sidecar', 'xivlantern', 'Voices in the Aether', 'Ring a Friend', 'One-to-one voice calls: ring from the friend list, and the audio runs in a small companion process beside the game.', 'You right-click Bob and choose Ring. His Lantern chimes with ''Alice is calling''; he answers, and you are talking, no server and no other app to open. Mute and hang up sit in the Lantern window.', 'Follows DESIGN.md''s call plan. Signalling already exists as a spike behind the calls feature (node/calls.rs: CallRing, CallAnswer, CallHangup with an iroh://<node>/call/<id> media URL); it needs C ABI events and a MainWindow call bar. Media runs in a lantern-media sidecar using moq-native with iroh and moq-audio against PipeWire (or WASAPI on Windows), paired to the plugin''s node by a one-time ticket like a friend invite and driven over a loopback friend link.', 'None of the media path has been built; DESIGN.md lists four observable steps before anything is in the game. Shipping and starting a second executable from a Dalamud plugin is unusual and must be explicit to the player. Echo cancellation, NAT traversal for UDP media and latency are all unmeasured.', 'friends, duos, statics that do not want a separate voice app', 0, 1, 1, 9, 'stretch', 'weeks', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-voice-in-process', 'xivlantern', 'Voices in the Aether', 'Voice Without the Sidecar', 'Try running Opus capture and playback inside lantern.dll itself, under the game''s Wine, so voice needs nothing else installed.', 'You install one plugin and nothing else. Ring a friend, and it just works, on Windows and on a Steam Deck under Proton alike.', 'Step 5 of DESIGN.md''s call plan: build moq-audio (unsafe-libopus, cpal, sonora AEC) for x86_64-pc-windows-gnu in the same container that builds lantern.dll, repeat the WINE.md evidence method with a test prefix, and only then consider the game''s prefix. Frames stay off the render thread; the plugin only sees lt_poll events for mute and level.', 'cpal''s WASAPI path under Wine goes through Wine''s audio stack, whose latency and device handling vary by distro. A crash in audio code is a game crash, which is the reason the sidecar exists. It may simply not be good enough, and the honest result could be ''no''.', 'Linux and Steam Deck players, anyone who hates extra installs', 0, 1, 0, 8, 'research', 'weeks', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-fc-hearth', 'xivlantern', 'Voices in the Aether', 'The FC Hearth', 'One container an FC can run on a spare box: an iroh relay, a moq relay for group calls, and an always-on node that keeps channel history.', 'Your FC''s tech person runs one command on their home server. Settings now offer ''Our relay'' with its URL, the FC channel has history even when nobody else was online, and eight of you can be in a call without anyone''s upload melting.', 'Relay choice already supports LT_RELAY_CUSTOM with a URL (Configuration.CustomRelayUrl, Privacy.Relay). Package iroh-relay, moq-relay and a headless lantern-cli node (the CLI already runs author mode, so a ''keeper'' mode that joins listed channels and serves history snapshots fits) as one OCI image with a compose file and a README of who sees what. Group calls use the relay for fan-out per the DESIGN.md plan.', 'Whoever runs it sees IP addresses and timing for everyone who uses it, and holds every channel''s plaintext if channels are not sealed; the privacy note must name them. Home hosting means port forwarding or tunnels. Keeping three services patched is a real commitment for a volunteer.', 'FCs, communities, homelab folks', 0, 1, 0, 7, 'stretch', 'weeks', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-nostr-mailbox', 'xivlantern', 'Letters That Find You', 'Leave It at the Post', 'When a friend has been offline for a while, your message also goes to their nostr inbox, so it reaches them even if you are both never online at once.', 'You play mornings, Bob plays nights. You write ''savage lockout reset, do you want the loot?'' and log off. Bob logs in at midnight and it is there, marked as arrived by post, with no second copy when your nodes do meet.', 'DESIGN.md specifies it: NIP-17 kind 14 rumor, sealed and gift-wrapped to the friend''s DM relays, carrying the Lantern message id so the iroh copy is dropped as a duplicate. The nostr feature already sends invites this way (nostr_send_invite, nostr_check_inbox in node/nostr.rs); extend it to texts in the outbox, then expose nostr in the C ABI, which it is not today, and add a relay list to Configuration.', 'Relays learn who receives messages, when and how big. It needs both people to have opted into nostr keys, and the nostr secret sits unencrypted in SQLite. Relays drop old events on their own schedule, so delivery is best effort and the UI must not promise more.', 'friends across time zones, shift workers, returning players', 0, 1, 1, 7, 'stretch', 'weeks', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-every-device', 'xivlantern', 'Letters That Find You', 'One Friend, Every Device', 'A friend who plays on a PC and a Steam Deck is one entry, and messages reach whichever device they are on.', 'Bob moves from his desk to the sofa with the Deck. His lantern stays lit under one name, and the message you sent while he was switching arrives on the Deck, not on the PC he just shut down.', 'The core already models friends with many devices (friends and friend_devices tables) and verifies nostr device lists (nostr_publish_devices, nostr_fetch_devices, the lantern-device-claim/1 signature). What is missing is text fan-out to all devices with de-duplication by message id across them, the nostr calls in lantern-ffi and include/lantern.h, and a ''this device / add a device'' page in MainWindow.DrawSettings.', 'Delivered and read state across devices gets confusing fast (delivered to the PC, read on the Deck). Adding a device means importing the nsec on each, which moves a secret between machines. DESIGN.md lists this as the known gap because it is real work.', 'Steam Deck and multi-PC players', 0, 1, 0, 6, 'stretch', 'weeks', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-invite-by-npub', 'xivlantern', 'Letters That Find You', 'Invite by Name Card', 'Send a friend invite to someone''s nostr npub or name@domain instead of pasting a ticket through a tell or Discord.', 'Your friend''s profile says their Lantern name is cid@example.org. You type it into Add, press Invite, and a day later they see ''Alice invited you'' in their Add tab, ready to accept or ignore.', 'nostr_send_invite and nostr_check_inbox are implemented and tested against an in-process relay (tests/nostr.rs), raising NostrInvite without redeeming anything. Add them to lantern-ffi as new LT_EV_* events, NIP-05 resolution as DESIGN.md describes, and an npub field plus pending list in MainWindow.DrawAdd. Accepting still goes through AcceptInvite, so nothing is accepted for the player.', 'A public npub invites spam; rate limits and ignore must apply to nostr invites too. NIP-05 depends on someone''s web server being up. It adds a third party (nostr relays) that the privacy note must name.', 'players who meet outside the game, streamers with public npubs', 0, 1, 0, 5, 'stretch', 'days', 14, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-pocket', 'xivlantern', 'Letters That Find You', 'Lantern in Your Pocket', 'A small phone app that is one more of your devices, so you can see who is lit and answer a message away from the PC.', 'You are on the bus when your phone buzzes: ''Bob: static tonight at 8?''. You answer ''yes'' from the phone. At 8 you log in, and the reply is in the game window''s history like any other.', 'lantern-core is plain Rust with no game dependency, and lantern-cli already runs it headless. A mobile shell (iroh runs on Android and iOS) would reuse lantern-core, pair as another device through the nostr device list (lantern-every-device), and use the nostr mailbox for wake-ups instead of a push server. Start with the CLI on a Linux phone or Termux as the proof.', 'Mobile OSes kill background sockets, so presence and delivery need the mailbox or a push service, which reintroduces a server. App store distribution is its own project. Keys on a phone widen where the identity can be stolen from.', 'everyone with a phone, statics that organise during the day', 0, 1, 0, 8, 'research', 'weeks', 15, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-safety-words', 'xivlantern', 'The Lamplighter''s Keys', 'Check It Is Really Them', 'Four short words derived from both of your node ids that you can read to each other in game or in voice to confirm the friend is who they say.', 'A ''Bob'' redeemed your invite, but you sent it in a busy Discord. You open his entry: ''lamp moss harbour quill''. You /tell Bob in game to read his; they match, and you tick verified.', 'A pure function in XivLantern.Core over the two 32-byte node ids (sorted, hashed, mapped to a fixed wordlist), host-tested for symmetry. MainWindow''s friend context menu shows it; a local Verified flag in Configuration adds a mark in DrawList. Display names are self-asserted (DESIGN.md), and friendship is keyed on the QUIC-authenticated NodeId, so this checks the thing that is actually authenticated.', 'Only as good as the out-of-band check; people will tick it without comparing. A friend who reinstalls gets a new NodeId and must be verified again, which is correct but will surprise them.', 'anyone who shares invites in semi-public places', 0, 1, 1, 5, 'ready', 'hours', 16, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-key-passphrase', 'xivlantern', 'The Lamplighter''s Keys', 'Lock the Lantern', 'Optionally protect the device key (and nostr key) in the node''s database with a passphrase, entered when you turn Lantern on.', 'You share a PC with a flatmate. With a passphrase set, /lantern on asks for it once per session; the SQLite file on its own is useless to anyone who copies it.', 'DESIGN.md''s threat model says the key sits unencrypted like an SSH key with no passphrase. Wrap the identity row and the nostr_secret profile row with a key derived by Argon2id, add an unlock parameter to lt_config (an lt_node_open error code for ''locked''), and a passphrase prompt in MainWindow.DrawWelcome before LanternService.Start. Existing databases migrate on first set.', 'A forgotten passphrase loses the identity for good; there is deliberately no recovery. Auto-start at plugin load (config.Enabled) can no longer be silent. The ABI version must bump.', 'shared PCs, privacy-minded players', 0, 1, 0, 4, 'stretch', 'days', 17, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-move-house', 'xivlantern', 'The Lamplighter''s Keys', 'Moving House', 'Export your identity and friend list to one encrypted file and import it on a new PC, so friends do not have to re-add you.', 'New PC day. You export from the old one, copy the file on a USB stick, import on the new one, and your lantern lights for the same friends under the same node id, as if nothing changed.', 'The store already holds everything: identity, profile, friends, friend_devices, blocked. Add export and import to lantern-core (a passphrase-encrypted SQLite backup plus a schema version check), expose them in lantern-ffi, and put two buttons in MainWindow.DrawSettings. Saved channel tickets live in the Dalamud Configuration and would be included from the C# side.', 'Running two copies of the same NodeId at once confuses friends'' links and presence; import should refuse while another node with that id is online, which is hard to know. The export file is a full identity and must be treated like a private key.', 'anyone who reinstalls or upgrades', 0, 1, 0, 5, 'stretch', 'days', 18, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('lantern-signed-release-notes', 'xivlantern', 'The Lamplighter''s Keys', 'News From the Lamplighter', 'Each release posts its changelog entry to the author channel as a signed announcement, so players who opted in hear about fixes in game.', 'You log in and the Announcements pane has a new verified line: ''Test build 0.2: channel invites fixed; please run /lantern selftest and send what it prints.'' A button beside it opens Write to the author.', 'tools/release.sh and tools/changelog.py already produce the player-facing entry from changelog.json. Add a step that signs it offline with the lantern CLI''s author sign command (crates/lantern-cli/src/author.rs, which prints an ltannounce line with a growing --seq) and hands that line to the author node''s /announce, per docs/AUTHOR.md. The plugin already verifies and shows announcements (LT_EV_ANNOUNCEMENT, AuthorChat).', 'AuthorIdentity.cs is still empty, so nothing can be verified until the author does the AUTHOR.md setup. Signing must stay on the author''s machine and never move into CI. Too many announcements will get the channel muted.', 'players in the author channel, testers', 0, 1, 0, 4, 'stretch', 'hours', 19, 1, 0)
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Ask Me Before Anything Changes', 'The approval gate, made to arrive at the right moment and to say exactly what a change will do.', 0, 'xivmcp') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Agents on the Duty List', 'Where the agents'' work shows up in Eorzea: under the Duty List, in the toasts, and in a channel only you can read.', 1, 'xivmcp') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Sharlayan Study Hall', 'Read-only planning from the game''s own sheets and your own character, with nothing clicked for you.', 2, 'xivmcp') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Linkpearls Between Mods', 'How XivMcp reaches past the running game: the title screen, the sibling mods and other plugins.', 3, 'xivmcp') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-pull-safe-approvals', 'xivmcp', 'Ask Me Before Anything Changes', 'Approvals That Wait for the Pull to End', 'An agent''s gated call that arrives mid-fight becomes a ticket instead of a prompt, and the prompt appears once you are out of combat.', 'You are in the middle of a trash pull when Claude Code decides your macro needs rewriting. Nothing pops up over your hotbars. When the last mob drops, a quiet toast says ''Claude Code is waiting: write macro 12'' and the Approvals tab carries a (1).', 'ConfirmationService.ApproveToolCallAsync reads ICondition first: while InCombat (or BoundByDuty with the duty started, the flags get_conditions and get_duty_state already read) it does not open ConfirmWindow but files the call through the same path request_action uses into ApprovalQueue/TicketStore, and the tools/call answers with the ticket id so the client can follow the resume contract in APPROVALS.md. ApprovalWiring''s 1 Hz tick raises the toast when the condition clears. A setting under Advanced in MainWindow.Settings.cs turns it off.', 'Clients that do not implement the ticket resume contract see a call that never completes, so the answer must say plainly what happened. The 20-second prompt timeout and the call timeout both need rethinking for this path. Condition flags are among the ClientStructs members not yet observed in game. With approval switched off it changes nothing, which is correct but should be said in the setting''s text.', 'anyone who plays with an agent connected, raiders and roulette runners especially', 1, 1, 1, 7, 'ready', 'days', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-approval-diff-preview', 'xivmcp', 'Ask Me Before Anything Changes', 'Show Me the Before and After', 'The approval prompt for write_macro, equip_gearset and set_plugin_enabled shows what is there now next to what will be there, not only a sentence.', 'Codex asks to rewrite macro 7. The prompt shows your old six lines on the left, its new ones on the right, with the changed lines tinted. For a gear set you see each slot''s item level before and after, and one red row where the new set drops your ring.', 'Tools that already carry an approval sentence gain an optional preview callback: MacroWriteProvider reads the slot through MacroMemory, GearsetProvider reads the target set and get_equipment''s current slots. The preview is rendered by ConfirmWindow and the Approvals tab (MainWindow.Approvals.cs) as a two-column table. It also lets McpServer.RenderApprovalSummary stop truncating write_macro at 500 characters, the open point in TODO.md. ToolContractTests gains a check that a preview never replaces the sentence.', 'The preview is taken when the prompt opens; the macro could change before approval, so the write must compare against the preview and fail if it moved. Reading macro and gear set memory needs the framework thread before the window draws. A long diff makes the prompt tall.', 'cautious players, macro hoarders, anyone letting an agent tidy their setup', 1, 1, 1, 6, 'ready', 'days', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-session-receipt', 'xivmcp', 'Ask Me Before Anything Changes', 'The Receipt at Session''s End', 'When an agent disconnects, a quest-complete toast and a one-page receipt of everything it read, changed, was denied and failed at.', 'You come back from making tea. Almanac''s session has closed and the quest-complete fanfare plays: ''Almanac finished: 41 reads, 2 changes, 1 denied''. Opening the receipt shows the teleport it asked for, the macro it wrote, and the chat line you refused.', 'Sessions.cs already knows when a session''s lifetime ends (IsClosed, StreamClosed). ServerHost counts ActivityRecorded per session; on close it builds a summary from those counts and the matching ActionLog entries, shows it with IToastGui.ShowQuest as ObjectiveTracker does, and keeps the last twenty receipts in the Activity tab (MainWindow.Activity.cs). With approval off the receipt lists every change, since those ran without a prompt.', 'Streamable HTTP sessions often end by expiry rather than a clean close, so some receipts arrive minutes late. Clients that open a new session per call would produce a toast storm; receipts need a minimum size and a mute. Tool arguments in the receipt may hold chat text, so it stays local.', 'players who leave agents running, owners who run with approval off', 1, 1, 0, 5, 'ready', 'days', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-per-client-read-scopes', 'xivmcp', 'Ask Me Before Anything Changes', 'Keys That Open Only Some Doors', 'Each per-client token carries its own list of categories, so the benchmark client can read game data but never your chat or your bags.', 'In Settings you issue a token for a friend''s model experiment and untick chat, inventory and party. Their client lists sixty tools instead of a hundred and fifty, and a call to read_chat answers that the tool does not exist for this key.', 'ClientTokenEntry (AutoApprovePolicy.cs) gains an optional category allow-list, edited in MainWindow.Policy.cs and settable through XivMcp.ConnectClient. The request scope already knows which token authenticated; tools/list, resources/list and dispatch filter by it after HostState''s global tiers and categories, so a scope can only narrow. Changing a token''s scope sends list_changed to that client''s sessions only.', 'Core/Abstractions and McpServer''s public surface are frozen, so this must be an additive hook. Clients without a per-client token share the global view, which the UI must make obvious. Resources and templates cut across categories (ffxiv://chat/recent) and need their own mapping. It is a boundary between clients, not a sandbox for a hostile one.', 'players who connect more than one client, tailnet users, anyone testing a new model', 0, 1, 0, 5, 'stretch', 'days', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-ask-the-player', 'xivmcp', 'Ask Me Before Anything Changes', 'An Agent May Ask You One Question', 'A Ui tool that puts a short multiple-choice question on your screen and hands the answer back, so an agent stops guessing which gear set or which retainer you meant.', 'Planning your crafting run, the agent is unsure. A small window in the game''s style asks: ''Sell the extra Darksteel Ore, or keep it for the Grade 4 materia recipe?'' with two buttons and ''Not now''. You click Keep and the plan updates in your terminal.', 'A new ask_player tool (Ui tier, marked RequiresApproval=false as it only displays to the owner, listed in ToolContractTests'' display-only set) takes a question and two to five choices, returns a question id at once and exposes ffxiv://questions/{id} with notifications/resources/updated on the answer, the same shape as tickets. The window reuses ConfirmWindow''s layout and the pull-safe hold for combat. MCP''s own elicitation/create is a later option once clients render it; McpServer.Dispatch has no handler for it today.', 'A chatty agent could ask twenty questions an hour; it needs a per-client cap and a ''stop asking'' button. Answers are free text to the model, so choices must stay short labels, never a way to route the player into a gated action without its own prompt. Clients that do not subscribe to resources must poll.', 'players using agents for planning, Almanac users', 1, 1, 0, 7, 'stretch', 'days', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-agent-board-duty-list', 'xivmcp', 'Agents on the Duty List', 'Agent Progress as Tracked Quests', 'The agent board''s running entries appear under the Duty List next to custom objectives, with a progress line and a quest toast when one finishes.', 'Below ''The Porcelain Prisoner'' in your Duty List sits ''Claude Code: refactoring loader, 3/7, 42 %''. You finish a FATE; the line turns to ''Done'' and the quest-complete chime plays. A failed one turns red and stays until you hover and dismiss it.', 'ObjectiveOverlay already draws native-styled rows under DutyListAnchor. A second section reads AgentBoard (subscribing to its change event as the IPC Changed gate does) and draws each running post as title plus status line, with the Progress value as a thin bar in the Duty List''s colours. Done and Failed transitions call IToastGui.ShowQuest as ObjectiveTracker does. A Settings toggle beside ''Custom objectives'' chooses board, objectives or both.', 'The overlay itself has never been seen in game (OBJECTIVES.md checklist), so this inherits every placement question. Five busy agents crowd the Duty List; it needs a cap and collapse. Agent names and status text are client-supplied and must be length-capped and cleaned before drawing.', 'developers running agents while they play, Ghostty and Almanac users', 1, 1, 1, 8, 'ready', 'days', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-tickets-in-duty-list', 'xivmcp', 'Agents on the Duty List', 'Pending Approvals Where You Already Look', 'Open approval tickets show as a single tracked line under the Duty List, so a request filed while you were away is noticed without opening the plugin window.', 'You log back in after dinner. Under your quests: ''2 requests waiting: teleport to Kugane (Codex), write macro 3 (Claude Code)''. Clicking it opens the Approvals tab on the first one; nothing is approved from the overlay itself.', 'APPROVALS.md names the hook: ApprovalQueue.Changed and Snapshot(). ObjectiveOverlay reads the pending count and the first two summaries (the existing approval sentences) and draws one entry; its click calls the same toggle as the XivMcp.ToggleWindow IPC gate with the Approvals tab selected.', 'Approving from a Duty List row would be one mis-click from an unintended teleport, so the row only opens the tab, and that has to stay true. Ticket reasons are client text and are shown only in the tab, not the overlay. Same unverified overlay placement as objectives.', 'players who file tickets from agents while away, anyone using the ticket queue', 1, 1, 0, 6, 'ready', 'hours', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-agent-linkshell', 'xivmcp', 'Agents on the Duty List', 'A Linkshell for Your Agents', 'A private in-game channel where agents post short messages in their own colour and you reply with a slash command, delivered to them as a resource update.', 'Your chat log shows ''[MCP:claude] Tests pass. Want me to open the PR?'' in pale gold. You type ''/xivmcp say claude yes, draft only'' without leaving the game, and a minute later the reply comes back that the draft is up. Nobody else sees a word of it.', 'print_echo already writes [MCP]-tagged lines to the player''s own log only. Give each client a stable colour and prefix, and add `/xivmcp say <agent> <text>` in the command handler Plugin.cs registers; messages go to a bounded per-client inbox exposed as ffxiv://inbox with notifications/resources/updated through NotifierProxy, plus a read_inbox tool. The EventStream gains a ''message'' kind so get_events clients see it too.', 'Echo lines are the player''s own log, but they still sit in chat logs that other plugins read and export, so secrets posted by an agent end up there. Clients must subscribe to resources for replies to feel live. A /say typo such as ''/say claude'' would post in public Say chat, so the command name must be hard to confuse.', 'developers who play between agent turns, Ghostty users away from their terminal', 1, 1, 1, 8, 'stretch', 'days', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-objective-here', 'xivmcp', 'Agents on the Duty List', 'Pin This Spot as an Objective', '`/xivmcp quests here "Title"` records your zone, map coordinates, the current bell and weather as a new objective, and `export` writes the lot as a pack to share.', 'You find the perfect screenshot spot above Costa del Sol at dusk in clear skies. One command and it is on your Duty List with the flag, the window ''ET 18:00-20:00, Clear Skies'' and a 30-yalm radius. Exported, it loads straight into a friend''s game.', 'ObjectiveCommands.cs gains ''here'' and ''export'' next to its ten verbs. ''here'' reads the territory and player position as get_location does, converts to map x/y with the same maths as CoordinateProvider and set_map_flag, reads the live weather from WeatherManager and the Eorzea bell from the clock EorzeaTimeWindow uses, then builds the objective through ObjectiveFactory. ''export'' serialises the store in the ObjectivePack format that load_objective_pack reads.', 'What time window to record is a guess: the current bell alone is too narrow, so it defaults to no time condition and says so. Weather in fixed-weather zones is reported as a problem by the evaluator, which is correct but surprising. Export paths under Wine need the same Z: mapping as load.', 'screenshot takers, gposers, pack authors, friends sharing sightseeing routes', 1, 1, 0, 6, 'ready', 'hours', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-native-duty-list-rows', 'xivmcp', 'Agents on the Duty List', 'Real Rows in the Duty List', 'Replace the overlay with native nodes inside the Duty List itself, so custom objectives and agent posts move, collapse and hide exactly as quests do.', 'Your custom objectives sit in the Duty List under a ''Custom'' header, and when you accept a quest the list reflows with them in it. HUD scale, alignment and the collapse arrow all behave as the game''s own rows do, because they are the game''s own rows.', 'Option (a) in OBJECTIVES.md: node injection into _ToDoList through IAddonLifecycle (PostSetup, PostRequestedUpdate, PostRefresh, PreFinalize), either through KamiToolKit or Dalamud''s native overlay service once goatcorp/Dalamud#2874 is merged. It is a drop-in for ObjectiveOverlay and DutyListAnchor; ObjectiveStore, the evaluator and the tools do not change.', 'AddonToDoList has no slot for plugin rows and rebuilds its ListPanel itself; a node still linked at finalize (zone change, HUD layout change, unload) crashes the game rather than failing softly. KamiToolKit is a large dependency to keep current with patches. None of it can be tested outside the running game.', 'players who want XivMcp to feel like part of the game', 1, 1, 0, 8, 'research', 'weeks', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-sightseeing-log-objectives', 'xivmcp', 'Sharlayan Study Hall', 'Your Unfinished Sightseeing Log, as Objectives', 'A tool that reads which vistas you have not logged and posts each as a custom objective with its spot, emote, Eorzea time and weather window.', 'You ask Almanac what is left in your Stormblood log. Six entries appear under your Duty List, two of them ''Ready now (14 min left)''. Clicking the first flags the vista on the map; the step reads ''Go to the spot, then /lookout''.', 'A static provider reads the Adventure sheet through IGameDataSource (so the standalone host can answer the data half) for the Level location, emote and time columns; a live half checks completion through ClientStructs'' PlayerState adventure flags via ILiveWorld. The result feeds ObjectiveFactory directly, and the time and weather become the objective''s eorzeaTime and weather conditions that ObjectiveEvaluator and find_weather_windows already compute.', 'Which Adventure columns carry the weather requirement must be checked against Lumina and may need a small hand-kept table for some entries. The completion flags are unverified in game like every ClientStructs read here. Posting a whole expansion''s log at once hits the 200-objective cap, so it works a region at a time.', 'completionists, achievement hunters, returning players', 1, 1, 1, 8, 'stretch', 'days', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-weekly-reset-ledger', 'xivmcp', 'Sharlayan Study Hall', 'The Weekly Ledger', 'One live resource that says what the daily and weekly resets have left for you: roulettes, tomestone cap headroom, and the reset times in your local time.', 'Tuesday evening, the agent board shows ''Weekly: 180 tomestones to cap, Expert roulette not done, resets in 3 h''. You finish the roulette, and the line updates when the bonus is spent.', 'A ffxiv://reset resource combines what already exists: get_roulette_status, the tomestone weekly figures from get_currencies and the reset schedule from get_time, with resources/updated on the ''duty'' and ''inventory'' events EventStream already appends. The plan_daily_reset prompt switches to reading it. Optionally it posts itself as a single objective with a note line.', 'Much of what players count as weekly (Wondrous Tails, custom deliveries, Doman enclave) lives in managers whose ClientStructs fields are unverified and may not be loaded until the relevant window has been opened. It must show ''unknown'' rather than ''done'' for those. Reset times shift with daylight saving in the player''s zone.', 'players on a weekly routine, returners who forget what resets when', 1, 1, 0, 6, 'stretch', 'days', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-dresser-armoire-tidy', 'xivmcp', 'Sharlayan Study Hall', 'Dresser and Armoire Tidy', 'A read-only report of glamour items that could move to the Armoire, duplicates across dresser and bags, and sets that could be combined into outfits.', 'Your dresser is full again. The agent answers with three lists: 22 items that belong in the Armoire, 5 you own twice, and 3 sets one piece short of becoming an outfit, with where the missing piece sits (retainer 2). You do the moving yourself.', 'A new tool in the Inventory providers joins the dresser contents GlamourProvider already reads with InventoryReader''s containers and cached retainer inventories, then checks each item against the Cabinet sheet (Armoire-eligible) and the MirageStoreSetItem sheet (outfit sets) through IGameDataSource. It returns lists only; nothing is moved.', 'Dresser and retainer contents are only loaded after the player has opened them this session, so the answer must say which containers were not seen. Outfit rules around dyes and duplicates have edge cases. Pure planning, which is the point, but some will ask it to do the moving; it must not.', 'glamour collectors, anyone whose dresser is always full', 0, 1, 0, 5, 'ready', 'days', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-gear-upgrade-path', 'xivmcp', 'Sharlayan Study Hall', 'Next Three Upgrades', 'For your current job, the three cheapest item-level gains you can reach, what each costs in tomestones, seals or crafted materials, and what you already hold towards it.', 'Fresh to 100 on Dancer, you ask what to do first. The answer: the tomestone earrings (you have 375 of 375), the crafted body (the ingredient tree is two steps from what you own), and the Normal raid bracelet, with the shop NPC flagged on your map.', 'A plan_gear_upgrades tool (GameData, with a live half) takes get_equipment''s slots, searches equippable items above each slot''s level with the same index search_items uses, ranks by item level gain per unit cost from ItemSources (SpecialShop and GilShop rows) and RecipeTree, and compares against get_currencies and find_owned_items. The gear_audit prompt calls it.', 'Real best-in-slot depends on stat tiers and substat weights the game data does not state; this ranks by item level and cost only, and must say so. SpecialShop parsing is the messiest data in the sheets. Raid drops are not in the sheets at all.', 'levelling players, alt-job owners, returning players gearing up', 0, 1, 0, 6, 'stretch', 'days', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-craft-margin-sheet', 'xivmcp', 'Sharlayan Study Hall', 'What Is This Craft Worth', 'Cost to craft from the full recipe tree against recent sale prices on your data centre, with the age of every price shown.', 'You wonder whether the new housing item is worth crafting. The agent lays out the tree: ingredients you own at zero, the rest priced from recent sales, total 38,000 gil against a median sale of 61,000 two hours ago. You go gather the ore yourself.', 'Combine get_recipe_tree (RecipeTree), find_owned_items and get_market_prices (UniversalisClient behind MarketCache) into one tool or prompt: price leaves by median recent sale, mark owned quantities as free, and report the age of each price. The crafting_plan prompt gains a ''with prices'' variant.', 'Universalis data is crowd-sourced and can be hours stale; a thin market gives misleading medians. A deep tree asks for many items and must batch within the 20-item call and be polite with the cache. It stays on reading public prices and never touches the market board UI, per HARD-LINES.md; alerts on single listings are deliberately left out.', 'crafters, gil-makers who do their own crafting, FC workshop planners', 0, 1, 0, 6, 'stretch', 'days', 14, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-standalone-last-known', 'xivmcp', 'Linkpearls Between Mods', 'Last Known State Before Login', 'The pre-game standalone host answers character questions from a snapshot the plugin saved at logout, clearly labelled with its age.', 'At work, over the tailnet, you ask what is in your saddlebag. Instead of ''game not running'' the answer comes back with ''as of yesterday 23:14, when you logged out''. Log in and the plugin takes the port and answers live again.', 'On the ''session'' logout event the plugin writes a snapshot of a small allow-listed set of read tools (get_player, get_inventory, get_currencies, get_job_levels, list_gearsets) to a file next to objectives.json. LiveToolStubs in the standalone host serves those tools from the snapshot with an asOf field instead of game_not_running, and everything else keeps its stub. HandoffCoordinator is unchanged.', 'It puts inventory and character data in a file on disk that a tailnet client can reach, so it is off by default and never includes chat or party. Stale answers presented as live would mislead agents; asOf must be in every result and in the description. The standalone host has only been run between native processes.', 'players who plan away from the PC, tailnet users, standalone host users', 0, 1, 0, 6, 'stretch', 'days', 15, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-plugin-tool-gate', 'xivmcp', 'Linkpearls Between Mods', 'Other Plugins Can Offer Tools', 'An IPC gate through which any Dalamud plugin registers its own read tools with XivMcp, under the same catalogue, rate limit and approval gate.', 'Your favourite housing plugin adds three read tools in its next update. In XivMcp''s Tools tab they appear under ''from HousingPlugin'', and your agent can ask it for the saved layout of your apartment.', 'Core already describes tools by data through ExternalTool (McpServer.Extensions.cs), which the standalone host uses. A new IpcContract gate lets a plugin register ExternalTool descriptions whose handler calls back into that plugin''s own IPC. They sit under a per-plugin category the player enables in Settings, and anything not Read goes through ConfirmationService like every other gated tool.', 'XivMcp cannot see what another plugin''s handler does, so HARD-LINES.md cannot be enforced on it; the first version should allow Read tier only, and say so. ToolContractTests cannot check runtime tools. A plugin that unloads leaves dead tools until list_changed. IpcContract is a frozen, additive-only contract.', 'Dalamud plugin authors, players who run several plugins with agents', 0, 1, 0, 7, 'stretch', 'weeks', 16, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-client-budget-meter', 'xivmcp', 'Linkpearls Between Mods', 'Per-Client Call Meter', 'The Status tab shows each connected client''s calls per minute against the rate limit, and the long-missing rate-limit control lands under Advanced.', 'The game hitches and you open XivMcp. One bar is nearly full: a script polling get_events four times a second. You lower the limit from 600 to 120 and watch it settle.', 'TODO.md lists it: RateLimitPerMinute exists with no UI; add the input under Advanced in MainWindow.Settings.cs. The per-client bucket McpServer already keeps for RateLimitPerMinute and RateLimitBurst exposes its current fill, read by MainWindow.Status.cs as one bar per client, and get_server_info gains the same numbers.', 'Client names are self-reported unless a per-client token is used, so two clients can share a bar. Reading the buckets from the draw loop must not take the same lock the dispatch path holds.', 'players running several clients, anyone debugging a greedy agent', 0, 1, 0, 4, 'ready', 'hours', 17, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('mcp-house-aware-terminal-layouts', 'xivmcp', 'Linkpearls Between Mods', 'Terminal Layouts That Remember the House', 'Saved Ghostty layouts tied to a housing plot and room, so apply_terminal_layout puts your panels back on the same wall every time you walk in.', 'You enter your apartment and ask the agent to set up for work. Three terminals appear exactly where you left them last night, one over the desk and two beside the window. Walk out and they fold back to pets.', 'get_terminal_layouts and apply_terminal_layout already exist and answer ''unavailable'', because TODO.md notes that ''/term pin'' has no absolute world-position form. This needs that form in GhosttyDalamud first, then layouts keyed by get_housing_info''s ward, plot and room, written through the layout.get/layout.set verbs that SiblingIpcProposals.cs leaves out today.', 'The blocking work is in another mod and has to be designed there. Housing interiors share coordinates across plots, so the key must include the house identity. The sibling IPC patches have not been applied or built. Panels have no depth test and show through walls.', 'Ghostty users who work from their house, FC workshop builders', 1, 1, 0, 7, 'research', 'weeks', 18, 1, 0)
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Orchestrion''s Moods', 'Music that knows where you are and what is happening: zones, duties, dialogue and the end of a song.', 0, 'xivpiano') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Songs for the Linkshell', 'Telling friends what is playing and listening together, each on their own Pandora account.', 1, 'xivpiano') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Tending Your Stations', 'The station editing Pandora offers, from the game: seeds, genres, shuffle, modes and filters.', 2, 'xivpiano') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Bard''s Comforts', 'Small things for long evenings: what just played, keys and other plugins to control it, and scrobbling.', 3, 'xivpiano') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-duty-stations', 'xivpiano', 'The Orchestrion''s Moods', 'A Station for Every Place', 'Tie a station to a zone, a kind of duty or your home, so the radio changes with where you are and goes back when you leave.', 'You set your chill station for your house and a loud one for high-end duties. The queue pops, you zone into the savage fight, and the heavy station starts on the loading screen. When the duty ends and you are back in Limsa, your usual station picks up again.', 'Configuration gains a list of rules (territory id, or a content type from the ContentFinderCondition sheet, or ''housing'') to a station Id, like LastStationId. Plugin subscribes to IClientState.TerritoryChanged and IDutyState.DutyStarted, finds the first matching rule, and calls Radio.PlayStationAsync through Plugin.Run with the matching entry of Radio.Stations. The station before the rule is remembered and restored when no rule matches. MainWindow gets a ''Stations for places'' section with a ''this zone'' button that fills in IClientState.TerritoryType. Zone names come from the TerritoryType sheet through IDataManager.', 'Switching stations throws away the current song and fetches a fresh playlist, so rapid zoning (a housing ward tour) would burn through songs; switches need a short settle time. A rule pointing at a station you deleted must fail quietly. Pandora limits how many songs you may skip an hour on some accounts, and changing station is not a skip, but it should be checked.', 'players who keep the radio on all evening', 1, 1, 1, 8, 'ready', 'days', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-boss-themes', 'xivpiano', 'The Orchestrion''s Moods', 'Let the Boss Theme Play', 'Pick duties where the game''s own music matters, and XivPiano steps aside there: the radio pauses and the game''s music comes back.', 'You love the radio for levelling, but not over a trial''s theme. You tick ''the game''s music in trials and raids''. The instance loads, the song fades out, the boss theme swells, and when you leave the duty your station carries on from where it paused.', 'In Plugin.OnUpdate, beside the cutscene pause, a ''step aside'' check: ICondition BoundByDuty plus the duty''s ContentType (from IDutyState and the ContentFinderCondition sheet) against a set in Configuration. It pauses with Radio.TogglePause like pausedForCutscene does, with its own flag. The music muting needs no change: OnUpdate already puts IsSndBgm back as it was whenever the radio stops playing.', 'A paused song''s audio link can expire during a long raid, so resuming may skip to a fresh song; Radio already does that quietly. Two reasons to pause (a cutscene inside a duty) must not resume each other too early, so the flags need to be kept apart and tested.', 'everyone who has a favourite boss theme', 1, 1, 1, 7, 'ready', 'hours', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-duck-dialogue', 'xivpiano', 'The Orchestrion''s Moods', 'Quieter While Someone Speaks', 'Lower the radio while a dialogue box is open, and bring it back up when the talking is over, instead of only pausing for full cutscenes.', 'An NPC stops you in the street with a voiced line. The song dips to a murmur so you can hear her, and rises back to its volume a moment after you close the box.', 'An IAddonLifecycle listener on the Talk addon (PostSetup and PreFinalize) sets a ''ducked'' flag in Plugin. AudioOut.Volume is ramped over about 300 ms toward Config.Volume times a duck factor (Configuration.DuckTo, default 25%) from Plugin.OnUpdate, and back when the flag clears. AudioOut already applies Volume per sample in MpegSampleProvider.Read, so the ramp is a few lines.', 'The plugin cannot tell a voiced line from a silent one, so it ducks for every dialogue box; that has to be a setting. The ramp must never fight the volume slider in MainWindow. Talk is not the only dialogue addon (battle talk, some quest windows), so the first version will miss some.', 'story players, anyone doing MSQ with the radio on', 1, 1, 0, 6, 'ready', 'hours', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-crossfade', 'xivpiano', 'The Orchestrion''s Moods', 'Crossfade Between Songs', 'Fade the end of one song into the start of the next, so the radio flows like a mix instead of stopping and starting.', 'The last chorus of a song fades under the first bars of the next. There is no gap of silence while the next song downloads, even on a slow evening connection.', 'AudioOut today holds one WaveOutEvent and one MpegSampleProvider. It would build one output over a MixingSampleProvider fed by two MpegSampleProviders, with a PrepareAsync(Track) that downloads the next song while the current one plays (Radio.AdvanceAsync already keeps one song in hand in its queue). A fade of a few seconds starts when Position reaches Duration minus the fade length, and the Ended event moves to the fade start so Radio advances then. Crossfade length and ''off'' go in Configuration.', 'Two songs in memory at once, a few MB each, which is fine. Thumbs and ''why this song?'' act on Radio.Current, so the switch-over moment must be clear or a thumb could land on the wrong song. Replay gain differs per song; each keeps its own gain factor. Songs with long silent endings make the fade point a guess.', 'everyone, especially on long play sessions', 0, 1, 0, 5, 'stretch', 'days', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-share-song', 'xivpiano', 'Songs for the Linkshell', 'Share What''s Playing', 'One button copies a line about the song, with its Pandora link, ready to paste into party, FC or linkshell chat.', 'Your static asks what this song is on voice. You press Share, type /fc, paste, and your FC reads ''♪ Title by Artist, on Pandora'' with the link, while the song carries on.', 'A Share button in MainWindow.DrawControls builds the line from Radio.Current (Title, Artist, Album and DetailUrl, Pandora''s page for the song, which Track already carries) and puts it on the clipboard with ImGui.SetClipboardText. A matching ''/piano share'' copies it too. Nothing is sent by the plugin: the player pastes it into whichever channel they choose.', 'Automatically posting to party or FC chat would be a plugin sending chat for you, which Square Enix''s terms and Dalamud''s rules frown on, so this only fills the clipboard. Some players will find the extra paste a nuisance, and that is the price. DetailUrl can be empty; the line must read well without it.', 'FCs, statics, friends who swap music', 0, 1, 1, 6, 'ready', 'hours', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-lantern-status', 'xivpiano', 'Songs for the Linkshell', 'Now Playing on Your Lantern', 'With XivLantern installed, your friends can see what you are listening to next to your lit lantern, if you say so.', 'You open XivLantern and your friend''s line reads ''Listening to Clair de Lune on Classical Piano''. You like it, so you start the same kind of station yourself.', 'XivPiano already offers XivPiano.NowPlaying over IPC. XivLantern would gain an opt-in to read it and add ''listening to'' to the presence note it already shares with friends; nothing in XivPiano changes except a new XivPiano.SongChanged message gate (see piano-song-events) so XivLantern does not have to poll. Off by default in both plugins.', 'It needs work in XivLantern, which only has XivLantern.v1.GetStatus today, and XivLantern''s promise is that nothing from the game is sent; a song title is not from the game, but it is still something about you going to others, so it must be plainly opt-in. Song titles can be long and need cutting.', 'XivLantern users and their friends', 0, 1, 0, 6, 'stretch', 'days', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-listen-together', 'xivpiano', 'Songs for the Linkshell', 'Listen Together', 'A party or linkshell tunes in to the same station''s seeds together, each person on their own Pandora account, with play and pause kept in step.', 'Your FC''s Friday night: the host starts ''Listen together'' on a synthwave station and shares a short code. Each friend pastes it and a station built from the same artists starts for them. When the host pauses for a mechanic explanation, everyone''s radio pauses too.', 'The code carries the station''s seeds (from station.getStation with includeExtendedAttributes, as pianobar asks for them) as music tokens. Each listener''s XivPiano makes a station with station.createStation from the first and adds the rest with station.addMusic, then plays it. Play and pause travel as small messages over XivLantern''s channels when it is installed, or not at all. Nothing but the code and play/pause state is shared.', 'Every listener hears different songs, because Pandora makes a playlist per listener and XivPiano will never pass audio from one player to another (that would be rebroadcasting, which Pandora''s terms forbid). So ''together'' means the same kind of music, not the same song, and the page must say that honestly. Everyone needs a US Pandora account. It adds a station to each listener''s list, which they may not want to keep.', 'FCs, roleplay venues, friend groups', 0, 1, 0, 8, 'research', 'weeks', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-station-seeds', 'xivpiano', 'Tending Your Stations', 'Add Variety to a Station', 'See what a station is built from, add an artist or song to it, and take back a thumb you regret, without leaving the game.', 'Your ''Final Fantasy Soundtracks'' station has gone stale. You open its seeds, search for a composer and add them. The next few songs bring in pieces you have not heard, and you remove a thumbs-down you gave by mistake last week.', 'PandoraClient gains GetStationAsync (station.getStation with includeExtendedAttributes, returning seeds and feedback), AddMusicAsync (station.addMusic with a musicToken from SearchAsync), DeleteMusicAsync (station.deleteMusic with the seedId) and DeleteFeedbackAsync (station.deleteFeedback with the feedbackId), the calls pianobar makes in src/libpiano/request.c. MainWindow gets a ''Station details'' popup reusing the search box from DrawNewStation. Host tests go into PandoraTests against the fake Pandora.', 'More Pandora calls means more of an unofficial API to keep working. A station must keep at least one seed, and Pandora''s answer to removing the last must read clearly. Shared stations cannot be edited until they are made your own (piano-adopt-shared).', 'listeners who shape their stations', 0, 1, 1, 7, 'ready', 'days', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-genre-stations', 'xivpiano', 'Tending Your Stations', 'Browse Pandora''s Genre Stations', 'A list of Pandora''s own genre stations by category, to start one with a click when you do not know what you want.', 'You open ''Genres'', pick Ambient, then ''Video Game Music'', and a station starts playing without you having to think of an artist.', 'PandoraClient.GetGenreStationsAsync calls station.getGenreStations and returns categories of (name, stationToken). A ''Genres'' tab in MainWindow lists them; picking one runs Radio.CreateAndPlayAsync with PandoraClient.CreateStationAsync on that genre station''s token, the way pianobar makes a station from a genre. The list is cached for the session.', 'Pandora has changed its genre catalogue over the years and this call may return fewer genres than the web app shows. Each pick adds a station to the list, and Pandora caps how many stations you may have (PandoraException.StationLimit already explains it).', 'new Pandora users, anyone out of ideas', 0, 1, 0, 5, 'ready', 'hours', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-quickmix', 'xivpiano', 'Tending Your Stations', 'Choose What Shuffle Mixes', 'Tick which stations Shuffle draws from, the way Pandora''s QuickMix lets you.', 'Your Shuffle keeps playing a kids'' station someone set up years ago. You untick it in XivPiano''s list and Shuffle plays only your own music from then on.', 'Station already knows IsQuickMix. PandoraClient.GetStationsAsync would also read quickMixStationIds from the QuickMix station in the user.getStationList answer, and a new SetQuickMixAsync sends user.setQuickMix with the chosen quickMixStationIds, as pianobar does. MainWindow.DrawStations shows a checkbox per station when ''Edit Shuffle'' is on.', 'Changes apply to the account everywhere, including the Pandora app, which is the point but should be said. The field is not present for every account type, so the checkboxes must hide when it is missing.', 'anyone with many stations', 0, 1, 0, 4, 'ready', 'hours', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-station-modes', 'xivpiano', 'Tending Your Stations', 'Station Modes', 'Pick a station''s mode (My Station, Crowd Faves, Deep Cuts, Discovery, Newly Released, Artist Only) where Pandora offers them to your account.', 'Your favourite band''s station has played the same five hits all week. You switch it to Deep Cuts and the next songs are album tracks you had forgotten about.', 'pianobar asks for modes with interactiveradio.v1.getAvailableModesSimple (stationId) and sets one with interactiveradio.v1.setAndGetAvailableModes (stationId, modeId), through the same JSON API and Blowfish wrapping PandoraClient.CallAsync already does. A mode picker beside the station name in MainWindow.DrawNowPlaying; a mode change clears Radio''s queue so the next song follows it.', 'These calls are newer than the rest and less documented; whether they answer for the Android and Pandora One partners XivPiano signs in as, and for free accounts, has to be found out first. Pandora offers different modes per station, so the picker must list only what the answer says.', 'Plus and Premium listeners, long-time Pandora users', 0, 1, 1, 7, 'stretch', 'days', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-explicit-filter', 'xivpiano', 'Tending Your Stations', 'Explicit Content Filter', 'Turn Pandora''s explicit content filter on or off from XivPiano''s settings, for streaming or a shared room.', 'You stream your gameplay on Saturday. You tick ''Filter explicit songs'' in XivPiano and Pandora stops sending explicit tracks until you untick it.', 'PandoraClient gains GetSettingsAsync (user.getSettings, reading isExplicitContentFilterEnabled) and ChangeSettingsAsync (user.changeSettings with isExplicitContentFilterEnabled), as pianobar''s settings menu does; changeSettings wants the current username and password, which PandoraClient keeps for the session in its credentials field. A checkbox in MainWindow.DrawSettings, read after sign-in. Queued songs are dropped after a change so the filter applies from the next song.', 'It is an account setting, so it changes the Pandora app and website too. If the password was not kept, a change needs it typed again. Songs already fetched still play until the queue is refilled.', 'streamers, players with family nearby', 0, 1, 0, 4, 'ready', 'hours', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-adopt-shared', 'xivpiano', 'Tending Your Stations', 'Make a Shared Station Your Own', 'Turn a station someone shared with you into your own copy, so your thumbs teach it and you can edit its seeds.', 'A friend shared their ''Gridanian Folk'' station and you added it on Pandora''s site. In XivPiano it is marked as shared; you press ''Make it mine'' and from then on your thumbs up count.', 'Station already carries IsShared from user.getStationList. PandoraClient.TransformSharedStationAsync calls station.transformSharedStation with the stationToken, as pianobar does, and Radio replaces the station in Radio.Stations with the answer. MainWindow shows a small ''shared'' tag and the button.', 'Few people use shared stations any more, so it is small value. The transformed station gets a new token, so LastStationId and any piano-duty-stations rules pointing at the old one need updating.', 'players who swap stations with friends', 0, 1, 0, 3, 'ready', 'hours', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-history-window', 'xivpiano', 'The Bard''s Comforts', 'What Was That Song?', 'A list of the last twenty songs, with thumbs, bookmark and ''why this song?'' still working on them after they have finished.', 'A song played during a pull and you were too busy to look. After the wipe you open History, find it second from the top, thumb it up and bookmark it.', 'Radio already keeps the last Radio.HistoryLength (20) finished tracks in Radio.History. A History tab in MainWindow lists them with the same icon buttons as DrawControls; thumbs call PandoraClient.AddFeedbackAsync with the old track''s StationId and Token (pianobar rates songs from its history the same way), and bookmarks and ExplainAsync take the Token as they do now. Album art reuses LoadArtAsync.', 'A thumb on an old song must go to the station it played on, which may not be the current one; Track.StationId has it, but the station token must be looked up. Pandora may refuse feedback on a very old track token, and the error has to read plainly. History is lost when the game closes unless it is saved.', 'everyone', 0, 1, 1, 7, 'ready', 'hours', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-song-events', 'xivpiano', 'The Bard''s Comforts', 'Other Plugins Hear the Song Change', 'Tell other plugins the moment the song changes, so XivMcp, Ghostty or a Stream Deck setup can react without asking every second.', 'You ask Almanac through XivMcp ''what was that song?'' and it answers from the event it heard. Your Stream Deck''s ''next'' button runs a macro with /piano next and its label updates with the new title.', 'A message gate XivPiano.SongChanged next to the existing XivPiano.NowPlaying and XivPiano.Control, sent with ICallGateProvider.SendMessage from Plugin.OnUpdate where announcedToken already notices a new track, carrying the same JSON NowPlayingJson builds. XivMcp could add read and control tools that call NowPlaying and Control. Stream Deck works today through macros with /piano; the event is for plugins that show state.', 'Subscribers run on the framework thread, so a slow one would stall the game; the docs must say to return quickly. The JSON shape becomes a contract to keep. XivMcp''s control tools would need the same in-game approval as its other actions.', 'plugin authors, XivMcp and Stream Deck users', 0, 1, 0, 5, 'ready', 'hours', 14, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-scrobble', 'xivpiano', 'The Bard''s Comforts', 'Scrobble to Last.fm', 'Send what you listen to in game to your Last.fm profile, as Elpis does, if you sign in to Last.fm.', 'Your Last.fm profile has years of listening, and the hours in Eorzea were missing from it. You connect it once in XivPiano''s settings and your raid night''s songs show up under your recent tracks.', 'A small Last.fm client in XivPiano.Core (Elpis has one in Libs/LastFmScrobbler): desktop auth once, then track.updateNowPlaying when Radio.Current changes and track.scrobble when a song has played for half its length or four minutes, measured from AudioOut.Position, queued and retried while offline. The session key is kept with Secrets (DPAPI) like the Pandora password. Needs a Last.fm API key registered for XivPiano.', 'A second network destination, which the privacy note must name, and off by default. Last.fm''s own terms apply to the API key. Skipped and banned songs must not scrobble. Scrobble rules about minimum length (30 seconds) must be kept.', 'Last.fm users', 0, 1, 0, 5, 'stretch', 'days', 15, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-media-keys', 'xivpiano', 'The Bard''s Comforts', 'Media Keys and Hotkeys', 'Play, pause and skip with your keyboard''s media keys, or a key of your choosing, while the game has focus.', 'Mid-dungeon, a song you do not like starts. You press the next-track key on your keyboard and it skips, without opening a window or typing a command.', 'Dalamud''s IKeyState reads keys while the game window has focus; Plugin.OnUpdate would watch the media keys (VK_MEDIA_PLAY_PAUSE, VK_MEDIA_NEXT_TRACK) and any keys set in Configuration, and call Plugin.Control(''toggle'') or Control(''next'') on a fresh press. Elpis does the same outside a game with global hotkeys (Elpis/Hotkeys.cs); here only in-focus keys are planned.', 'Whether Wine passes media keys to the game at all has to be found out, and the desktop''s own media player may take them first. A bound key must not also trigger a game action, and IKeyState cannot stop the game seeing it, so plain keys are risky and chords are safer. Macros with /piano already cover most of this.', 'keyboard players, laptop players', 0, 1, 0, 6, 'research', 'days', 16, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('piano-lyrics', 'xivpiano', 'The Bard''s Comforts', 'Lyrics, Where Licensed', 'Show the words of the song that is playing, if a licensed source that allows it can be found.', 'A song you half know comes on. You open the Lyrics tab and read along while you craft.', 'Pandora''s partner API that pianobar documents has no lyrics call, and Pandora''s own apps show lyrics from a licensed provider through their private web API, which XivPiano does not use. So this would mean a lyrics provider whose terms allow a third-party player to show them, keyed on Track.Title and Track.Artist, shown in a tab in MainWindow.', 'Lyrics are licensed separately from the music. Scraping them from lyrics sites, or lifting Pandora''s own, would break someone''s terms and their licence, which is why this is marked unsafe as it stands. It is listed to see whether people want it enough to look for a proper licence; without one it will not be built.', 'sing-along listeners', 0, 0, 0, 6, 'research', 'weeks', 17, 1, 0)
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Bead''s Moods', 'How the bead and the glove look, sound and move, so a glance tells you more.', 0, 'xivwayfinder') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('More Than the Map Flag', 'New things to point at, all drawn from the game''s own sheets and your own character.', 1, 'xivwayfinder') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Aetheryte to Doorstep', 'Guidance that carries on past the teleport, across zone lines and back again.', 2, 'xivwayfinder') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('The Wayfinder''s Linkpearl', 'Sharing routes with friends and letting sibling plugins hear what the bead is doing.', 3, 'xivwayfinder') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-source-colours', 'xivwayfinder', 'The Bead''s Moods', 'A Colour for Every Source', 'The bead takes a different colour for your own target, the map flag and the quest step, so you always know which one it is following.', 'You set a flag for a hunt mark while a quest is tracked. The bead turns the flag''s red. You clear the flag and it fades to the quest''s blue, and you know without opening the settings that it has moved on to the quest.', 'Configuration gains a colour per TargetSource beside BeadColor (which stays the default for Explicit). Overlay.DrawBead and DrawTrail pick the colour from scene.Guide.Target.Source; a Pulse.Approach blend over about 0.4 s eases the change. SettingsWindow gets three colour pickers and a ''one colour for all'' box. Colors.cs already has Pack and Lighten.', 'Three more colours to explain in a window that is already busy. Red and green as defaults would fail colour-blind players, so the defaults should differ in lightness too.', 'everyone, especially players who keep a flag and a quest going at once', 1, 1, 0, 5, 'ready', 'hours', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-corner-double-tap', 'xivwayfinder', 'The Bead''s Moods', 'The Glove Warns of a Turn', 'With vnavmesh, the glove taps twice and leans into the next leg a few yalms before the path turns a corner.', 'You run down a Limsa stairwell. Three yalms before the landing the glove taps twice and swings to the left, so you take the turn without overshooting and doubling back.', 'Navmesh already exposes Corner and the path''s corners. In Overlay.DrawWalk, when the flat distance to path[Corner] falls under about 3 yalms, blend the glove''s angle towards the next segment and run Pulse.Tap at double rate for one period. PathFollow gains a small pure helper for ''approaching corner'' so it can be host-tested next to MotionAndPathTests.', 'vnavmesh paths in towns have many short corners; the glove could fidget. Needs a minimum turn angle (say 30 degrees) before it warns. Not yet seen in game, like the rest of the path code.', 'players who use vnavmesh paths, city navigators', 1, 1, 0, 5, 'ready', 'hours', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-hot-and-cold-chime', 'xivwayfinder', 'The Bead''s Moods', 'Warmer, Colder', 'An optional soft chime that repeats faster as you face the right way and slows as you turn away, for players who would rather listen than look.', 'You are looking at the market board chat, not the screen centre. A quiet chime ticks slowly, then quicker as you turn, then settles into a steady beat when you are on course. You walk there without once looking for the bead.', 'Heading.TurnAway already gives 0 to 1 for how far off course you face. A new pure Chime class in XivWayfinder.Core maps that and the distance to an interval, host-tested like Pulse. The plugin plays a game UI sound through FFXIVClientStructs'' UIGlobals.PlaySoundEffect on each tick. Settings: off by default, a sound choice from the chat <se.1>-<se.16> set, and a volume note pointing at the game''s own System Sounds slider.', 'The game''s sound effects cannot be pitched, so only the rate can carry meaning. Repeated chimes get tiring fast; it must stop on arrival and in the same situations Visibility.Decide hides the pointer. UIGlobals signatures can move between patches.', 'low-vision players, players who hide most UI, screenshotters', 1, 1, 1, 6, 'stretch', 'days', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-minimap-glove', 'xivwayfinder', 'The Bead''s Moods', 'A Glove on the Compass', 'A small glove clings to the edge of the minimap and points the way there too, for players who navigate by the minimap.', 'You fly over Thavnair with the camera swung wide for the view. On the minimap''s rim a tiny white glove sits at two o''clock, pointing out. It slides round the rim as you turn.', 'Read the _NaviMap addon''s position, scale and rotation through IGameGui.GetAddonByName and its node tree. Place the glove on the ring with a circular version of ScreenEdge.RayToEdge (a new pure helper in Core, host-tested), and draw it with the existing Glove.Quad and GloveTexture, at a smaller size, on the same foreground draw list Overlay uses.', 'The minimap can be locked north-up or to the camera, and its rotation must be read correctly for both. HUD layouts, scaling and minimap replacement plugins move or hide it. Addon node indices change between patches.', 'minimap navigators, players with the camera zoomed right out', 0, 1, 0, 6, 'stretch', 'days', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-bead-behind-walls', 'xivwayfinder', 'The Bead''s Moods', 'A Bead That Knows About Walls', 'Draw the bead in the world itself rather than on top of the screen, so a pillar or a companion can stand in front of it the way real things do.', 'You round a column in the Crystarium and the bead slips out from behind it rather than floating in front of the stone. Its glow picks up the lamplight. It finally looks like part of the place.', 'Overlay draws everything on ImGui''s foreground list, which has no depth. Two routes to try: spawn a client-side VFX at the bead''s world position (the approach Splatoon-style plugins take), or read the game''s depth buffer and test the bead''s projected point against it before drawing. Either way the bead''s position stays computed by Heading.Ahead and Pulse, and the ImGui bead remains the fallback.', 'Both routes need hooks or signatures that break on patches, and a VFX left behind on unload or a crash stays in the scene. Reading the depth buffer is renderer-specific and may not work the same under Wine. May cost more frame time than the whole plugin does today.', 'screenshotters, roleplayers, anyone bothered by overlays', 1, 1, 0, 8, 'research', 'weeks', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-named-places', 'xivwayfinder', 'More Than the Map Flag', 'Places You Keep', 'Save where you stand under a name and point back at it later: /wayfinder save forge, /wayfinder go forge.', 'You find the quiet spot behind the Idyllshire inn where your FC meets. /wayfinder save meetup. A week later, logging in lost in the middle of Idyllshire, /wayfinder go meetup and the bead turns towards it, or names the aetheryte if you are elsewhere.', 'WayfinderCommands.Parse gains save, go, forget and places verbs (they must be matched before the free-text zone words). Configuration stores a list of (name, territory, x, y, z); names compare through ZoneMatch.Fold so accents and case do not matter. ''go'' sets explicitTarget exactly as SetMapTargetFromCommand does, with the name as the label, so arrival, the aetheryte hint and GetState all work unchanged.', 'A name that is also a zone name (''/wayfinder go limsa'') needs a clear rule. Positions inside instanced housing are per ward and plot and would need those stored too, or be refused.', 'roleplayers, gatherers, FC organisers, anyone who forgets where things are', 1, 1, 0, 6, 'ready', 'hours', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-waypoint-queue', 'xivwayfinder', 'More Than the Map Flag', 'A Queue of Stops', 'Line up several targets and walk them in order: each one is dropped as you reach it and the bead turns to the next.', 'You have six vendors to visit for a crafting run. You paste six sets of coordinates, one after another, with /wayfinder add. The bead leads you to the first; on arrival chat says ''stop 1 of 6 reached'' and the glove swings round to point at the second.', 'Plugin.explicitTarget becomes the head of an immutable list swapped atomically (IPC callers are on other threads). The existing ArrivalTimer and ClearOnArrival logic pop the head instead of clearing. New verbs in Commands.cs: add, next, skip, list. A new IPC function XivWayfinder.v1.AddTarget sits beside SetTarget in IpcContract.cs and docs/IPC.md; GetState gains a ''queue'' count, which is additive and keeps version 1.', 'The order is yours, not an optimised route; people will ask for ''shortest order'', which is a travelling-salesman problem across zones. Queue and single-target semantics must stay obvious: does SetTarget replace the whole queue? It should, and the docs must say so.', 'crafters, gatherers, sightseers, event hosts', 1, 1, 1, 7, 'ready', 'days', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-find-npc', 'xivwayfinder', 'More Than the Map Flag', 'Where Is the Mender?', 'Point at an NPC by name, /wayfinder find mender, using where the game''s own data places them.', 'Your gear is at 5% in Old Sharlayan and you have no idea where the mender stands. /wayfinder find mender. The bead turns, the distance reads 38 y, and a moment later you are repairing.', 'Build an index once from the Level sheet rows whose Type is an ENpc, joined to ENpcResident for names and titles (''Mender'' is usually a title). Match with ZoneMatch''s exact, then prefix, then substring ranking over ZoneMatch.Fold. Among placements pick the nearest in your zone first, like QuestPick.Nearest, else fall back to the aetheryte hint. Results become an Explicit Target with the NPC''s name as the label, Y included so vnavmesh gets a proper floor.', 'Many NPCs have several Level rows or appear only during certain quest phases, so the game data can place someone who is not there. Generic titles match dozens of NPCs. Building the index costs a noticeable moment on first use and must happen off the framework thread.', 'returning players, new players, alts in unfamiliar cities', 1, 1, 1, 8, 'stretch', 'days', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-aether-currents', 'xivwayfinder', 'More Than the Map Flag', 'The Next Aether Current', 'Point at the nearest aether current in this zone that you have not yet attuned to.', 'You land in a new zone and walk everywhere anyway. /wayfinder currents: the bead leads you up a ridge to a current you would have missed, then turns to the next one as soon as you have attuned.', 'The AetherCurrentCompFlgSet sheet lists each zone''s currents; field currents are EObj placements found through Level rows. FFXIVClientStructs'' PlayerState reports which currents are unlocked. A new source (or a queue fed into way-waypoint-queue) keeps the nearest unattuned one as the target, re-read at the same 0.25 s scan Plugin.Update already does for the flag and quest.', 'Quest-rewarded currents have no field position and must be named, not pointed at. Plugins that already do this exist; this would need to be clearly nicer, not merely present. The EObj-to-current mapping has to be checked in game.', 'levelling players, completionists, anyone unlocking flight', 1, 1, 1, 7, 'stretch', 'days', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-sightseeing-vistas', 'xivwayfinder', 'More Than the Map Flag', 'Sightseeing Log Guide', 'Point at the next Sightseeing Log vista you have not logged, and say which weather and hours it needs.', 'The note above your head reads ''Vista 14: Clear Skies, 8 a.m. to noon''. It is raining, so you set it aside for later. Next morning the bead is already pointing at the cliff edge.', 'The Adventure sheet has each vista''s Level (place), emote and time window; PlayerState knows which are complete. A new source reads them for the current expansion''s log. The existing DrawNote glass note carries the conditions. Pure selection logic goes in Core with host tests, like QuestPick.', 'Weather conditions come from another sheet and forecasting them is its own project. Needs care to not spoil vistas for players who like finding them unaided, so it only points at the one you ask for.', 'completionists, sightseers, screenshotters', 1, 1, 0, 6, 'stretch', 'days', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-nearest-fate', 'xivwayfinder', 'More Than the Map Flag', 'Towards the FATE', 'Follow the nearest active FATE in the zone, switching as FATEs start and end.', 'You are grinding a relic step in Thanalan. A FATE pops on the far side of the map and the bead swings towards it. You arrive, the fight starts and the bead steps aside; when it ends the bead is already pointing at the next one.', 'Dalamud''s IFateTable gives each active FATE''s position and state. A fourth TargetSource, Fate, sits after Quest in TargetPicker.Pick, with its own toggle in SourceToggles and SettingsWindow. The existing combat rule in Visibility.Decide already hides the pointer while you fight.', 'Adding a source touches the enum, IPC names in WayfinderIpc.Name and the GetState docs. FATE positions are what the map already shows, but a new source is still something to keep tidy. ''Nearest'' flip-flops between two equal FATEs without hysteresis.', 'relic and bicolour gem grinders, levelling players', 1, 1, 0, 6, 'ready', 'days', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-timeworn-map', 'xivwayfinder', 'More Than the Map Flag', 'X Marks the Spot', 'Once you have deciphered a timeworn map, point at the dig site it shows.', 'You decipher a map and the little chart pops up. Instead of squinting at the landmarks, you close it and the note says ''Teleport to Camp Broken Glass''. When you land, the bead leads you straight to the spot.', 'The TreasureSpot and TreasureHuntRank sheets give the candidate Level rows; which one is yours is only known after deciphering. Research whether the client exposes it in an agent (as the treasure-map UI must know it) before considering a hook. The result becomes an Explicit Target, so the aetheryte hint and vnavmesh work unchanged.', 'If the spot is only in a network packet, reading it means a hook, which is fragile and a larger step than anything the plugin does now. Established plugins already fill this niche. Must never extend to anything the player has not deciphered themselves.', 'treasure hunters, map parties', 1, 1, 0, 8, 'research', 'weeks', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-quest-map-links', 'xivwayfinder', 'Aetheryte to Doorstep', 'The Quest Continues Next Door', 'When a quest step lies on another map, point at the exit the game''s own quest link names instead of just saying ''another zone''.', 'Your next step is in Western Thanalan and you are standing in Central Thanalan. Instead of ''Teleport to Horizon'', the glove points down the road to the zone exit, the same way the game''s own map arrow does.', 'docs/WAYFINDER.md lists AgentMap.MapQuestLinkContainer (QuestId, LevelId, source and target map) as ''not used yet''. GameReader.Quest reads it when no marker or to-do Level is in the player''s zone and returns the link''s Level as the target, labelled with the destination. Core gains a pure chooser beside QuestPick.Nearest, host-tested.', 'The container reflects what the map has loaded, the same known gap the event markers have. Links can point at places the player can only reach by ferry or NPC. Needs checking against a real journal, which nothing in the quest reads has had yet.', 'questing players, returning players on long MSQ runs', 1, 1, 1, 7, 'stretch', 'days', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-walk-next-zone', 'xivwayfinder', 'Aetheryte to Doorstep', 'Walk, Don''t Teleport', 'When the target is one or two zones away on foot, point at the zone exit instead of naming an aetheryte.', 'Your flag is in Middle La Noscea, just over the line from where you stand. The note offers a choice: ''Teleport to Summerford Farms'' or the glove pointing at the road east, ''on foot, 1 zone''.', 'Map-to-map links come from MapMarker rows of the map-link type, read the same way GameReader.AetherytesIn already reads aetheryte markers and converted with MapCoords.PixelToWorld. Build a zone graph once and find the shortest walk with a breadth-first search in Core (pure, host-tested). TargetPicker.Plan grows a WalkToExit guide kind; GetState''s ''guide'' field gains a value, documented in IPC.md.', 'Links through ferries, airships and NPC dialogue are not walkable and are hard to tell apart from real exits. One-way drops and locked zones (before a quest opens them) will mislead. Deciding when walking beats teleporting is a judgement call, so the first version should only offer it for adjacent zones.', 'players saving gil, sprouts, roleplayers who like to walk', 1, 1, 0, 6, 'stretch', 'weeks', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-aethernet-last-leg', 'xivwayfinder', 'Aetheryte to Doorstep', 'The Aethernet Leg', 'In the big cities, name the aethernet shard nearest the target as well: ''Teleport to Ul''dah, then aethernet to Sapphire Avenue Exchange''.', 'Your target is the Ul''dah market. The note says ''Teleport to Ul''dah, then aethernet to Sapphire Avenue Exchange''. You arrive by the shard and the bead is waiting, pointing across the plaza.', 'The Aetheryte sheet includes aethernet shards (not IsAetheryte, grouped by AethernetGroup), with MapMarker positions like the main aetherytes. Extend GameReader.AetherytesIn to return shards, and TargetPicker.NearestAetheryte to pick a (main, shard) pair when the shard saves real distance. Also useful in the same zone: ''aethernet to X'' when the walk is long.', 'Shard attunement state needs its own check, and it may not be exposed as simply as IAetheryteList. Cities span several territories (Ul''dah Steps of Nald and Thal), so the shard graph crosses zones. The note gets longer and must stay readable.', 'everyone who gets lost in Ul''dah, city shoppers', 1, 1, 0, 6, 'stretch', 'days', 14, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-flight-paths', 'xivwayfinder', 'Aetheryte to Doorstep', 'Pointing on the Wing', 'When you are mounted and flying, ask vnavmesh for a flight path and let the bead climb and dive with it.', 'You take off in Il Mheg. The bead drifts upwards with you, points over the treeline rather than round it, and dips as you approach the flag so you know when to descend.', 'Navmesh.Request always passes fly = false to vnavmesh.Nav.PathfindCancelable. Pass true when ICondition shows InFlight (and Diving under water), and requery on take-off and landing through PathFollow.ShouldRequery. Heading.Ahead gains a pitched variant so the bead follows the path''s height; the glove stays a ground-plane pointer with an up or down hint.', 'vnavmesh''s flight meshes are less tested than its ground meshes. A flying path to a flag without height has no obvious end altitude. Must stay pointing only: never vnavmesh''s movement gates, in the air as on the ground.', 'flyers, gatherers, hunt trains', 1, 1, 0, 7, 'stretch', 'days', 15, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-breadcrumbs-back', 'xivwayfinder', 'Aetheryte to Doorstep', 'Breadcrumbs Back', 'Remember the way you came and point you back along it: /wayfinder back.', 'You chased a gathering node deep into a Kholusian cave and lost your bearings. /wayfinder back, and a trail of small beads lights up the route you walked in, leading you out the way you came.', 'Plugin.Update records your own position into a fixed ring buffer every couple of yalms (allocation-free, covered by AllocationBudgetTests), cleared on zone change. ''back'' feeds the reversed crumbs to the existing PathFollow.NextCorner as if they were a vnavmesh path, and DrawTrail shows them. Nothing but your own character is recorded, and nothing is saved to disk.', 'Crumbs recorded while flying or swimming do not make a walkable path. Loops and backtracking need simplifying, or the bead leads you round every detour you made. Zone changes break the trail.', 'gatherers, explorers, players who get lost in caves and cities', 1, 1, 0, 6, 'ready', 'days', 16, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-arrival-events', 'xivwayfinder', 'The Wayfinder''s Linkpearl', 'Arrival and Change Events', 'Tell other plugins when a target is reached or changes, so Ghostty, XivMcp or a macro plugin can react without polling GetState.', 'XivMcp set a target for you from a question you asked. When you arrive, it hears the arrival at once and follows up in its own window with the next thing you wanted, instead of checking every second.', 'Two message gates next to the existing four in IpcContract.cs: XivWayfinder.v1.Arrived (label, territory) and XivWayfinder.v1.StateChanged (the same JSON as WayfinderIpc.StateJson), sent with ICallGateProvider.SendMessage from Plugin.Update when the arrival timer fires or the guide kind or target changes. docs/IPC.md documents them, and the existing host test that checks every contract name is in the doc covers them.', 'StateChanged must be debounced or it fires every frame the distance changes. Subscribers run on the framework thread and a slow one could stall it; the docs must say to return quickly.', 'plugin authors, XivMcp and Ghostty users', 0, 1, 0, 4, 'ready', 'hours', 17, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-route-codes', 'xivwayfinder', 'The Wayfinder''s Linkpearl', 'Treasure Hunt Routes', 'Build a route of stops with a riddle at each and share it as a pasteable code, so an FC can run a scavenger hunt with nothing but chat.', 'Your FC''s event host posts a short code in FC chat. You paste it with /wayfinder route. The note shows the first riddle: ''where the bell tolls over sand''. When you reach the right spot a soft ring blooms, the next riddle appears and the bead turns towards the next stop.', 'A route is a small JSON list of (territory, x, z, label, clue, hidden) compressed and base64-encoded with a version prefix; parsing and validation go in Core using WayfinderIpc.Validate and CleanLabel for every stop, so a malicious code can do nothing but point. Builds on way-waypoint-queue. ''Hidden'' stops show no bead until the previous one is reached, only the clue in DrawNote. Recording a route is /wayfinder route add at each spot. No network: the code is passed by hand.', 'Codes get long for many stops and chat limits message length. Hidden stops can be cheated by reading the code, which is fine for fun and should be said plainly. Clues are player-written text, so they need the same cleaning labels get.', 'FC event hosts, roleplay communities, friend groups', 1, 1, 1, 8, 'stretch', 'days', 18, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('way-proving-ground', 'xivwayfinder', 'The Wayfinder''s Linkpearl', 'The Proving Ground', 'A step-by-step window that walks you through the in-game checks in docs/WAYFINDER.md and builds a report to paste into an issue.', 'You install the dev plugin and open /wayfinder prove. Step 1 ticks itself when the test target shows at about 20 yalms. At step 7 you tick ''aims round the wall'' by hand. At the end one button copies a tidy report with your status lines, glove and vnavmesh state and game version.', 'A new window beside SettingsWindow, with the eight steps from ''Proving it in game'' as data. Steps that can be checked automatically read WayfinderState (guide Walk, distance close to 20, source Flag, source Quest, Navmesh true, reason ''cutscene''); the others are manual ticks. The report joins WayfinderIpc.StatusLine, GloveTexture.Status and Navmesh.Status and goes to the clipboard, never the network.', 'An automatic tick proves only what the plugin believes, not what the player saw, so the report must keep the two kinds of evidence apart. The step list must stay in step with the doc.', 'testers, early adopters, the author before a release', 0, 1, 0, 4, 'ready', 'days', 19, 1, 0)
